    pub const @"SELECT a.action_id,a.parent_operation_id,a.call_ordinal,a.permission_revision,a.authorized,revision.permission_mode,@payload(call_name) AS tool_name,call_id.byte_length AS call_id_length,call_id.digest AS call_id_digest,arguments.byte_length AS arguments_length,arguments.digest AS arguments_digest,call_name.digest AS name_digest,(SELECT tool.server FROM model_tool_call tool_call JOIN content name ON name.content_id=tool_call.name_content_id JOIN tool_set_member member ON member.tool_set_id=operation.tool_set_id JOIN tool_record tool ON tool.tool_record_id=member.tool_record_id WHERE tool_call.operation_id=a.parent_operation_id AND tool_call.call_ordinal=a.call_ordinal AND @bytes(tool.name)=@payload(name) AND (tool.owner IN ('mcp'))) AS server,tool_call.description FROM action_operation a JOIN model_operation operation ON operation.operation_id=a.parent_operation_id JOIN turn active ON active.turn_id=operation.turn_id CROSS JOIN session_revision revision ON revision.session_ref=a.session_ref AND revision.revision=a.permission_revision CROSS JOIN model_tool_call tool_call ON tool_call.operation_id=a.parent_operation_id AND tool_call.call_ordinal=a.call_ordinal CROSS JOIN content call_id ON call_id.content_id=tool_call.call_id_content_id CROSS JOIN content arguments ON arguments.content_id=tool_call.arguments_content_id CROSS JOIN content call_name ON call_name.content_id=tool_call.name_content_id WHERE a.session_ref=?1 AND a.acceptance_position IS NULL AND a.resolution_code IS NULL ORDER BY a.action_id": rsql.TableEntry = .{ .variants = &.{.{ .signature = "r0:.:action_id,parent_operation_id,call_ordinal,permission_revision,authorized,permission_mode,tool_name,call_id_length,call_id_digest,arguments_length,arguments_digest,name_digest,server,description,", .sqlite = "SELECT a.action_id,a.parent_operation_id,a.call_ordinal,a.permission_revision,a.authorized,revision.permission_mode,call_name.payload AS tool_name,call_id.byte_length AS call_id_length,call