    pub const @"SELECT session.session_ref,session.archive_seq,session.parent_ref,session.creator_ref,session.workspace,session.provider,session.model,(SELECT @list(tool.name) FROM tool_set_member member JOIN tool_record tool ON tool.tool_record_id=member.tool_record_id WHERE member.tool_set_id=session.tool_set_id) AS tools,session.permission_mode,session.label,session.created_at,session.revision,session.next_position,CASE WHEN session.archive_seq IS NULL THEN 'active' WHEN EXISTS(SELECT 1 FROM core_command ac JOIN session_stop astop ON astop.command_key=ac.command_key LEFT JOIN turn aturn ON aturn.turn_id=astop.selected_turn_id WHERE ac.command_seq=session.archive_seq AND NOT ((astop.selected_turn_id IS NULL OR (aturn.outcome_position IS NOT NULL AND (NULL IS NULL OR aturn.outcome_position<=NULL))) AND NOT EXISTS(SELECT 1 FROM action_operation selected_action WHERE selected_action.session_ref=astop.session_ref AND selected_action.action_id<=astop.action_cutoff AND (selected_action.acceptance_position IS NULL OR (NULL IS NOT NULL AND selected_action.acceptance_position>NULL))))) THEN 'archiving' ELSE 'archived' END AS archive_state,(SELECT pin_command.command_seq FROM session_pin pin JOIN core_command pin_command ON pin_command.command_key=pin.command_key WHERE pin.session_ref=session.session_ref) AS pin_order,(SELECT admitted_at FROM message_admission @index(message_admission_person) WHERE session_ref=session.session_ref AND message_admission.source_kind=1 ORDER BY admission_position DESC LIMIT 1) AS from_person_at,last_turn.outcome_position AS last_turn_position,(SELECT substr(@payload(content),1,1024) FROM content WHERE content_id=last_turn.outcome_content_id AND private=0 AND last_turn.outcome_code='completed') AS last_answer,awaiting.approval_position AS last_approval_position,awaiting_call.description AS last_approval_text,awaiting.action_id AS first_awaiting_action,(SELECT COALESCE((SELECT e.recorded_at FROM conversation_entry e WHERE e.source_admission_id=t.