    pub const @"WITH context_session AS (SELECT ?1 AS session_ref,?2 AS boundary),base AS (SELECT candidate.operation_id,candidate.admission_position,candidate.history_floor,candidate.session_ref,candidate.settings_revision FROM context_session context JOIN model_operation candidate ON candidate.operation_id=(SELECT selected.operation_id FROM model_operation selected @index(model_operation_compaction_bases) WHERE selected.session_ref=context.session_ref AND selected.purpose=1 AND selected.resolution_code='compacted' AND selected.admission_position<context.boundary ORDER BY selected.admission_position DESC LIMIT 1)),since AS (SELECT NOT EXISTS(SELECT 1 FROM base WHERE NOT EXISTS(SELECT 1 FROM conversation_entry e WHERE e.session_ref=context.session_ref AND e.entry_kind IN (1,2,4) AND e.session_position>base.admission_position AND e.session_position<context.boundary) AND NOT EXISTS(SELECT 1 FROM model_output_item item @index(model_output_history) CROSS JOIN model_operation suffix ON suffix.operation_id=item.operation_id WHERE item.session_ref=context.session_ref AND suffix.session_ref=context.session_ref AND suffix.purpose=0 AND item.session_position>base.admission_position AND item.session_position<context.boundary)) AS changed FROM context_session context) SELECT since.changed,base.admission_position AS base_position,base.history_floor AS base_floor,base_revision.model AS base_model,(SELECT s.codec FROM session s WHERE s.session_ref=?1) AS codec,(SELECT r.model FROM model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision WHERE o.session_ref=?1 AND o.admission_position=?2) AS model FROM since LEFT JOIN base ON 1 LEFT JOIN session_revision base_revision ON base_revision.session_ref=base.session_ref AND base_revision.revision=base.settings_revision ": rsql.TableEntry = .{ .variants = &.{.{ .signature = "r0:..:changed,base_position,base_floor,base_model,codec,model,", .sqlite = "WITH context_session AS (SELECT ?1 AS session_ref,?2 AS boundary),base AS (SELECT candidate.operation_id,candidate.admission_position,candidate.history_floor,candidate.session_ref,candidate.settings_revision FROM context_session context JOIN model_operation candidate ON candidate.operation_id=(SELECT selected.operation_id FROM model_operation selected INDEXED BY model_operation_compaction_bases WHERE selected.session_ref=context.session_ref AND selected.purpose=1 AND selected.resolution_code='compacted' AND selected.admission_position<context.boundary ORDER BY selected.admission_position DESC LIMIT 1)),since AS (SELECT NOT EXISTS(SELECT 1 FROM base WHERE NOT EXISTS(SELECT 1 FROM conversation_entry e WHERE e.session_ref=context.session_ref AND e.entry_kind IN (1,2,4) AND e.session_position>base.admission_position AND e.session_position<context.boundary) AND NOT EXISTS(SELECT 1 FROM model_output_item item INDEXED BY model_output_history CROSS JOIN model_operation suffix ON suffix.operation_id=item.operation_id WHERE item.session_ref=context.session_ref AND suffix.session_ref=context.session_ref AND suffix.purpose=0 AND item.session_position>base.admission_position AND item.session_position<context.boundary)) AS changed FROM context_session context) SELECT since.changed,base.admission_position AS base_position,base.history_floor AS base_floor,base_revision.model AS base_model,(SELECT s.codec FROM session s WHERE s.session_ref=?1) AS codec,(SELECT r.model FROM model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision WHERE o.session_ref=?1 AND o.admission_position=?2) AS model FROM since LEFT JOIN base ON 1 LEFT JOIN session_revision base_revision ON base_revision.session_ref=base.session_ref AND base_revision.revision=base.settings_revision " }}, .mysql = .{ .parts = &.{ "WITH context_session AS (SELECT ", " AS session_ref,", " AS boundary),base AS (SELECT candidate.operation_id,candidate.admission_position,candidate.history_floor,candidate.session_ref,candid