epted ON action_operation(session_ref) WHERE acceptance_position IS NULL" }, .{ .kind = .index, .name = "action_operation_executable", .sql = "CREATE INDEX action_operation_executable ON action_operation(action_id) WHERE authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0" }, .{ .kind = .index, .name = "action_operation_unresolved_attempt", .sql = "CREATE INDEX action_operation_unresolved_attempt ON action_operation(action_id) WHERE resolution_code IS NULL AND attempt_ordinal=1" }, .{ .kind = .index, .name = "action_operation_indeterminate", .sql = "CREATE INDEX action_operation_indeterminate ON action_operation(session_ref,parent_operation_id,call_ordinal) WHERE resolution_code='indeterminate'" }, .{ .kind = .index, .name = "model_tool_call_session_order", .sql = "CREATE INDEX model_tool_call_session_order ON model_tool_call(session_ref,operation_id,call_ordinal)" }, .{ .kind = .index, .name = "model_tool_call_session_results", .sql = "CREATE INDEX model_tool_call_session_results ON model_tool_call(session_ref,operation_id,acceptance_position) WHERE acceptance_position IS NOT NULL" }, .{ .kind = .index, .name = "model_tool_call_acceptance", .sql = "CREATE INDEX model_tool_call_acceptance ON model_tool_call(session_ref,acceptance_position) WHERE acceptance_position IS NOT NULL" }, .{ .kind = .index, .name = "model_operation_retry_due", .sql = "CREATE INDEX model_operation_retry_due ON model_operation(retry_due_at_ms,operation_id) WHERE resolution_code IS NULL AND attempt_ordinal<4" }, .{ .kind = .index, .name = "model_operation_retry_exhausted", .sql = "CREATE INDEX model_operation_retry_exhausted ON model_operation(operation_id) WHERE resolution_code IS NULL AND retry_due_at_ms=0 AND attempt_ordinal=4" }, .{ .kind = .index, .name = "model_operation_session_history", .sql = "CREATE INDEX model_operation_session_history ON model_operation(session_ref,operation_id)" }, .{ .kind = .index, .name = "action_operation_background", .sql = "CREATE INDEX action_ope