ion_entry_history", .sql = "CREATE INDEX conversation_entry_history ON conversation_entry(session_ref,session_position)" }, .{ .kind = .index, .name = "model_output_history", .sql = "CREATE INDEX model_output_history ON model_output_item(session_ref,session_position)" }, .{ .kind = .index, .name = "model_output_call_history", .sql = "CREATE INDEX model_output_call_history ON model_output_item(session_ref,session_position) WHERE item_kind=3" }, .{ .kind = .index, .name = "model_output_hosted_history", .sql = "CREATE INDEX model_output_hosted_history ON model_output_item(session_ref,session_position) WHERE item_kind=5" }, .{ .kind = .index, .name = "model_output_compaction_history", .sql = "CREATE INDEX model_output_compaction_history ON model_output_item(session_ref,session_position) WHERE item_kind=4" }, .{ .kind = .index, .name = "model_output_compaction_anchor", .sql = "CREATE INDEX model_output_compaction_anchor ON model_output_item(operation_id,item_ordinal) WHERE item_kind=4" }, .{ .kind = .index, .name = "turn_session_latest", .sql = "CREATE INDEX turn_session_latest ON turn(session_ref,turn_id DESC)" }, .{ .kind = .index, .name = "turn_unpositioned", .sql = "CREATE INDEX turn_unpositioned ON turn(session_ref) WHERE (outcome_code IS NULL)!=(outcome_position IS NULL)" }, .{ .kind = .index, .name = "turn_outcome_unpositioned", .sql = "CREATE INDEX turn_outcome_unpositioned ON turn(session_ref) WHERE outcome_position IS NULL" }, .{ .kind = .index, .name = "turn_outcome_position", .sql = "CREATE INDEX turn_outcome_position ON turn(session_ref,outcome_position)" } };
    pub const mysql_objects: []const Object = &.{ .{ .kind = .table, .name = "store_meta", .sql = "CREATE TABLE store_meta(\x0a meta_key VARCHAR(14) NOT NULL,\x0a meta_value LONGTEXT NOT NULL,\x0a PRIMARY KEY(meta_key),\x0a CHECK((meta_key='wire_version' OR meta_key='store_selector' OR meta_key='format' OR meta_key='store_id'))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "store_owner", .sql = "CREATE TABLE store_owner(\x0a owner_key BIGINT NOT NULL,\x0a epoch BIGINT NOT NULL,\x0a commit_seq BIGINT NOT NULL,\x0a PRIMARY KEY(owner_key),\x0a CHECK(owner_key=1),\x0a CHECK(epoch>=0),\x0a CHECK(commit_seq>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "content", .sql = "CREATE TABLE content(\x0a content_id BIGINT NOT NULL,\x0a digest VARBINARY(32) NOT NULL,\x0a byte_length BIGINT NOT NULL,\x0a private TINYINT NOT NULL,\x0a form BIGINT NOT NULL DEFAULT 0,\x0a PRIMARY KEY(content_id),\x0a UNIQUE(digest,byte_length,private),\x0a CHECK(length(digest)=32),\x0a CHECK(byte_length>=0 AND byte_length<=1073737728),\x0a CHECK(private IN (0,1)),\x0a CHECK(form IN (0,1) AND (form=0 OR private=0))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "content_chunk", .sql = "CREATE TABLE content_chunk(\x0a content_id BIGINT NOT NULL,\x0a chunk_index BIGINT NOT NULL,\x0a bytes LONGBLOB NOT NULL,\x0a PRIMARY KEY(content_id,chunk_index),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a CHECK(chunk_index>=0),\x0a CHECK(length(bytes) BETWEEN 1 AND 131072)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "content_part", .sql = "CREATE TABLE content_part(\x0a content_id BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a part_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(content_id,ordinal),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(part_content_id) REFERENCES content(content_id),\x0a CHECK(ordinal>=0),\x0a CHECK(part_content_id<>content_id)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "tool_record", .sql = "CREATE TABLE tool_record(\x0a tool_record_id BIGINT NOT NULL,\x0a name VARCHAR(64) NOT NULL,\x0a remote_name VARCHAR(64) NOT NULL,\x0a owner VARCHAR(8) NOT NULL,\x0a server VARCHAR(64) NOT NULL,\x0a replay VARCHAR(6) NOT NULL,\x0a restart_limit BIGINT NOT NULL,\x0a wait_ms BIGINT NOT NULL,\x0a description_content_id BIGINT NOT NULL,\x0a input_schema_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(tool_record_id),\x0a UNIQUE(name,remote_name,owner,server,replay,restart_limit,wait_ms,description_content_id,input_schema_content_id),\x0a FOREIGN KEY(description_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(input_schema_content_id) REFERENCES content(content_id),\x0a CHECK(tool_record_id>0),\x0a CHECK(OCTET_LENGTH(name) BETWEEN 1 AND 64 AND (NOT REGEXP_LIKE(name,'[^A-Za-z0-9_-]','c'))),\x0a CHECK(OCTET_LENGTH(remote_name)<=64 AND (NOT REGEXP_LIKE(remote_name,'[^A-Za-z0-9_-]','c'))),\x0a CHECK((owner='rui' OR owner='provider' OR owner='mcp' OR owner='app')),\x0a CHECK(OCTET_LENGTH(server)<=64 AND (NOT REGEXP_LIKE(server,'[^A-Za-z0-9_-]','c')) AND (owner='mcp' AND OCTET_LENGTH(server)>0 OR owner<>'mcp' AND OCTET_LENGTH(server)=0)),\x0a CHECK(OCTET_LENGTH(replay)<=6 AND replay IN ('','unsafe','safe') AND (owner='app' AND replay<>'' OR owner<>'app' AND replay='')),\x0a CHECK((owner='app' AND restart_limit BETWEEN 0 AND 16 OR owner<>'app' AND restart_limit=0)),\x0a CHECK((owner='app' AND wait_ms BETWEEN 1000 AND 3600000 OR owner<>'app' AND wait_ms=0)),\x0a CHECK(replay<>'unsafe' OR restart_limit=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "tool_set", .sql = "CREATE TABLE tool_set(\x0a tool_set_id BIGINT NOT NULL,\x0a digest VARBINARY(32) NOT NULL,\x0a member_count BIGINT NOT NULL,\x0a PRIMARY KEY(tool_set_id),\x0a UNIQUE(digest),\x0a CHECK(tool_set_id>0),\x0a CHECK(length(digest)=32),\x0a CHECK(member_count BETWEEN 0 AND 1024)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "tool_set_member", .sql = "CREATE TABLE tool_set_member(\x0a tool_set_id BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a tool_record_id BIGINT NOT NULL,\x0a PRIMARY KEY(tool_set_id,ordinal),\x0a FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(tool_record_id) REFERENCES tool_record(tool_record_id),\x0a CHECK(ordinal>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "host_tool_set", .sql = "CREATE TABLE host_tool_set(\x0a slot BIGINT NOT NULL,\x0a tool_set_id BIGINT NOT NULL,\x0a PRIMARY KEY(slot),\x0a FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id),\x0a CHECK(slot=1)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "model_fact", .sql = "CREATE TABLE model_fact(\x0a model_id VARCHAR(256) NOT NULL,\x0a context_window BIGINT,\x0a efforts BIGINT NOT NULL,\x0a openai_listed TINYINT NOT NULL,\x0a generation BIGINT NOT NULL,\x0a output_limit BIGINT,\x0a PRIMARY KEY(model_id),\x0a CHECK(OCTET_LENGTH(model_id) BETWEEN 1 AND 256),\x0a CHECK(efforts BETWEEN 0 AND 63),\x0a CHECK(openai_listed IN (0,1)),\x0a CHECK(output_limit IS NULL OR output_limit BETWEEN 0 AND 4294967295)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "model_catalog_source", .sql = "CREATE TABLE model_catalog_source(\x0a slot BIGINT NOT NULL,\x0a etag TEXT,\x0a generation BIGINT NOT NULL,\x0a fetched_at BIGINT NOT NULL,\x0a PRIMARY KEY(slot),\x0a CHECK(slot=1),\x0a CHECK(etag IS NULL OR OCTET_LENGTH(etag)<=512)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "session", .sql = "CREATE TABLE session(\x0a session_ref VARCHAR(6) NOT NULL,\x0a workspace TEXT NOT NULL,\x0a provider TEXT NOT NULL,\x0a codec TEXT NOT NULL,\x0a codec_options BLOB,\x0a prefix_seal BLOB,\x0a model TEXT NOT NULL,\x0a instructions_content_id BIGINT NOT NULL,\x0a tool_set_id BIGINT NOT NULL,\x0a loaded_tool_set_id BIGINT,\x0a permission_mode BIGINT NOT NULL,\x0a output_schema_content_id BIGINT,\x0a revision BIGINT NOT NULL,\x0a compaction_trigger BIGINT,\x0a output_reservation BIGINT,\x0a reasoning_effort VARCHAR(6),\x0a label TEXT,\x0a created_at BIGINT NOT NULL,\x0a next_position BIGINT NOT NULL,\x0a created_seq BIGINT NOT NULL,\x0a workspace_digest VARBINARY(32) NOT NULL,\x0a workspace_key BIGINT NOT NULL,\x0a parent_ref VARCHAR(6),\x0a obligation_since BIGINT,\x0a creator_ref VARCHAR(6),\x0a archive_seq BIGINT,\x0a session_obligation_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN obligation_since IS NOT NULL THEN parent_ref END) STORED,\x0a session_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN parent_ref IS NOT NULL THEN parent_ref END) STORED,\x0a PRIMARY KEY(session_ref),\x0a UNIQUE(created_seq),\x0a FOREIGN KEY(instructions_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(loaded_tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(output_schema_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(parent_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(creator_ref) REFERENCES session(session_ref),\x0a CHECK(OCTET_LENGTH(session_ref)=6 AND (NOT REGEXP_LIKE(session_ref,'[^0123456789abcdefghjkmnpqrstvwxyz]','c'))),\x0a CHECK(OCTET_LENGTH(workspace) BETWEEN 1 AND 4096),\x0a CHECK(OCTET_LENGTH(provider) BETWEEN 1 AND 16 AND REGEXP_LIKE(provider,'^[a-z]','c') AND (NOT REGEXP_LIKE(provider,'[^a-z0-9_-]','c'))),\x0a CHECK(OCTET_LENGTH(codec) BETWEEN 3 AND 40),\x0a CHECK(codec_options IS NULL OR length(codec_options) BETWEEN 1 AND 512),\x0a CHECK(prefix_seal IS NULL OR length(prefix_seal)=56),\x0a CHECK(OCTET_LENGTH(model) BETWEEN 1 AND 256),\x0a CHECK(tool_set_id>0),\x0a CHECK(permission_mode BETWEEN 0 AND 1),\x0a CHECK(revision>0),\x0a CHECK(compaction_trigger IS NULL OR compaction_trigger>0),\x0a CHECK(output_reservation IS NULL OR output_reservation>=0),\x0a CHECK(reasoning_effort IS NULL OR (reasoning_effort='none' OR reasoning_effort='low' OR reasoning_effort='medium' OR reasoning_effort='high' OR reasoning_effort='xhigh' OR reasoning_effort='max')),\x0a CHECK(label IS NULL OR OCTET_LENGTH(label) BETWEEN 1 AND 100),\x0a CHECK(created_at>0),\x0a CHECK(next_position>0),\x0a CHECK(created_seq>0),\x0a CHECK(length(workspace_digest)=32),\x0a CHECK(obligation_since IS NULL OR obligation_since>0),\x0a CHECK(creator_ref IS NULL OR creator_ref<>session_ref),\x0a CHECK(archive_seq IS NULL OR archive_seq>0),\x0a CHECK(workspace_key>0 AND workspace_key<=created_seq),\x0a CHECK(parent_ref IS NULL OR parent_ref<>session_ref)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "core_command", .sql = "CREATE TABLE core_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a kind BIGINT NOT NULL,\x0a target VARCHAR(128) NOT NULL,\x0a input_digest BLOB NOT NULL,\x0a primary_content_id BIGINT,\x0a secondary_content_id BIGINT,\x0a accepted TINYINT NOT NULL,\x0a code TEXT NOT NULL,\x0a revision BIGINT NOT NULL,\x0a created TINYINT NOT NULL,\x0a command_seq BIGINT NOT NULL,\x0a missing_settings BIGINT,\x0a PRIMARY KEY(command_seq),\x0a UNIQUE(command_key),\x0a FOREIGN KEY(primary_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(secondary_content_id) REFERENCES content(content_id),\x0a CHECK(OCTET_LENGTH(command_key)<=128),\x0a CHECK(kind BETWEEN 1 AND 9),\x0a CHECK(OCTET_LENGTH(target)<=128),\x0a CHECK(length(input_digest)=32),\x0a CHECK(accepted IN (0,1)),\x0a CHECK(OCTET_LENGTH(code)<=96),\x0a CHECK(revision>=0),\x0a CHECK(created IN (0,1)),\x0a CHECK(command_seq>0),\x0a CHECK(missing_settings IS NULL AND code<>'missing_settings' OR missing_set