 ALWAYS AS (CASE WHEN item_kind=4 THEN session_ref END) STORED,\x0a model_output_compaction_anchor_lead BIGINT GENERATED ALWAYS AS (CASE WHEN item_kind=4 THEN operation_id END) STORED,\x0a PRIMARY KEY(operation_id,item_ordinal),\x0a UNIQUE(session_ref,session_position),\x0a UNIQUE(operation_id,item_id_digest),\x0a FOREIGN KEY(operation_id) REFERENCES model_operation(operation_id),\x0a FOREIGN KEY(message_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(extras_content_id) REFERENCES content(content_id),\x0a CHECK(item_ordinal>=0),\x0a CHECK(session_position>0),\x0a CHECK(item_kind BETWEEN 1 AND 5),\x0a CHECK((message_content_id IS NOT NULL)=(item_kind=2)),\x0a CHECK(attempt_ordinal>0),\x0a CHECK(length(item_id_digest)=32),\x0a CHECK(replay_omits_reasoning_text IN (0,1) AND (replay_omits_reasoning_text=0 OR item_kind=1)),\x0a CHECK(phase IN (0,1,2) AND (phase=0 OR item_kind=2)),\x0a CHECK(part_count>=0 AND (part_count=0 OR item_kind IN (1,2))),\x0a CHECK(description IS NULL OR (OCTET_LENGTH(description) BETWEEN 1 AND 200 AND (description IS NOT NULL)=(item_kind=5))),\x0a CHECK(call_failed IN (0,1) AND (call_failed=0 OR item_kind=5))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "model_output_part", .sql = "CREATE TABLE model_output_part(\x0a operation_id BIGINT NOT NULL,\x0a item_ordinal BIGINT NOT NULL,\x0a part_ordinal BIGINT NOT NULL,\x0a part_array BIGINT NOT NULL,\x0a part_kind BIGINT NOT NULL,\x0a text_length BIGINT,\x0a text_content_id BIGINT,\x0a extras_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(operation_id,item_ordinal,part_ordinal),\x0a FOREIGN KEY(text_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(extras_content_id) REFERENCES content(content_id),\x0a CHECK(part_ordinal>=0),\x0a CHECK(part_array IN (1,2)),\x0a CHECK(part_kind=0 OR (part_kind IN (1,2,4) AND part_array=1) OR (part_kind=3 AND part_array=2)),\x0a CHECK(text_length IS NULL OR text_length>=0),\x0a CHECK((text_length IS NOT NULL)=(part_kind IN (1,2)) AND (text_content_id IS NOT NULL)=(part_kind IN (3,4)))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "model_tool_call", .sql = "CREATE TABLE model_tool_call(\x0a operation_id BIGINT NOT NULL,\x0a session_ref VARCHAR(6) NOT NULL,\x0a call_ordinal BIGINT NOT NULL,\x0a item_ordinal BIGINT NOT NULL,\x0a name_content_id BIGINT NOT NULL,\x0a call_id_content_id BIGINT NOT NULL,\x0a arguments_content_id BIGINT NOT NULL,\x0a description TEXT,\x0a field_metadata BLOB NOT NULL,\x0a rejection_code VARCHAR(17),\x0a rejection_content_id BIGINT,\x0a acceptance_position BIGINT,\x0a action_kind BIGINT,\x0a model_tool_call_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED,\x0a model_tool_call_acceptance_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED,\x0a PRIMARY KEY(operation_id,call_ordinal),\x0a UNIQUE(operation_id,item_ordinal),\x0a UNIQUE(operation_id,call_id_content_id),\x0a UNIQUE(operation_id,call_ordinal,action_kind),\x0a FOREIGN KEY(operation_id) REFERENCES model_operation(operation_id),\x0a FOREIGN KEY(operation_id,session_ref) REFERENCES model_operation(operation_id,session_ref),\x0a FOREIGN KEY(name_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(call_id_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(arguments_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(rejection_content_id) REFERENCES content(content_id),\x0a CHECK(call_ordinal>=0),\x0a CHECK(item_ordinal>=0),\x0a CHECK(description IS NULL OR OCTET_LENGTH(description) BETWEEN 1 AND 200),\x0a CHECK(length(field_metadata)=120),\x0a CHECK(rejection_code IS NULL OR rejection_code IN ('unknown_tool','invalid_arguments')),\x0a CHECK(acceptance_position IS NULL OR acceptance_position>0),\x0a CHECK(action_kind IS NULL OR action_kind=1),\x0a CHECK((rejection_code IS NULL AND rejection_content_id IS NULL AND acceptance_position IS NULL AND (action_kind <=> 1)) OR (rejection_code IS NOT NULL AND rejection_content_id IS NOT NULL AND acceptance_position IS NOT NULL AND action_kind IS NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "action_operation", .sql = "CREATE TABLE action_operation(\x0a action_id BIGINT NOT NULL,\x0a parent_operation_id BIGINT NOT NULL,\x0a call_ordinal BIGINT NOT NULL,\x0a session_ref VARCHAR(6) NOT NULL,\x0a tool_kind BIGINT NOT NULL,\x0a permission_revision BIGINT NOT NULL,\x0a authorized TINYINT NOT NULL,\x0a attempt_ordinal BIGINT NOT NULL DEFAULT 0,\x0a bash_timeout_override_ms BIGINT,\x0a attempt_timeout_ms BIGINT,\x0a sender_handle VARCHAR(32),\x0a resolution_code VARCHAR(23),\x0a resolution_content_id BIGINT,\x0a acceptance_position BIGINT,\x0a attempt_at BIGINT,\x0a decided_at BIGINT,\x0a resolved_at BIGINT,\x0a approval_position BIGINT,\x0a background_content_id BIGINT,\x0a background_position BIGINT,\x0a background_at BIGINT,\x0a action_operation_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL AND background_position IS NULL THEN session_ref END) STORED,\x0a action_operation_approval_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN approval_position IS NOT NULL THEN session_ref END) STORED,\x0a action_operation_unaccepted_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NULL THEN session_ref END) STORED,\x0a action_operation_executable_lead BIGINT GENERATED ALWAYS AS (CASE WHEN authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0 THEN action_id END) STORED,\x0a action_operation_unresolved_attempt_lead BIGINT GENERATED ALWAYS AS (CASE WHEN resolution_code IS NULL AND attempt_ordinal=1 THEN action_id END) STORED,\x0a action_operation_indeterminate_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN resolution_code='indeterminate' THEN session_ref END) STORED,\x0a action_operation_background_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL THEN session_ref END) STORED,\x0a action_operation_background_ready_lead BIGINT GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL AND authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0 THEN parent_operation_id END) STORED,\x0a action_operation_awaiting_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN authorized=0 AND resolution_code IS NULL THEN session_ref END) STORED,\x0a PRIMARY KEY(action_id),\x0a UNIQUE(parent_operation_id,call_ordinal),\x0a FOREIGN KEY(parent_operation_id) REFERENCES model_operation(operation_id),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(resolution_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(background_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(parent_operation_id,session_ref) REFERENCES model_operation(operation_id,session_ref),\x0a FOREIGN KEY(parent_operation_id,call_ordinal,tool_kind) REFERENCES model_tool_call(operation_id,call_ordinal,action_kind),\x0a FOREIGN KEY(session_ref,permission_revision) REFERENCES session_revision(session_ref,revision),\x0a CHECK(action_id>0),\x0a CHECK(call_ordinal>=0),\x0a CHECK(tool_kind=1),\x0a CHECK(permission_revision>0),\x0a CHECK(authorized IN (0,1)),\x0a CHECK(attempt_ordinal IN (0,1)),\x0a CHECK(bash_timeout_override_ms IS NULL OR bash_timeout_override_ms>0),\x0a CHECK(attempt_timeout_ms IS NULL OR attempt_timeout_ms>0),\x0a CHECK(sender_handle IS NULL OR (OCTET_LENGTH(sender_handle)=32 AND (NOT REGEXP_LIKE(sender_handle,'[^0-9a-f]','c')))),\x0a CHECK(resolution_code IS NULL OR (resolution_code='denied' OR resolution_code='cancelled' OR resolution_code='succeeded' OR resolution_code='failed' OR resolution_code='timed_out' OR resolution_code='indeterminate' OR resolution_code='storage_failed' OR resolution_code='spawn_failed' OR resolution_code='infrastructure_shutdown')),\x0a CHECK(acceptance_position IS NULL OR acceptance_position>0),\x0a CHECK(attempt_at IS NULL OR attempt_at>0),\x0a CHECK(decided_at IS NULL OR decided_at>0),\x0a CHECK(resolved_at IS NULL OR resolved_at>0),\x0a CHECK(approval_position IS NULL OR approval_position>0),\x0a CHECK((background_content_id IS NULL AND background_position IS NULL) OR (background_content_id IS NOT NULL AND background_position IS NOT NULL AND background_position>0 AND (acceptance_position IS NULL OR background_position<acceptance_position))),\x0a CHECK((background_position IS NULL AND background_at IS NULL) OR (background_position IS NOT NULL AND background_at IS NOT NULL AND background_at>0)),\x0a CHECK((NOT (resolution_code <=> 'denied')) OR (authorized=0 AND attempt_ordinal=0)),\x0a CHECK((attempt_ordinal=0 AND attempt_timeout_ms IS NULL) OR (attempt_ordinal=1 AND attempt_timeout_ms IS NOT NULL)),\x0a CHECK((resolution_code IS NULL AND resolution_content_id IS NULL AND acceptance_position IS NULL) OR (resolution_code IS NOT NULL AND resolution_content_id IS NOT NULL AND acceptance_position IS NOT NULL)),\x0a CHECK((attempt_ordinal=1)=(attempt_at IS NOT NULL)),\x0a CHECK((authorized=1)=(decided_at IS NOT NULL)),\x0a CHECK((resolution_code IS NULL)=(resolved_at IS NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "permission_decision_command", .sql = "CREATE TABLE permission_decision_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a action_id TEXT NOT NULL,\x0a decision VARCHAR(10) NOT NULL,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(OCTET_LENGTH(action_id) BETWEEN 1 AND 20 AND (NOT REGEXP_LIKE(action_id,'[^0-9]','c'))),\x0a CHECK(decision IN ('allow_once','deny'))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin" }, .{ .kind = .table, .name = "action_stop", .sql = "CREATE TABLE action_stop(\x0a stop_key VARCHAR(130) NOT NULL,\x0a source_action_id BIGINT,\x0a source_command_key VARCHAR(128)