n(action_operation_background_ready_lead,action_id)" }, .{ .kind = .index, .name = "action_operation_awaiting", .sql = "CREATE INDEX action_operation_awaiting ON action_operation(action_operation_awaiting_lead,action_id)" }, .{ .kind = .index, .name = "model_operation_turn_history", .sql = "CREATE INDEX model_operation_turn_history ON model_operation(turn_id,operation_id)" }, .{ .kind = .index, .name = "session_change_refused_operation", .sql = "CREATE INDEX session_change_refused_operation ON session_change(refused_operation_id,session_ref,revision)" }, .{ .kind = .index, .name = "model_operation_effort_source", .sql = "CREATE UNIQUE INDEX model_operation_effort_source ON model_operation(operation_id,session_ref,effort_source_revision)" }, .{ .kind = .index, .name = "model_operation_admission", .sql = "CREATE INDEX model_operation_admission ON model_operation(session_ref,admission_position)" }, .{ .kind = .index, .name = "model_operation_context_history", .sql = "CREATE INDEX model_operation_context_history ON model_operation(model_operation_context_history_lead,admission_position)" }, .{ .kind = .index, .name = "model_operation_compaction_bases", .sql = "CREATE INDEX model_operation_compaction_bases ON model_operation(model_operation_compaction_bases_lead,admission_position)" }, .{ .kind = .index, .name = "conversation_entry_history", .sql = "CREATE INDEX conversation_entry_history ON conversation_entry(session_ref,session_position)" }, .{ .kind = .index, .name = "model_output_history", .sql = "CREATE INDEX model_output_history ON model_output_item(session_ref,session_position)" }, .{ .kind = .index, .name = "model_output_call_history", .sql = "CREATE INDEX model_output_call_history ON model_output_item(model_output_call_history_lead,session_position)" }, .{ .kind = .index, .name = "model_output_hosted_history", .sql = "CREATE INDEX model_output_hosted_history ON model_output_item(model_output_hosted_history_lead,session_position)" }, .{ .kind = .index, .name = "model_output_compaction_history", .sql = "CREATE INDEX model_output_compaction_history ON model_output_item(model_output_compaction_history_lead,session_position)" }, .{ .kind = .index, .name = "model_output_compaction_anchor", .sql = "CREATE INDEX model_output_compaction_anchor ON model_output_item(model_output_compaction_anchor_lead,item_ordinal)" }, .{ .kind = .index, .name = "turn_session_latest", .sql = "CREATE INDEX turn_session_latest ON turn(session_ref,turn_id DESC)" }, .{ .kind = .index, .name = "turn_unpositioned", .sql = "CREATE INDEX turn_unpositioned ON turn(turn_unpositioned_lead)" }, .{ .kind = .index, .name = "turn_outcome_unpositioned", .sql = "CREATE INDEX turn_outcome_unpositioned ON turn(turn_outcome_unpositioned_lead)" }, .{ .kind = .index, .name = "turn_outcome_position", .sql = "CREATE INDEX turn_outcome_position ON turn(session_ref,outcome_position)" }, .{ .kind = .foreign_key, .name = "session(archive_seq)", .sql = "ALTER TABLE session ADD FOREIGN KEY(archive_seq) REFERENCES core_command(command_seq)" }, .{ .kind = .foreign_key, .name = "session_change(refused_operation_id,session_ref,revision)", .sql = "ALTER TABLE session_change ADD FOREIGN KEY(refused_operation_id,session_ref,revision) REFERENCES model_operation(operation_id,session_ref,effort_source_revision)" }, .{ .kind = .foreign_key, .name = "message_admission(turn_id)", .sql = "ALTER TABLE message_admission ADD FOREIGN KEY(turn_id) REFERENCES turn(turn_id)" }, .{ .kind = .foreign_key, .name = "message_admission(source_action_id)", .sql = "ALTER TABLE message_admission ADD FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id)" }, .{ .kind = .foreign_key, .name = "action_value(action_id)", .sql = "ALTER TABLE action_value ADD FOREIGN KEY(action_id) REFERENCES action_operation(action_id)" }, .{ .kind = .foreign_key, .name = "conversation_entry(source_operation_id,source_item_ordinal)", .sql = "ALTER TABLE conversation_entry ADD FOREIGN KEY(source_operation_id,source_item_ordinal) REFERENCES model_output_item(operation_id,item_ordinal)" } };
    pub const sqlite_ddl = "CREATE TABLE store_meta(\x0a meta_key TEXT PRIMARY KEY NOT NULL CHECK((meta_key='wire_version' OR meta_key='store_selector' OR meta_key='format' OR meta_key='store_id')),\x0a meta_value TEXT NOT NULL\x0a) STRICT;\x0aCREATE TABLE content(\x0a content_id INTEGER PRIMARY KEY NOT NULL,\x0a digest BLOB NOT NULL CHECK(length(digest)=32),\x0a byte_length INTEGER NOT NULL CHECK(byte_length>=0 AND byte_length<=1073737728),\x0a private INTEGER NOT NULL CHECK(private IN (0,1)),\x0a payload BLOB NOT NULL CHECK(length(payload)=byte_length), form INTEGER NOT NULL DEFAULT 0 CHECK(form IN (0,1) AND (form=0 OR private=0)),\x0a UNIQUE(digest,byte_length,private)\x0a) STRICT;\x0aCREATE TABLE content_part(\x0a content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a ordinal INTEGER NOT NULL CHECK(ordinal>=0),\x0a part_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a PRIMARY KEY(content_id,ordinal),\x0a CHECK(part_content_id<>content_id)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE tool_record(\x0a tool_record_id INTEGER PRIMARY KEY NOT NULL CHECK(tool_record_id>0),\x0a name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) BETWEEN 1 AND 64 AND (name NOT GLOB '*[^A-Za-z0-9_-]*' AND length(name)=length(CAST(name AS BLOB)))),\x0a remote_name TEXT NOT NULL CHECK(length(CAST(remote_name AS BLOB))<=64 AND (remote_name NOT GLOB '*[^A-Za-z0-9_-]*' AND length(remote_name)=length(CAST(remote_name AS BLOB)))),\x0a owner TEXT NOT NULL CHECK((owner='rui' OR owner='provider' OR owner='mcp' OR owner='app')),\x0a server TEXT NOT NULL CHECK(length(CAST(server AS BLOB))<=64 AND (server NOT GLOB '*[^A-Za-z0-9_-]*' AND length(server)=length(CAST(server AS BLOB))) AND (owner='mcp' AND length(CAST(server AS BLOB))>0 OR owner<>'mcp' AND length(CAST(server AS BLOB))=0)),\x0a replay TEXT NOT NULL CHECK(length(CAST(replay AS BLOB))<=6 AND replay IN ('','unsafe','safe') AND (owner='app' AND replay<>'' OR owner<>'app' AND replay='')),\x0a restart_limit INTEGER NOT NULL CHECK((owner='app' AND restart_limit BETWEEN 0 AND 16 OR owner<>'app' AND restart_limit=0)),\x0a wait_ms INTEGER NOT NULL CHECK((owner='app' AND wait_ms BETWEEN 1000 AND 3600000 OR owner<>'app' AND wait_ms=0)),\x0a description_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a input_schema_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a UNIQUE(name,remote_name,owner,server,replay,restart_limit,wait_ms,description_content_id,input_schema_content_id),\x0a CHECK(replay<>'unsafe' OR restart_limit=0)\x0a) STRICT;\x0aCREATE TABLE tool_set(\x0a tool_set_id INTEGER PRIMARY KEY NOT NULL CHECK(tool_set_id>0),\x0a digest BLOB NOT NULL UNIQUE CHECK(length(digest)=32),\x0a member_count INTEGER NOT NULL CHECK(member_count BETWEEN 0 AND 1024)\x0a) STRICT;\x0aCREATE TABLE tool_set_member(\x0a tool_set_id INTEGER NOT NULL REFERENCES tool_set(tool_set_id),\x0a ordinal INTEGER NOT NULL CHECK(ordinal>=0),\x0a tool_record_id INTEGER NOT NULL REFERENCES tool_record(tool_record_id),\x0a PRIMARY KEY(tool_set_id,ordinal)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE host_tool_set(\x0a slot INTEGER PRIMARY KEY NOT NULL CHECK(slot=1),\x0a tool_set_id INTEGER NOT NULL REFERENCES tool_set(tool_set_id)\x0a) STRICT;\x0aCREATE TABLE model_fact(\x0a model_id TEXT PRIMARY KEY NOT NULL CHECK(length(CAST(model_id AS BLOB)) BETWEEN 1 AND 256),\x0a context_window INTEGER,\x0a efforts INTEGER NOT NULL CHECK(efforts BETWEEN 0 AND 63),\x0a openai_listed INTEGER NOT NULL CHECK(openai_listed IN (0,1)),\x0a generation INTEGER NOT NULL,\x0a output_limit INTEGER CHECK(output_limit IS NULL OR output_limit BETWEEN 0 AND 4294967295)\x0a) STRICT;\x0aCREATE TABLE model_catalog_source(\x0a slot INTEGER PRIMARY KEY NOT NULL CHECK(slot=1),\x0a etag TEXT CHECK(etag IS NULL OR length(CAST(etag AS BLOB))<=512),\x0a generation INTEGER NOT NULL,\x0a fetched_at INTEGER NOT NULL\x0a) STRICT;\x0aCREATE TABLE session(\x0a session_ref TEXT PRIMARY KEY NOT NULL CHECK(length(CAST(session_ref AS BLOB))=6 AND (session_ref NOT GLOB '*[^0123456789abcdefghjkmnpqrstvwxyz]*' AND length(session_ref)=length(CAST(session_ref AS BLOB)))),\x0a workspace TEXT NOT NULL CHECK(length(CAST(workspace AS BLOB)) BETWEEN 1 AND 4096),\x0a provider TEXT NOT NULL CHECK(length(CAST(provider AS BLOB)) BETWEEN 1 AND 16 AND provider GLOB '[a-z]*' AND (provider NOT GLOB '*[^a-z0-9_-]*' AND length(provider)=length(CAST(provider AS BLOB)))),\x0a codec TEXT NOT NULL CHECK(length(CAST(codec AS BLOB)) BETWEEN 3 AND 40),\x0a codec_options BLOB CHECK(codec_options IS NULL OR length(codec_options) BETWEEN 1 AND 512),\x0a prefix_seal BLOB CHECK(prefix_seal IS NULL OR length(prefix_seal)=56),\x0a model TEXT NOT NULL CHECK(length(CAST(model AS BLOB)) BETWEEN 1 AND 256),\x0a instructions_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a tool_set_id INTEGER NOT NULL REFERENCES tool_set(tool_set_id) CHECK(tool_set_id>0),\x0a loaded_tool_set_id INTEGER REFERENCES tool_set(tool_set_id),\x0a permission_mode INTEGER NOT NULL CHECK(permission_mode BETWEEN 0 AND 1),\x0a output_schema_content_id INTEGER REFERENCES content(content_id),\x0a revision INTEGER NOT NULL CHECK(revision>0),\x0a compaction_trigger INTEGER CHECK(compaction_trigger IS NULL OR compaction_trigger>0),\x0a output_reservation INTEGER CHECK(output_reservation IS NULL OR output_reservation>=0),\x0a reasoning_effort TEXT CHECK(reasoning_effort IS NULL OR (reasoning_effort='none' OR reasoning_effort='low' OR reasoning_effort='medium' OR reasoning_effort='high' OR reasoning_effort='xhigh' OR reasoning_effort='max')),\x0a label TEXT CHECK(label IS NULL OR length(CAST(label AS BLOB)) BETWEEN 1 AND 100),\x0a created_at INTEGER NOT NULL CHECK(created_at>0),\x0a next_position INTEGER NOT NULL CHECK(next_position>0),\x0a created_seq INTEGER NOT NULL UNIQUE CHECK(created_seq>0),\x0a workspace_digest BLOB NOT NULL CHECK(length(workspace_digest)=32),\x0a workspace_key INTEGER NOT NULL,\x0a parent_ref TEXT REFERENCES session(session_ref), obligation_since INTEGER CHECK(obligation_since IS NULL OR obligation_since>0), creator_ref TEXT REFERENCES session(session_ref) CHECK(creator_ref IS NULL OR creator_ref<>session_ref), archive_seq INTEGER REFERENCES core_command(command_seq) CHECK(archive_seq IS NULL OR archive_seq>0),\x0a CHECK(workspace_key>0 AND workspace_key<=created_seq),\x0a CHECK(parent_ref IS NULL OR parent_ref<>session_ref)\x0a) STRICT;\x0aCREATE TABLE core_command(\x0a command_key TEXT NOT NULL UNIQUE CHECK(length(CAST(command_key AS BLOB))<=128),\x0a kind INTEGER NOT NULL CHECK(kind BETWEEN 1 AND 9),\x0a target TEXT NOT NULL CHECK(length(CAST(target AS BLOB))<=128),\x0a input_digest BLOB NOT NULL CHECK(length(input_digest)=32),\x0a primary_content_id INTEGER REFERENCES content(content_id),\x0a secondary_content_id INTEGER REFERENCES content(content_id),\x0a accepted INTEGER NOT NULL CHECK(accepted IN (0,1)),\x0a code TEXT NOT NULL CHECK(length(CAST(code AS BLOB))<=96),\x0a revision INTEGER NOT NULL CHECK(revision>=0),\x0a created INTEGER NOT NULL CHECK(created IN (0,1)),\x0a command_seq INTEGER PRIMARY KEY NOT NULL CHECK(command_seq>0),\x0a missing_settings INTEGER CHECK(missing_settings IS NULL AND code<>'missing_settings' OR missing_settings IS NOT NULL AND code='missing_settings' AND missing_settings BETWEEN 1 AND 7)\x0a) STRICT;\x0aCREATE TABLE session_revision(\x0a session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a revision INTEGER NOT NULL CHECK(revision>0),\x0a command_key TEXT NOT NULL UNIQUE REFERENCES core_command(command_key),\x0a workspace TEXT NOT NULL,\x0a provider TEXT NOT NULL CHECK(length(CAST(provider AS BLOB)) BETWEEN 1 AND 16 AND provider GLOB '[a-z]*' AND (provider NOT GLOB '*[^a-z0-9_-]*' AND length(provider)=length(CAST(provider AS BLOB)))),\x0a model TEXT NOT NULL,\x0a instructions_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a instructions_updated INTEGER NOT NULL CHECK(instructions_updated IN (0,1)),\x0a tool_set_id INTEGER NOT NULL REFERENCES tool_set(tool_set_id) CHECK(tool_set_id>0),\x0a loaded_tool_set_id INTEGER REFERENCES tool_set(tool_set_id),\x0a permission_mode INTEGER NOT NULL CHECK(permission_mode BETWEEN 0 AND 1),\x0a output_schema_content_id INTEGER REFERENCES content(content_id),\x0a compaction_trigger INTEGER CHECK(compaction_trigger IS NULL OR compaction_trigger>0),\x0a output_reservation INTEGER CHECK(output_reservation IS NULL OR output_reservation>=0),\x0a reasoning_effort TEXT CHECK(reasoning_effort IS NULL OR (reasoning_effort='none' OR reasoning_effort='low' OR reasoning_effort='medium' OR reasoning_effort='high' OR reasoning_effort='xhigh' OR reasoning_effort='max')),\x0a label TEXT CHECK(label IS NULL OR length(CAST(label AS BLOB)) BETWEEN 1 AND 100),\x0a effort_source_revision INTEGER NOT NULL DEFAULT 1 CHECK(effort_source_revision>0 AND effort_source_revision<=revision),\x0a PRIMARY KEY(session_ref,revision),\x0a FOREIGN KEY(session_ref,effort_source_revision) REFERENCES session_revision(session_ref,revision)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE session_change(\x0a session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a position INTEGER NOT NULL CHECK(position>0),\x0a ordinal INTEGER NOT NULL CHECK(ordinal>=0),\x0a revision INTEGER NOT NULL CHECK(revision>1),\x0a field TEXT NOT NULL CHECK((field='provider' OR field='model' OR field='instructions' OR field='tools' OR field='loaded_tools' OR field='permission_mode' OR field='output_schema' OR field='compaction_trigger' OR field='output_reservation' OR field='reasoning_effort' OR field='label' OR field='reasoning_effort_refused')),\x0a changed_at INTEGER NOT NULL CHECK(changed_at>0),\x0a provider_text TEXT CHECK(provider_text IS NULL OR length(CAST(provider_text AS BLOB))<=520),\x0a refused_operation_id INTEGER,\x0a PRIMARY KEY(session_ref,position,ordinal),\x0a UNIQUE(session_ref,revision,field),\x0a FOREIGN KEY(session_ref,revision) REFERENCES session_revision(session_ref,revision),\x0a FOREIGN KEY(refused_operation_id,session_ref,revision) REFERENCES model_operation(operation_id,session_ref,effort_source_revision),\x0a CHECK((field='reasoning_effort_refused')=(provider_text IS NOT NULL)),\x0a CHECK((field='reasoning_effort_refused')=(refused_operation_id IS NOT NULL))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE message_admission(\x0a admission_id INTEGER PRIMARY KEY NOT NULL CHECK(admission_id>0),\x0a session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a command_key TEXT NOT NULL UNIQUE REFERENCES core_command(command_key),\x0a content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a admission_position INTEGER CHECK(admission_position>0),\x0a turn_id INTEGER REFERENCES turn(turn_id),\x0a admitted_at INTEGER NOT NULL CHECK(admitted_at>0),\x0a sender_session_ref TEXT REFERENCES session(session_ref),\x0a sender_position INTEGER CHECK(sender_position>0),\x0a source_action_id INTEGER UNIQUE REFERENCES action_operation(action_id),\x0a source_kind INTEGER NOT NULL CHECK(source_kind BETWEEN 1 AND 5),\x0a UNIQUE(admission_id,source_kind),\x0a CHECK((sender_session_ref IS NULL)=(sender_position IS NULL)),\x0a CHECK(source_action_id IS NULL OR sender_session_ref IS NULL),\x0a CHECK((source_kind=1 AND sender_session_ref IS NULL AND source_action_id IS NULL) OR (source_kind=2 AND sender_session_ref IS NOT NULL) OR (source_kind=3 AND source_action_id IS NOT NULL) OR (source_kind IN (4,5) AND sender_session_ref IS NULL))\x0a) STRICT;\x0aCREATE TABLE action_value(\x0a action_id INTEGER NOT NULL REFERENCES action_operation(action_id),\x0a ordinal INTEGER NOT NULL CHECK(ordinal>0),\x0a handle TEXT NOT NULL CHECK(length(CAST(handle AS BLOB))=32 AND (handle NOT GLOB '*[^0-9a-f]*' AND length(handle)=length(CAST(handle AS BLOB)))),\x0a publication_key TEXT NOT NULL CHECK(length(CAST(publication_key AS BLOB)) BETWEEN 1 AND 128),\x0a content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a admission_id INTEGER UNIQUE REFERENCES message_admission(admission_id),\x0a published_at INTEGER NOT NULL CHECK(published_at>0),\x0a PRIMARY KEY(action_id,ordinal),\x0a UNIQUE(handle,publication_key)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE sent_rejection(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a sender_session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a sender_position INTEGER NOT NULL CHECK(sender_position>0),\x0a rejected_at INTEGER NOT NULL CHECK(rejected_at>0),\x0a UNIQUE(sender_session_ref,sender_position)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE turn(\x0a turn_id INTEGER PRIMARY KEY NOT NULL CHECK(turn_id>0),\x0a session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a first_admission_id INTEGER NOT NULL REFERENCES message_admission(admission_id),\x0a input_cutoff INTEGER NOT NULL CHECK(input_cutoff>=first_admission_id),\x0a operation_id INTEGER NOT NULL,\x0a outcome_code TEXT CHECK(outcome_code IS NULL OR length(CAST(outcome_code AS BLOB)) BETWEEN 1 AND 96),\x0a outcome_content_id INTEGER REFERENCES content(content_id),\x0a outcome_position INTEGER CHECK(outcome_position>0),\x0a outcome_at INTEGER CHECK(outcome_at IS NULL OR outcome_at>0),\x0a continuation_operation_id INTEGER CHECK(continuation_operation_id IS NULL OR continuation_operation_id<=operation_id),\x0a CHECK((outcome_code IS NULL)=(outcome_at IS NULL))\x0a) STRICT;\x0aCREATE TABLE session_stop(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a selected_turn_id INTEGER REFERENCES turn(turn_id),\x0a position INTEGER CHECK(position>0),\x0a admission_cutoff INTEGER NOT NULL CHECK(admission_cutoff>=0),\x0a stopped_at INTEGER NOT NULL CHECK(stopped_at>0),\x0a parent_caused INTEGER NOT NULL DEFAULT 0 CHECK(parent_caused IN (0,1)), action_cutoff INTEGER NOT NULL DEFAULT 0 CHECK(action_cutoff>=0)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE session_archive_command(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a archived INTEGER NOT NULL CHECK(archived IN (0,1))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE session_pin(\x0a session_ref TEXT PRIMARY KEY NOT NULL REFERENCES session(session_ref),\x0a command_key TEXT UNIQUE REFERENCES core_command(command_key)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE session_pin_command(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a pinned INTEGER NOT NULL CHECK(pinned IN (0,1))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE session_stop_owed(\x0a child_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a cause_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a cause_position INTEGER NOT NULL CHECK(cause_position>0),\x0a settled INTEGER NOT NULL CHECK(settled BETWEEN 0 AND 1),\x0a PRIMARY KEY(child_ref,cause_ref,cause_position)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE session_forward(\x0a forward_id INTEGER PRIMARY KEY NOT NULL CHECK(forward_id>0),\x0a target_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a child_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a kind INTEGER NOT NULL CHECK(kind BETWEEN 1 AND 2),\x0a source_id INTEGER NOT NULL CHECK(source_id>0),\x0a position INTEGER CHECK(position IS NULL OR position>0),\x0a ordinal INTEGER NOT NULL CHECK(ordinal=0),\x0a delivered_at INTEGER CHECK(delivered_at IS NULL OR delivered_at>0),\x0a message_delivered INTEGER CHECK(message_delivered IS NULL OR message_delivered IN (0,1)),\x0a suppress_message INTEGER NOT NULL DEFAULT 0 CHECK(suppress_message IN (0,1)),\x0a UNIQUE(target_ref,kind,source_id),\x0a CHECK((position IS NULL)=(delivered_at IS NULL)),\x0a CHECK(target_ref<>child_ref)\x0a) STRICT;\x0aCREATE TABLE model_interruption_command(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a session_ref TEXT NOT NULL CHECK(length(CAST(session_ref AS BLOB))<=128),\x0a turn_id TEXT NOT NULL CHECK(length(CAST(turn_id AS BLOB)) BETWEEN 1 AND 20 AND (turn_id NOT GLOB '*[^0-9]*' AND length(turn_id)=length(CAST(turn_id AS BLOB)))),\x0a operation_id TEXT NOT NULL CHECK(length(CAST(operation_id AS BLOB)) BETWEEN 1 AND 20 AND (operation_id NOT GLOB '*[^0-9]*' AND length(operation_id)=length(CAST(operation_id AS BLOB))))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE model_operation(\x0a operation_id INTEGER PRIMARY KEY NOT NULL CHECK(operation_id>0),\x0a turn_id INTEGER NOT NULL REFERENCES turn(turn_id),\x0a session_ref TEXT NOT NULL,\x0a settings_revision INTEGER NOT NULL CHECK(settings_revision>0),\x0a input_cutoff INTEGER NOT NULL CHECK(input_cutoff>0),\x0a admission_position INTEGER NOT NULL CHECK(admission_position>0),\x0a purpose INTEGER NOT NULL DEFAULT 0 CHECK(purpose IN (0,1)),\x0a compaction_trigger INTEGER CHECK(compaction_trigger IS NULL OR compaction_trigger>0),\x0a output_reservation INTEGER NOT NULL CHECK(output_reservation>=0),\x0a reasoning_effort TEXT CHECK(reasoning_effort IS NULL OR (reasoning_effort='none' OR reasoning_effort='low' OR reasoning_effort='medium' OR reasoning_effort='high' OR reasoning_effort='xhigh' OR reasoning_effort='max')),\x0a output_item_count INTEGER CHECK(output_item_count IS NULL OR output_item_count>=0),\x0a attempt_ordinal INTEGER NOT NULL CHECK(attempt_ordinal BETWEEN 1 AND 4),\x0a auth_refresh_claimed INTEGER NOT NULL DEFAULT 0 CHECK(auth_refresh_claimed IN (0,1)),\x0a retry_due_at_ms INTEGER CHECK(retry_due_at_ms IS NULL OR retry_due_at_ms>=0),\x0a last_failure_code TEXT CHECK(last_failure_code IS NULL OR length(CAST(last_failure_code AS BLOB)) BETWEEN 1 AND 96),\x0a resolution_code TEXT CHECK(resolution_code IS NULL OR length(CAST(resolution_code AS BLOB)) BETWEEN 1 AND 96),\x0a resolution_content_id INTEGER REFERENCES content(content_id),\x0a response_id TEXT CHECK(response_id IS NULL OR length(CAST(response_id AS BLOB))<=256),\x0a model_evidence BLOB CHECK(model_evidence IS NULL OR length(model_evidence) BETWEEN 7 AND 775),\x0a request_id TEXT CHECK(request_id IS NULL OR length(CAST(request_id AS BLOB))<=256),\x0a usage_uncached_tokens INTEGER CHECK(usage_uncached_tokens IS NULL OR usage_uncached_tokens>=0),\x0a usage_cache_read_tokens INTEGER CHECK(usage_cache_read_tokens IS NULL OR usage_cache_read_tokens>=0),\x0a usage_cache_write_tokens INTEGER CHECK(usage_cache_write_tokens IS NULL OR usage_cache_write_tokens>=0),\x0a usage_output_tokens INTEGER CHECK(usage_output_tokens IS NULL OR usage_output_tokens>=0),\x0a interrupted_by_command_key TEXT REFERENCES core_command(command_key),\x0a attempt_at INTEGER CHECK(attempt_at IS NULL OR attempt_at>0),\x0a retry_scheduled_at INTEGER CHECK(retry_scheduled_at IS NULL OR retry_scheduled_at>0),\x0a resolved_at INTEGER CHECK(resolved_at IS NULL OR resolved_at>0),\x0a history_floor INTEGER CHECK(history_floor IS NULL OR history_floor>0),\x0a history_level INTEGER CHECK(history_level IS NULL OR history_level BETWEEN 1 AND 3),\x0a history_dropped INTEGER CHECK(history_dropped IS NULL OR history_dropped>=0),\x0a tool_set_id INTEGER NOT NULL REFERENCES tool_set(tool_set_id) CHECK(tool_set_id>0),\x0a effort_source_revision INTEGER NOT NULL DEFAULT 1 CHECK(effort_source_revision>0 AND effort_source_revision<=settings_revision),\x0a previous_reasoning_effort TEXT CHECK(previous_reasoning_effort IS NULL OR (previous_reasoning_effort='none' OR previous_reasoning_effort='low' OR previous_reasoning_effort='medium' OR previous_reasoning_effort='high' OR previous_reasoning_effort='xhigh' OR previous_reasoning_effort='max')),\x0a effort_update INTEGER NOT NULL DEFAULT 0 CHECK(effort_update IN (0,1) AND (effort_update=0 OR reasoning_effort IS NOT NULL)),\x0a previous_effort_override TEXT CHECK(previous_effort_override IS NULL OR (previous_effort_override='none' OR previous_effort_override='low' OR previous_effort_override='medium' OR previous_effort_override='high' OR previous_effort_override='xhigh' OR previous_effort_override='max')), latency_ms INTEGER CHECK(latency_ms IS NULL OR latency_ms>=0), first_event_ms INTEGER CHECK(first_event_ms IS NULL OR first_event_ms>=0),\x0a context_window INTEGER NOT NULL CHECK(context_window BETWEEN 0 AND 4294967295), output_limit INTEGER NOT NULL DEFAULT 32000 CHECK(output_limit BETWEEN 0 AND 4294967295),\x0a UNIQUE(operation_id,session_ref),\x0a FOREIGN KEY(session_ref,settings_revision) REFERENCES session_revision(session_ref,revision),\x0a CHECK((usage_uncached_tokens IS NULL AND usage_cache_read_tokens IS NULL AND usage_cache_write_tokens IS NULL AND usage_output_tokens IS NULL) OR (usage_uncached_tokens IS NOT NULL AND usage_cache_read_tokens IS NOT NULL AND usage_cache_write_tokens IS NOT NULL AND usage_output_tokens IS NOT NULL)),\x0a CHECK((resolution_code IS NULL AND retry_due_at_ms IS NOT NULL) OR (resolution_code IS NOT NULL AND retry_due_at_ms IS NULL)),\x0a CHECK((resolution_code IS NULL AND retry_due_at_ms=0 AND attempt_at IS NOT NULL AND retry_scheduled_at IS NULL AND resolved_at IS NULL) OR (resolution_code IS NULL AND retry_due_at_ms>0 AND attempt_at IS NULL AND retry_scheduled_at IS NOT NULL AND resolved_at IS NULL) OR (resolution_code IS NOT NULL AND attempt_at IS NULL AND retry_scheduled_at IS NULL AND resolved_at IS NOT NULL)),\x0a CHECK(((resolution_code IS 'interrupted') AND interrupted_by_command_key IS NOT NULL) OR (coalesce(resolution_code,'')!='interrupted' AND interrupted_by_command_key IS NULL)),\x0a CHECK((history_floor IS NULL AND history_level IS NULL AND history_dropped IS NULL) OR (history_floor IS NOT NULL AND purpose=1 AND ((history_level IS NULL AND history_dropped IS NULL) OR (history_level IS NOT NULL AND history_dropped IS NOT NULL))))\x0a) STRICT;\x0aCREATE TABLE message_skill(\x0a admission_id INTEGER NOT NULL REFERENCES message_admission(admission_id),\x0a position INTEGER NOT NULL CHECK(position>0),\x0a name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) BETWEEN 1 AND 64 AND (name NOT GLOB '*[^a-z0-9-]*' AND length(name)=length(CAST(name AS BLOB)))),\x0a content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a PRIMARY KEY(admission_id,position)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE session_skill_catalog(\x0a session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a position INTEGER NOT NULL CHECK(position>=0),\x0a catalog_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a PRIMARY KEY(session_ref,position)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE conversation_entry(\x0a session_ref TEXT NOT NULL,\x0a entry_ordinal INTEGER NOT NULL CHECK(entry_ordinal>0),\x0a session_position INTEGER NOT NULL CHECK(session_position>0),\x0a entry_kind INTEGER NOT NULL CHECK(entry_kind BETWEEN 1 AND 4),\x0a turn_id INTEGER REFERENCES turn(turn_id),\x0a source_admission_id INTEGER UNIQUE REFERENCES message_admission(admission_id),\x0a source_kind INTEGER,\x0a source_revision INTEGER,\x0a source_catalog_position INTEGER,\x0a source_skill_admission_id INTEGER,\x0a source_skill_position INTEGER,\x0a source_operation_id INTEGER REFERENCES model_operation(operation_id),\x0a source_item_ordinal INTEGER CHECK(source_item_ordinal IS NULL OR source_item_ordinal>=0),\x0a content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a recorded_at INTEGER NOT NULL CHECK(recorded_at>0),\x0a PRIMARY KEY(session_ref,entry_ordinal),\x0a UNIQUE(session_ref,session_position),\x0a UNIQUE(session_ref,source_revision),\x0a UNIQUE(session_ref,source_catalog_position),\x0a UNIQUE(source_skill_admission_id,source_skill_position),\x0a FOREIGN KEY(source_admission_id,source_kind) REFERENCES message_admission(admission_id,source_kind),\x0a FOREIGN KEY(session_ref,source_revision) REFERENCES session_revision(session_ref,revision),\x0a FOREIGN KEY(session_ref,source_catalog_position) REFERENCES session_skill_catalog(session_ref,position),\x0a FOREIGN KEY(source_skill_admission_id,source_skill_position) REFERENCES message_skill(admission_id,position),\x0a FOREIGN KEY(source_operation_id,source_item_ordinal) REFERENCES model_output_item(operation_id,item_ordinal),\x0a CHECK((entry_kind=1)=(source_kind IS NOT NULL)),\x0a CHECK((entry_kind=3)=(source_item_ordinal IS NOT NULL)),\x0a CHECK((turn_id IS NULL)=(source_catalog_position IS NOT NULL)),\x0a CHECK(source_catalog_position IS NULL OR source_catalog_position=session_position),\x0a CHECK((source_skill_admission_id IS NULL)=(source_skill_position IS NULL)),\x0a CHECK((entry_kind=4)=(source_skill_position IS NOT NULL)),\x0a CHECK((entry_kind=1 AND source_admission_id IS NOT NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL) OR (entry_kind=2 AND source_admission_id IS NULL AND ((source_revision IS NOT NULL AND source_catalog_position IS NULL) OR (source_revision IS NULL AND source_catalog_position IS NOT NULL)) AND source_operation_id IS NULL) OR (entry_kind=3 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NOT NULL) OR (entry_kind=4 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE model_output_item(\x0a operation_id INTEGER NOT NULL REFERENCES model_operation(operation_id),\x0a item_ordinal INTEGER NOT NULL CHECK(item_ordinal>=0),\x0a session_ref TEXT NOT NULL,\x0a session_position INTEGER NOT NULL CHECK(session_position>0),\x0a item_kind INTEGER NOT NULL CHECK(item_kind BETWEEN 1 AND 5),\x0a message_content_id INTEGER REFERENCES content(content_id) CHECK((message_content_id IS NOT NULL)=(item_kind=2)),\x0a attempt_ordinal INTEGER NOT NULL CHECK(attempt_ordinal>0),\x0a item_id_digest BLOB NOT NULL CHECK(length(item_id_digest)=32),\x0a replay_omits_reasoning_text INTEGER NOT NULL CHECK(replay_omits_reasoning_text IN (0,1) AND (replay_omits_reasoning_text=0 OR item_kind=1)),\x0a phase INTEGER NOT NULL DEFAULT 0 CHECK(phase IN (0,1,2) AND (phase=0 OR item_kind=2)),\x0a extras_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a part_count INTEGER NOT NULL CHECK(part_count>=0 AND (part_count=0 OR item_kind IN (1,2))),\x0a description TEXT CHECK(description IS NULL OR (length(CAST(description AS BLOB)) BETWEEN 1 AND 200 AND (description IS NOT NULL)=(item_kind=5))),\x0a call_failed INTEGER NOT NULL DEFAULT 0 CHECK(call_failed IN (0,1) AND (call_failed=0 OR item_kind=5)),\x0a PRIMARY KEY(operation_id,item_ordinal),\x0a UNIQUE(session_ref,session_position),\x0a UNIQUE(operation_id,item_id_digest)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE model_output_part(\x0a operation_id INTEGER NOT NULL,\x0a item_ordinal INTEGER NOT NULL,\x0a part_ordinal INTEGER NOT NULL CHECK(part_ordinal>=0),\x0a part_array INTEGER NOT NULL CHECK(part_array IN (1,2)),\x0a part_kind INTEGER NOT NULL CHECK(part_kind=0 OR (part_kind IN (1,2,4) AND part_array=1) OR (part_kind=3 AND part_array=2)),\x0a text_length INTEGER CHECK(text_length IS NULL OR text_length>=0),\x0a text_content_id INTEGER REFERENCES content(content_id),\x0a extras_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a PRIMARY KEY(operation_id,item_ordinal,part_ordinal),\x0a CHECK((text_length IS NOT NULL)=(part_kind IN (1,2)) AND (text_content_id IS NOT NULL)=(part_kind IN (3,4)))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE model_tool_call(\x0a operation_id INTEGER NOT NULL REFERENCES model_operation(operation_id),\x0a session_ref TEXT NOT NULL,\x0a call_ordinal INTEGER NOT NULL CHECK(call_ordinal>=0),\x0a item_ordinal INTEGER NOT NULL CHECK(item_ordinal>=0),\x0a name_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a call_id_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a arguments_content_id INTEGER NOT NULL REFERENCES content(content_id),\x0a description TEXT CHECK(description IS NULL OR length(CAST(description AS BLOB)) BETWEEN 1 AND 200),\x0a field_metadata BLOB NOT NULL CHECK(length(field_metadata)=120),\x0a rejection_code TEXT CHECK(rejection_code IS NULL OR rejection_code IN ('unknown_tool','invalid_arguments')),\x0a rejection_content_id INTEGER REFERENCES content(content_id),\x0a acceptance_position INTEGER CHECK(acceptance_position IS NULL OR acceptance_position>0),\x0a action_kind INTEGER CHECK(action_kind IS NULL OR action_kind=1),\x0a PRIMARY KEY(operation_id,call_ordinal),\x0a UNIQUE(operation_id,item_ordinal),\x0a UNIQUE(operation_id,call_id_content_id),\x0a UNIQUE(operation_id,call_ordinal,action_kind),\x0a FOREIGN KEY(operation_id,session_ref) REFERENCES model_operation(operation_id,session_ref),\x0a CHECK((rejection_code IS NULL AND rejection_content_id IS NULL AND acceptance_position IS NULL AND (action_kind IS 1)) OR (rejection_code IS NOT NULL AND rejection_content_id IS NOT NULL AND acceptance_position IS NOT NULL AND action_kind IS NULL))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE action_operation(\x0a action_id INTEGER PRIMARY KEY NOT NULL CHECK(action_id>0),\x0a parent_operation_id INTEGER NOT NULL REFERENCES model_operation(operation_id),\x0a call_ordinal INTEGER NOT NULL CHECK(call_ordinal>=0),\x0a session_ref TEXT NOT NULL REFERENCES session(session_ref),\x0a tool_kind INTEGER NOT NULL CHECK(tool_kind=1),\x0a permission_revision INTEGER NOT NULL CHECK(permission_revision>0),\x0a authorized INTEGER NOT NULL CHECK(authorized IN (0,1)),\x0a attempt_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(attempt_ordinal IN (0,1)),\x0a bash_timeout_override_ms INTEGER CHECK(bash_timeout_override_ms IS NULL OR bash_timeout_override_ms>0),\x0a attempt_timeout_ms INTEGER CHECK(attempt_timeout_ms IS NULL OR attempt_timeout_ms>0),\x0a sender_handle TEXT CHECK(sender_handle IS NULL OR (length(CAST(sender_handle AS BLOB))=32 AND (sender_handle NOT GLOB '*[^0-9a-f]*' AND length(sender_handle)=length(CAST(sender_handle AS BLOB))))),\x0a resolution_code TEXT CHECK(resolution_code IS NULL OR (resolution_code='denied' OR resolution_code='cancelled' OR resolution_code='succeeded' OR resolution_code='failed' OR resolution_code='timed_out' OR resolution_code='indeterminate' OR resolution_code='storage_failed' OR resolution_code='spawn_failed' OR resolution_code='infrastructure_shutdown')),\x0a resolution_content_id INTEGER REFERENCES content(content_id),\x0a acceptance_position INTEGER CHECK(acceptance_position IS NULL OR acceptance_position>0),\x0a attempt_at INTEGER CHECK(attempt_at IS NULL OR attempt_at>0),\x0a decided_at INTEGER CHECK(decided_at IS NULL OR decided_at>0),\x0a resolved_at INTEGER CHECK(resolved_at IS NULL OR resolved_at>0),\x0a approval_position INTEGER CHECK(approval_position IS NULL OR approval_position>0), background_content_id INTEGER REFERENCES content(content_id), background_position INTEGER CHECK((background_content_id IS NULL AND background_position IS NULL) OR (background_content_id IS NOT NULL AND background_position IS NOT NULL AND background_position>0 AND (acceptance_position IS NULL OR background_position<acceptance_position))), background_at INTEGER CHECK((background_position IS NULL AND background_at IS NULL) OR (background_position IS NOT NULL AND background_at IS NOT NULL AND background_at>0)),\x0a UNIQUE(parent_operation_id,call_ordinal),\x0a FOREIGN KEY(parent_operation_id,session_ref) REFERENCES model_operation(operation_id,session_ref),\x0a FOREIGN KEY(parent_operation_id,call_ordinal,tool_kind) REFERENCES model_tool_call(operation_id,call_ordinal,action_kind),\x0a FOREIGN KEY(session_ref,permission_revision) REFERENCES session_revision(session_ref,revision),\x0a CHECK((resolution_code IS NOT 'denied') OR (authorized=0 AND attempt_ordinal=0)),\x0a CHECK((attempt_ordinal=0 AND attempt_timeout_ms IS NULL) OR (attempt_ordinal=1 AND attempt_timeout_ms IS NOT NULL)),\x0a CHECK((resolution_code IS NULL AND resolution_content_id IS NULL AND acceptance_position IS NULL) OR (resolution_code IS NOT NULL AND resolution_content_id IS NOT NULL AND acceptance_position IS NOT NULL)),\x0a CHECK((attempt_ordinal=1)=(attempt_at IS NOT NULL)),\x0a CHECK((authorized=1)=(decided_at IS NOT NULL)),\x0a CHECK((resolution_code IS NULL)=(resolved_at IS NULL))\x0a) STRICT;\x0aCREATE TABLE permission_decision_command(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a action_id TEXT NOT NULL CHECK(length(CAST(action_id AS BLOB)) BETWEEN 1 AND 20 AND (action_id NOT GLOB '*[^0-9]*' AND length(action_id)=length(CAST(action_id AS BLOB)))),\x0a decision TEXT NOT NULL CHECK(decision IN ('allow_once','deny'))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE action_stop(\x0a stop_key TEXT PRIMARY KEY NOT NULL CHECK(length(CAST(stop_key AS BLOB))<=130),\x0a source_action_id INTEGER UNIQUE REFERENCES action_operation(action_id),\x0a source_command_key TEXT UNIQUE REFERENCES core_command(command_key),\x0a target_action_id INTEGER NOT NULL REFERENCES action_operation(action_id),\x0a CHECK(source_action_id<>target_action_id),\x0a CHECK((source_action_id IS NULL)<>(source_command_key IS NULL))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE action_stop_command(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a action_id TEXT NOT NULL CHECK(length(CAST(action_id AS BLOB)) BETWEEN 1 AND 20 AND (action_id NOT GLOB '*[^0-9]*' AND length(action_id)=length(CAST(action_id AS BLOB)))),\x0a resolution_position INTEGER CHECK(resolution_position>0)\x0a) STRICT, WITHOUT ROWID;\x0aCREATE TABLE action_control_command(\x0a command_key TEXT PRIMARY KEY NOT NULL REFERENCES core_command(command_key),\x0a action_id TEXT NOT NULL CHECK(length(CAST(action_id AS BLOB)) BETWEEN 1 AND 20 AND (action_id NOT GLOB '*[^0-9]*' AND length(action_id)=length(CAST(action_id AS BLOB)))),\x0a selected_action_id INTEGER REFERENCES action_operation(action_id),\x0a selection TEXT CHECK(selection IS NULL OR selection IN ('background','final')),\x0a selection_position INTEGER CHECK(selection_position>0),\x0a CHECK((selected_action_id IS NULL AND selection IS NULL AND selection_position IS NULL) OR (selected_action_id IS NOT NULL AND selection IS NOT NULL AND selection_position IS NOT NULL))\x0a) STRICT, WITHOUT ROWID;\x0aCREATE INDEX message_admission_activity ON message_admission(session_ref,source_kind,admission_position);\x0aCREATE INDEX conversation_entry_activity_user ON conversation_entry(session_ref,entry_kind,source_kind,session_position);\x0aCREATE INDEX conversation_entry_activity_assistant ON conversation_entry(session_ref,entry_kind,session_position);\x0aCREATE INDEX action_stop_target ON action_stop(target_action_id);\x0aCREATE INDEX content_part_by_part ON content_part(part_content_id);\x0aCREATE INDEX session_obligation_parent ON session(parent_ref,obligation_since,session_ref) WHERE obligation_since IS NOT NULL;\x0aCREATE INDEX session_forward_owed_message ON session_forward(target_ref,message_delivered);\x0aCREATE INDEX session_workspace_list ON session(workspace_digest,created_seq);\x0aCREATE INDEX session_creator ON session(creator_ref,session_ref);\x0aCREATE INDEX session_tab ON session(archive_seq,created_seq);\x0aCREATE UNIQUE INDEX message_admission_sent ON message_admission(sender_session_ref,sender_position) WHERE sender_session_ref IS NOT NULL;\x0aCREATE UNIQUE INDEX turn_one_active_per_session ON turn(session_ref) WHERE outcome_code IS NULL;\x0aCREATE INDEX turn_tool_continuation ON turn(operation_id) WHERE outcome_code IS NULL AND continuation_operation_id=operation_id;\x0aCREATE INDEX message_admission_session_order ON message_admission(session_ref,turn_id,admission_id);\x0aCREATE INDEX message_admission_pending ON message_admission(admission_id,session_ref) WHERE turn_id IS NULL;\x0aCREATE INDEX message_admission_session_pending ON message_admission(session_ref,admission_id) WHERE turn_id IS NULL;\x0aCREATE INDEX message_admission_person ON message_admission(session_ref,admission_position) WHERE source_kind=1;\x0aCREATE INDEX message_admission_unpositioned ON message_admission(session_ref) WHERE admission_position IS NULL;\x0aCREATE INDEX message_admission_position ON message_admission(session_ref,admission_position);\x0aCREATE INDEX core_command_target_order ON core_command(target,kind,command_seq);\x0aCREATE INDEX session_revision_instructions ON session_revision(session_ref,instructions_content_id);\x0aCREATE INDEX session_revision_output_schema ON session_revision(session_ref,output_schema_content_id);\x0aCREATE INDEX session_stop_exclusion ON session_stop(session_ref,admission_cutoff,position);\x0aCREATE INDEX session_stop_unpositioned ON session_stop(session_ref) WHERE position IS NULL;\x0aCREATE INDEX session_stop_position ON session_stop(session_ref,position);\x0aCREATE INDEX session_stop_turn ON session_stop(selected_turn_id);\x0aCREATE INDEX session_parent ON session(parent_ref) WHERE parent_ref IS NOT NULL;\x0aCREATE INDEX session_stop_open ON session_stop_owed(settled,child_ref);\x0aCREATE INDEX session_forward_message ON session_forward(message_delivered,source_id);\x0aCREATE INDEX session_forward_open ON session_forward(forward_id) WHERE position IS NULL;\x0aCREATE INDEX session_forward_feed ON session_forward(target_ref,position);\x0aCREATE INDEX action_operation_session_order ON action_operation(session_ref,action_id);\x0aCREATE UNIQUE INDEX action_operation_sender_handle ON action_operation(sender_handle) WHERE sender_handle IS NOT NULL;\x0aCREATE INDEX action_operation_acceptance ON action_operation(session_ref,acceptance_position);\x0aCREATE INDEX action_operation_session_results ON action_operation(session_ref,parent_operation_id,acceptance_position) WHERE acceptance_position IS NOT NULL AND background_position IS NULL;\x0aCREATE INDEX action_operation_approval ON action_operation(session_ref,approval_position) WHERE approval_position IS NOT NULL;\x0aCREATE INDEX action_operation_unaccepted ON action_operation(session_ref) WHERE acceptance_position IS NULL;\x0aCREATE INDEX action_operation_executable ON action_operation(action_id) WHERE authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0;\x0aCREATE INDEX action_operation_unresolved_attempt ON action_operation(action_id) WHERE resolution_code IS NULL AND attempt_ordinal=1;\x0aCREATE INDEX action_operation_indeterminate ON action_operation(session_ref,parent_operation_id,call_ordinal) WHERE resolution_code='indeterminate';\x0aCREATE INDEX model_tool_call_session_order ON model_tool_call(session_ref,operation_id,call_ordinal);\x0aCREATE INDEX model_tool_call_session_results ON model_tool_call(session_ref,operation_id,acceptance_position) WHERE acceptance_position IS NOT NULL;\x0aCREATE INDEX model_tool_call_acceptance ON model_tool_call(session_ref,acceptance_position) WHERE acceptance_position IS NOT NULL;\x0aCREATE INDEX model_operation_retry_due ON model_operation(retry_due_at_ms,operation_id) WHERE resolution_code IS NULL AND attempt_ordinal<4;\x0aCREATE INDEX model_operation_retry_exhausted ON model_operation(operation_id) WHERE resolution_code IS NULL AND retry_due_at_ms=0 AND attempt_ordinal=4;\x0aCREATE INDEX model_operation_session_history ON model_operation(session_ref,operation_id);\x0aCREATE INDEX action_operation_background ON action_operation(session_ref,background_position);\x0aCREATE INDEX action_operation_background_results ON action_operation(session_ref,parent_operation_id,background_position) WHERE background_position IS NOT NULL;\x0aCREATE INDEX action_operation_background_ready ON action_operation(parent_operation_id,action_id) WHERE background_position IS NOT NULL AND authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0;\x0aCREATE INDEX action_operation_awaiting ON action_operation(session_ref,action_id) WHERE authorized=0 AND resolution_code IS NULL;\x0aCREATE INDEX model_operation_turn_history ON model_operation(turn_id,operation_id);\x0aCREATE INDEX session_change_refused_operation ON session_change(refused_operation_id,session_ref,revision);\x0aCREATE UNIQUE INDEX model_operation_effort_source ON model_operation(operation_id,session_ref,effort_source_revision);\x0aCREATE INDEX model_operation_admission ON model_operation(session_ref,admission_position);\x0aCREATE INDEX model_operation_context_history ON model_operation(session_ref,admission_position) WHERE (resolution_code='answer' OR resolution_code='compacted' OR resolution_code='tool_proposals');\x0aCREATE INDEX model_operation_compaction_bases ON model_operation(session_ref,admission_position) WHERE purpose=1 AND resolution_code='compacted';\x0aCREATE INDEX conversation_entry_history ON conversation_entry(session_ref,session_position);\x0aCREATE INDEX model_output_history ON model_output_item(session_ref,session_position);\x0aCREATE INDEX model_output_call_history ON model_output_item(session_ref,session_position) WHERE item_kind=3;\x0aCREATE INDEX model_output_hosted_history ON model_output_item(session_ref,session_position) WHERE item_kind=5;\x0aCREATE INDEX model_output_compaction_history ON model_output_item(session_ref,session_position) WHERE item_kind=4;\x0aCREATE INDEX model_output_compaction_anchor ON model_output_item(operation_id,item_ordinal) WHERE item_kind=4;\x0aCREATE INDEX turn_session_latest ON turn(session_ref,turn_id DESC);\x0aCREATE INDEX turn_unpositioned ON turn(session_ref) WHERE (outcome_code IS NULL)!=(outcome_position IS NULL);\x0aCREATE INDEX turn_outcome_unpositioned ON turn(session_ref) WHERE outcome_position IS NULL;\x0aCREATE INDEX turn_outcome_position ON turn(session_ref,outcome_position);\x0a";
    pub const mysql_ddl = "CREATE TABLE store_meta(\x0a meta_key VARCHAR(14) NOT NULL,\x0a meta_value LONGTEXT NOT NULL,\x0a PRIMARY KEY(meta_key),\x0a CHECK((meta_key='wire_version' OR meta_key='store_selector' OR meta_key='format' OR meta_key='store_id'))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE store_owner(\x0a owner_key BIGINT NOT NULL,\x0a epoch BIGINT NOT NULL,\x0a commit_seq BIGINT NOT NULL,\x0a PRIMARY KEY(owner_key),\x0a CHECK(owner_key=1),\x0a CHECK(epoch>=0),\x0a CHECK(commit_seq>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE content(\x0a content_id BIGINT NOT NULL,\x0a digest VARBINARY(32) NOT NULL,\x0a byte_length BIGINT NOT NULL,\x0a private TINYINT NOT NULL,\x0a form BIGINT NOT NULL DEFAULT 0,\x0a PRIMARY KEY(content_id),\x0a UNIQUE(digest,byte_length,private),\x0a CHECK(length(digest)=32),\x0a CHECK(byte_length>=0 AND byte_length<=1073737728),\x0a CHECK(private IN (0,1)),\x0a CHECK(form IN (0,1) AND (form=0 OR private=0))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE content_chunk(\x0a content_id BIGINT NOT NULL,\x0a chunk_index BIGINT NOT NULL,\x0a bytes LONGBLOB NOT NULL,\x0a PRIMARY KEY(content_id,chunk_index),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a CHECK(chunk_index>=0),\x0a CHECK(length(bytes) BETWEEN 1 AND 131072)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE content_part(\x0a content_id BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a part_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(content_id,ordinal),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(part_content_id) REFERENCES content(content_id),\x0a CHECK(ordinal>=0),\x0a CHECK(part_content_id<>content_id)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE tool_record(\x0a tool_record_id BIGINT NOT NULL,\x0a name VARCHAR(64) NOT NULL,\x0a remote_name VARCHAR(64) NOT NULL,\x0a owner VARCHAR(8) NOT NULL,\x0a server VARCHAR(64) NOT NULL,\x0a replay VARCHAR(6) NOT NULL,\x0a restart_limit BIGINT NOT NULL,\x0a wait_ms BIGINT NOT NULL,\x0a description_content_id BIGINT NOT NULL,\x0a input_schema_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(tool_record_id),\x0a UNIQUE(name,remote_name,owner,server,replay,restart_limit,wait_ms,description_content_id,input_schema_content_id),\x0a FOREIGN KEY(description_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(input_schema_content_id) REFERENCES content(content_id),\x0a CHECK(tool_record_id>0),\x0a CHECK(OCTET_LENGTH(name) BETWEEN 1 AND 64 AND (NOT REGEXP_LIKE(name,'[^A-Za-z0-9_-]','c'))),\x0a CHECK(OCTET_LENGTH(remote_name)<=64 AND (NOT REGEXP_LIKE(remote_name,'[^A-Za-z0-9_-]','c'))),\x0a CHECK((owner='rui' OR owner='provider' OR owner='mcp' OR owner='app')),\x0a CHECK(OCTET_LENGTH(server)<=64 AND (NOT REGEXP_LIKE(server,'[^A-Za-z0-9_-]','c')) AND (owner='mcp' AND OCTET_LENGTH(server)>0 OR owner<>'mcp' AND OCTET_LENGTH(server)=0)),\x0a CHECK(OCTET_LENGTH(replay)<=6 AND replay IN ('','unsafe','safe') AND (owner='app' AND replay<>'' OR owner<>'app' AND replay='')),\x0a CHECK((owner='app' AND restart_limit BETWEEN 0 AND 16 OR owner<>'app' AND restart_limit=0)),\x0a CHECK((owner='app' AND wait_ms BETWEEN 1000 AND 3600000 OR owner<>'app' AND wait_ms=0)),\x0a CHECK(replay<>'unsafe' OR restart_limit=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE tool_set(\x0a tool_set_id BIGINT NOT NULL,\x0a digest VARBINARY(32) NOT NULL,\x0a member_count BIGINT NOT NULL,\x0a PRIMARY KEY(tool_set_id),\x0a UNIQUE(digest),\x0a CHECK(tool_set_id>0),\x0a CHECK(length(digest)=32),\x0a CHECK(member_count BETWEEN 0 AND 1024)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE tool_set_member(\x0a tool_set_id BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a tool_record_id BIGINT NOT NULL,\x0a PRIMARY KEY(tool_set_id,ordinal),\x0a FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(tool_record_id) REFERENCES tool_record(tool_record_id),\x0a CHECK(ordinal>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE host_tool_set(\x0a slot BIGINT NOT NULL,\x0a tool_set_id BIGINT NOT NULL,\x0a PRIMARY KEY(slot),\x0a FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id),\x0a CHECK(slot=1)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE model_fact(\x0a model_id VARCHAR(256) NOT NULL,\x0a context_window BIGINT,\x0a efforts BIGINT NOT NULL,\x0a openai_listed TINYINT NOT NULL,\x0a generation BIGINT NOT NULL,\x0a output_limit BIGINT,\x0a PRIMARY KEY(model_id),\x0a CHECK(OCTET_LENGTH(model_id) BETWEEN 1 AND 256),\x0a CHECK(efforts BETWEEN 0 AND 63),\x0a CHECK(openai_listed IN (0,1)),\x0a CHECK(output_limit IS NULL OR output_limit BETWEEN 0 AND 4294967295)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE model_catalog_source(\x0a slot BIGINT NOT NULL,\x0a etag TEXT,\x0a generation BIGINT NOT NULL,\x0a fetched_at BIGINT NOT NULL,\x0a PRIMARY KEY(slot),\x0a CHECK(slot=1),\x0a CHECK(etag IS NULL OR OCTET_LENGTH(etag)<=512)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session(\x0a session_ref VARCHAR(6) NOT NULL,\x0a workspace TEXT NOT NULL,\x0a provider TEXT NOT NULL,\x0a codec TEXT NOT NULL,\x0a codec_options BLOB,\x0a prefix_seal BLOB,\x0a model TEXT NOT NULL,\x0a instructions_content_id BIGINT NOT NULL,\x0a tool_set_id BIGINT NOT NULL,\x0a loaded_tool_set_id BIGINT,\x0a permission_mode BIGINT NOT NULL,\x0a output_schema_content_id BIGINT,\x0a revision BIGINT NOT NULL,\x0a compaction_trigger BIGINT,\x0a output_reservation BIGINT,\x0a reasoning_effort VARCHAR(6),\x0a label TEXT,\x0a created_at BIGINT NOT NULL,\x0a next_position BIGINT NOT NULL,\x0a created_seq BIGINT NOT NULL,\x0a workspace_digest VARBINARY(32) NOT NULL,\x0a workspace_key BIGINT NOT NULL,\x0a parent_ref VARCHAR(6),\x0a obligation_since BIGINT,\x0a creator_ref VARCHAR(6),\x0a archive_seq BIGINT,\x0a session_obligation_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN obligation_since IS NOT NULL THEN parent_ref END) STORED,\x0a session_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN parent_ref IS NOT NULL THEN parent_ref END) STORED,\x0a PRIMARY KEY(session_ref),\x0a UNIQUE(created_seq),\x0a FOREIGN KEY(instructions_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(loaded_tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(output_schema_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(parent_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(creator_ref) REFERENCES session(session_ref),\x0a CHECK(OCTET_LENGTH(session_ref)=6 AND (NOT REGEXP_LIKE(session_ref,'[^0123456789abcdefghjkmnpqrstvwxyz]','c'))),\x0a CHECK(OCTET_LENGTH(workspace) BETWEEN 1 AND 4096),\x0a CHECK(OCTET_LENGTH(provider) BETWEEN 1 AND 16 AND REGEXP_LIKE(provider,'^[a-z]','c') AND (NOT REGEXP_LIKE(provider,'[^a-z0-9_-]','c'))),\x0a CHECK(OCTET_LENGTH(codec) BETWEEN 3 AND 40),\x0a CHECK(codec_options IS NULL OR length(codec_options) BETWEEN 1 AND 512),\x0a CHECK(prefix_seal IS NULL OR length(prefix_seal)=56),\x0a CHECK(OCTET_LENGTH(model) BETWEEN 1 AND 256),\x0a CHECK(tool_set_id>0),\x0a CHECK(permission_mode BETWEEN 0 AND 1),\x0a CHECK(revision>0),\x0a CHECK(compaction_trigger IS NULL OR compaction_trigger>0),\x0a CHECK(output_reservation IS NULL OR output_reservation>=0),\x0a CHECK(reasoning_effort IS NULL OR (reasoning_effort='none' OR reasoning_effort='low' OR reasoning_effort='medium' OR reasoning_effort='high' OR reasoning_effort='xhigh' OR reasoning_effort='max')),\x0a CHECK(label IS NULL OR OCTET_LENGTH(label) BETWEEN 1 AND 100),\x0a CHECK(created_at>0),\x0a CHECK(next_position>0),\x0a CHECK(created_seq>0),\x0a CHECK(length(workspace_digest)=32),\x0a CHECK(obligation_since IS NULL OR obligation_since>0),\x0a CHECK(creator_ref IS NULL OR creator_ref<>session_ref),\x0a CHECK(archive_seq IS NULL OR archive_seq>0),\x0a CHECK(workspace_key>0 AND workspace_key<=created_seq),\x0a CHECK(parent_ref IS NULL OR parent_ref<>session_ref)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE core_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a kind BIGINT NOT NULL,\x0a target VARCHAR(128) NOT NULL,\x0a input_digest BLOB NOT NULL,\x0a primary_content_id BIGINT,\x0a secondary_content_id BIGINT,\x0a accepted TINYINT NOT NULL,\x0a code TEXT NOT NULL,\x0a revision BIGINT NOT NULL,\x0a created TINYINT NOT NULL,\x0a command_seq BIGINT NOT NULL,\x0a missing_settings BIGINT,\x0a PRIMARY KEY(command_seq),\x0a UNIQUE(command_key),\x0a FOREIGN KEY(primary_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(secondary_content_id) REFERENCES content(content_id),\x0a CHECK(OCTET_LENGTH(command_key)<=128),\x0a CHECK(kind BETWEEN 1 AND 9),\x0a CHECK(OCTET_LENGTH(target)<=128),\x0a CHECK(length(input_digest)=32),\x0a CHECK(accepted IN (0,1)),\x0a CHECK(OCTET_LENGTH(code)<=96),\x0a CHECK(revision>=0),\x0a CHECK(created IN (0,1)),\x0a CHECK(command_seq>0),\x0a CHECK(missing_settings IS NULL AND code<>'missing_settings' OR missing_settings IS NOT NULL AND code='missing_settings' AND missing_settings BETWEEN 1 AND 7)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session_revision(\x0a session_ref VARCHAR(6) NOT NULL,\x0a revision BIGINT NOT NULL,\x0a command_key VARCHAR(128) NOT NULL,\x0a workspace LONGTEXT NOT NULL,\x0a provider TEXT NOT NULL,\x0a model LONGTEXT NOT NULL,\x0a instructions_content_id BIGINT NOT NULL,\x0a instructions_updated TINYINT NOT NULL,\x0a tool_set_id BIGINT NOT NULL,\x0a loaded_tool_set_id BIGINT,\x0a permission_mode BIGINT NOT NULL,\x0a output_schema_content_id BIGINT,\x0a compaction_trigger BIGINT,\x0a output_reservation BIGINT,\x0a reasoning_effort VARCHAR(6),\x0a label TEXT,\x0a effort_source_revision BIGINT NOT NULL DEFAULT 1,\x0a PRIMARY KEY(session_ref,revision),\x0a UNIQUE(command_key),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(instructions_content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(loaded_tool_set_id) REFERENCES tool_set(tool_set_id),\x0a FOREIGN KEY(session_ref,effort_source_revision) REFERENCES session_revision(session_ref,revision),\x0a FOREIGN KEY(output_schema_content_id) REFERENCES content(content_id),\x0a CHECK(revision>0),\x0a CHECK(OCTET_LENGTH(provider) BETWEEN 1 AND 16 AND REGEXP_LIKE(provider,'^[a-z]','c') AND (NOT REGEXP_LIKE(provider,'[^a-z0-9_-]','c'))),\x0a CHECK(instructions_updated IN (0,1)),\x0a CHECK(tool_set_id>0),\x0a CHECK(permission_mode BETWEEN 0 AND 1),\x0a CHECK(compaction_trigger IS NULL OR compaction_trigger>0),\x0a CHECK(output_reservation IS NULL OR output_reservation>=0),\x0a CHECK(reasoning_effort IS NULL OR (reasoning_effort='none' OR reasoning_effort='low' OR reasoning_effort='medium' OR reasoning_effort='high' OR reasoning_effort='xhigh' OR reasoning_effort='max')),\x0a CHECK(label IS NULL OR OCTET_LENGTH(label) BETWEEN 1 AND 100),\x0a CHECK(effort_source_revision>0 AND effort_source_revision<=revision)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session_change(\x0a session_ref VARCHAR(6) NOT NULL,\x0a position BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a revision BIGINT NOT NULL,\x0a field VARCHAR(24) NOT NULL,\x0a changed_at BIGINT NOT NULL,\x0a provider_text TEXT,\x0a refused_operation_id BIGINT,\x0a PRIMARY KEY(session_ref,position,ordinal),\x0a UNIQUE(session_ref,revision,field),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(session_ref,revision) REFERENCES session_revision(session_ref,revision),\x0a CHECK(position>0),\x0a CHECK(ordinal>=0),\x0a CHECK(revision>1),\x0a CHECK((field='provider' OR field='model' OR field='instructions' OR field='tools' OR field='loaded_tools' OR field='permission_mode' OR field='output_schema' OR field='compaction_trigger' OR field='output_reservation' OR field='reasoning_effort' OR field='label' OR field='reasoning_effort_refused')),\x0a CHECK(changed_at>0),\x0a CHECK(provider_text IS NULL OR OCTET_LENGTH(provider_text)<=520),\x0a CHECK((field='reasoning_effort_refused')=(provider_text IS NOT NULL)),\x0a CHECK((field='reasoning_effort_refused')=(refused_operation_id IS NOT NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE message_admission(\x0a admission_id BIGINT NOT NULL,\x0a session_ref VARCHAR(6) NOT NULL,\x0a command_key VARCHAR(128) NOT NULL,\x0a content_id BIGINT NOT NULL,\x0a admission_position BIGINT,\x0a turn_id BIGINT,\x0a admitted_at BIGINT NOT NULL,\x0a sender_session_ref VARCHAR(6),\x0a sender_position BIGINT,\x0a source_action_id BIGINT,\x0a source_kind BIGINT NOT NULL,\x0a message_admission_pending_lead BIGINT GENERATED ALWAYS AS (CASE WHEN turn_id IS NULL THEN admission_id END) STORED,\x0a message_admission_session_pending_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN turn_id IS NULL THEN session_ref END) STORED,\x0a message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN source_kind=1 THEN session_ref END) STORED,\x0a message_admission_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN admission_position IS NULL THEN session_ref END) STORED,\x0a PRIMARY KEY(admission_id),\x0a UNIQUE(command_key),\x0a UNIQUE(source_action_id),\x0a UNIQUE(admission_id,source_kind),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(sender_session_ref) REFERENCES session(session_ref),\x0a CHECK(admission_id>0),\x0a CHECK(admission_position>0),\x0a CHECK(admitted_at>0),\x0a CHECK(sender_position>0),\x0a CHECK(source_kind BETWEEN 1 AND 5),\x0a CHECK((sender_session_ref IS NULL)=(sender_position IS NULL)),\x0a CHECK(source_action_id IS NULL OR sender_session_ref IS NULL),\x0a CHECK((source_kind=1 AND sender_session_ref IS NULL AND source_action_id IS NULL) OR (source_kind=2 AND sender_session_ref IS NOT NULL) OR (source_kind=3 AND source_action_id IS NOT NULL) OR (source_kind IN (4,5) AND sender_session_ref IS NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE action_value(\x0a action_id BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a handle VARCHAR(32) NOT NULL,\x0a publication_key VARCHAR(128) NOT NULL,\x0a content_id BIGINT NOT NULL,\x0a admission_id BIGINT,\x0a published_at BIGINT NOT NULL,\x0a PRIMARY KEY(action_id,ordinal),\x0a UNIQUE(handle,publication_key),\x0a UNIQUE(admission_id),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(admission_id) REFERENCES message_admission(admission_id),\x0a CHECK(ordinal>0),\x0a CHECK(OCTET_LENGTH(handle)=32 AND (NOT REGEXP_LIKE(handle,'[^0-9a-f]','c'))),\x0a CHECK(OCTET_LENGTH(publication_key) BETWEEN 1 AND 128),\x0a CHECK(published_at>0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE sent_rejection(\x0a command_key VARCHAR(128) NOT NULL,\x0a sender_session_ref VARCHAR(6) NOT NULL,\x0a sender_position BIGINT NOT NULL,\x0a rejected_at BIGINT NOT NULL,\x0a PRIMARY KEY(command_key),\x0a UNIQUE(sender_session_ref,sender_position),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(sender_session_ref) REFERENCES session(session_ref),\x0a CHECK(sender_position>0),\x0a CHECK(rejected_at>0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE turn(\x0a turn_id BIGINT NOT NULL,\x0a session_ref VARCHAR(6) NOT NULL,\x0a first_admission_id BIGINT NOT NULL,\x0a input_cutoff 