,200000),('zai-org/glm-5',202800),('zai-org/glm-5-maas',200000),('zai-org/glm-5.1',202000),('zai-org/glm-5.2',1048576),('zai-org/glm-5.2-maas',1000000),('zai-org/glm-5.3',1048576),('zai-org/glm-5.3-flash',1048550),('zai.glm-4.7',202752),('zai.glm-4.7-flash',202752),('zai.glm-5',202752),('zai/GLM-5.1',200000),('zai/GLM-5.2',1000000),('zai/glm-4.5-flash',131072),('zai/glm-4.6',200000),('zai/glm-4.7',200000),('zai/glm-4.7-flash',200000),('zai/glm-4.7-flashx',200000),('zai/glm-5',202800),('zai/glm-5-turbo',202800),('zai/glm-5.1',200000),('zai/glm-5.2',1000000),('zai/glm-5.2-fast',1000000),('zai/glm-5.3',1000000),('zai/glm-5.3-fast',1048576),('zai/glm-5.3-flash',1048576),('zai/glm-5.3-flashx',1000000),('zai/glm-5.3-flashx-legal',1000000),('zai/glm-5v-turbo',200000),('zdev',1000000),('zhipu/glm-5.2',1000000),('zhipu/glm-5.3',1024000),('~anthropic/claude-fable-latest',1000000),('~anthropic/claude-haiku-latest',1000000),('~anthropic/claude-opus-latest',1000000),('~anthropic/claude-sonnet-latest',1000000),('~deepseek/deepseek-flash-latest',1048576),('~deepseek/deepseek-pro-latest',1048576),('~deepseek/deepseek-v4-flash-latest',1048576),('~google/gemini-flash-latest',1048576),('~google/gemini-pro-latest',1048576),('~moonshotai/kimi-latest',1048576),('~openai/gpt-astra-latest',1050000),('~openai/gpt-luna-latest',1050000),('~openai/gpt-mini-latest',400000),('~openai/gpt-sol-latest',1050000),('~openai/gpt-terra-latest',1050000),('~unbiased/pareto-latest',1048576),('~x-ai/grok-latest',500000),('~z-ai/glm-flash-latest',1048576),('~z-ai/glm-latest',1048576);\x0aALTER TABLE model_operation ADD COLUMN context_window BIGINT NULL AFTER first_event_ms;\x0aUPDATE model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision LEFT JOIN operation_window_backfill pinned ON pinned.model_id=r.model SET o.context_window=coalesce(pinned.context_window,128000);\x0aALTER TABLE model_operation MODIFY COLUMN context_window BIGINT NOT NULL, ADD CHECK(context_window BETWEEN 0 AND 4294967295);\x0aDROP TEMPORARY TABLE operation_window_backfill;\x0aUPDATE store_meta SET meta_value='14' WHERE meta_key='wire_version' AND meta_value='13';\x0aUPDATE store_meta SET meta_value='15' WHERE meta_key='wire_version' AND meta_value='14';\x0aUPDATE store_meta SET meta_value='16' WHERE meta_key='wire_version' AND meta_value='15';\x0aALTER TABLE session ADD COLUMN obligation_since BIGINT CHECK(obligation_since IS NULL OR obligation_since>0) AFTER parent_ref;\x0aALTER TABLE session ADD COLUMN session_obligation_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN obligation_since IS NOT NULL THEN parent_ref END) STORED AFTER obligation_since, ADD INDEX session_obligation_parent(session_obligation_parent_lead,obligation_since,session_ref);\x0aCREATE INDEX session_forward_owed_message ON session_forward(target_ref,message_delivered);\x0aWITH RECURSIVE own_owed(session_ref,since) AS (SELECT t.session_ref,m.admitted_at AS since FROM turn t JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE t.outcome_code IS NULL UNION SELECT m.session_ref,m.admitted_at FROM message_admission m WHERE m.turn_id IS NULL AND m.admission_id>coalesce((SELECT admission_cutoff FROM session_stop WHERE session_ref=m.session_ref ORDER BY admission_cutoff DESC LIMIT 1),0) UNION SELECT f.target_ref,m.admitted_at FROM session_forward f LEFT JOIN action_operation a ON f.kind=1 AND a.action_id=f.source_id LEFT JOIN model_operation op ON op.operation_id=a.parent_operation_id JOIN turn t ON t.turn_id=CASE WHEN f.kind=2 THEN f.source_id ELSE op.turn_id END JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE f.position IS NULL OR f.message_delivered=0),owed(session_ref,since) AS (SELECT session_ref,since FROM own_owed UNION SELECT s.parent_ref,o.since FROM owed o JOIN session s ON s.session_ref=o.session_ref WHERE s.parent_ref IS NOT NULL) UPDATE session s JOIN (SELECT session_ref,min(since) AS since FROM owed GROUP BY session_ref) o ON o