,''),'(',''),')','')))='kind between 1 and 7');\x0aPREPARE rui_background_kind FROM @rui_background_kind_ddl;\x0aEXECUTE rui_background_kind;\x0aDEALLOCATE PREPARE rui_background_kind;\x0aSET @rui_background_kind_ddl=NULL;\x0aALTER TABLE action_operation ADD COLUMN background_content_id BIGINT AFTER approval_position, ADD COLUMN background_position BIGINT AFTER background_content_id, ADD COLUMN background_at BIGINT AFTER background_position, ADD FOREIGN KEY(background_content_id) REFERENCES content(content_id), ADD CHECK((background_content_id IS NULL AND background_position IS NULL) OR (background_content_id IS NOT NULL AND background_position IS NOT NULL AND background_position>0 AND (acceptance_position IS NULL OR background_position<acceptance_position))), ADD CHECK((background_position IS NULL AND background_at IS NULL) OR (background_position IS NOT NULL AND background_at IS NOT NULL AND background_at>0));\x0aALTER TABLE action_operation DROP INDEX action_operation_session_results, MODIFY action_operation_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL AND background_position IS NULL THEN session_ref END) STORED, ADD INDEX action_operation_session_results(action_operation_session_results_lead,parent_operation_id,acceptance_position);\x0aCREATE INDEX action_operation_background ON action_operation(session_ref,background_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_background_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL THEN session_ref END) STORED, ADD INDEX action_operation_background_results(action_operation_background_results_lead,parent_operation_id,background_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_background_ready_lead BIGINT GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL AND authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0 THEN parent_operation_id END) STORED, ADD INDEX action_operation_background_ready(action_operation_background_ready_lead,action_id);\x0aALTER TABLE action_operation ADD COLUMN action_operation_awaiting_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN authorized=0 AND resolution_code IS NULL THEN session_ref END) STORED, ADD INDEX action_operation_awaiting(action_operation_awaiting_lead,action_id);\x0aALTER TABLE session_stop ADD COLUMN action_cutoff BIGINT NOT NULL DEFAULT 0 CHECK(action_cutoff>=0) AFTER parent_caused;\x0aCREATE TABLE action_control_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a action_id TEXT NOT NULL,\x0a selected_action_id BIGINT,\x0a selection VARCHAR(10),\x0a selection_position BIGINT,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(selected_action_id) REFERENCES action_operation(action_id),\x0a CHECK(OCTET_LENGTH(action_id) BETWEEN 1 AND 20 AND (NOT REGEXP_LIKE(action_id,'[^0-9]','c'))),\x0a CHECK(selection IS NULL OR selection IN ('background','final')),\x0a CHECK(selection_position>0),\x0a CHECK((selected_action_id IS NULL AND selection IS NULL AND selection_position IS NULL) OR (selected_action_id IS NOT NULL AND selection IS NOT NULL AND selection_position IS NOT NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD COLUMN source_action_id BIGINT AFTER sender_position, ADD UNIQUE(source_action_id), ADD FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id), ADD CHECK(source_action_id IS NULL OR sender_session_ref IS NULL), MODIFY COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN sender_session_ref IS NULL AND source_action_id IS NULL THEN session_ref END) STORED;\x0aCREATE TABLE action_stop(\x0a source_action_id BIGINT NOT NULL,\x0a target_action_id BIGINT NOT NULL,\x0a PRIMARY KEY(source_action_id),\x0a FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id),\x0a FOREIGN KEY(target_action_id) REFERENCES action_operat