ref IS NULL)), MODIFY COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN source_kind=1 THEN session_ref END) STORED;\x0aCREATE TABLE action_value(action_id BIGINT NOT NULL, ordinal BIGINT NOT NULL, handle VARCHAR(32) NOT NULL, publication_key VARCHAR(128) NOT NULL, content_id BIGINT NOT NULL, admission_id BIGINT, published_at BIGINT NOT NULL, PRIMARY KEY(action_id,ordinal), UNIQUE(handle,publication_key), UNIQUE(admission_id), FOREIGN KEY(action_id) REFERENCES action_operation(action_id), FOREIGN KEY(content_id) REFERENCES content(content_id), FOREIGN KEY(admission_id) REFERENCES message_admission(admission_id), CHECK(ordinal>0), CHECK(OCTET_LENGTH(handle)=32 AND NOT REGEXP_LIKE(handle,'[^0-9a-f]','c')), CHECK(OCTET_LENGTH(publication_key) BETWEEN 1 AND 128), CHECK(published_at>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD UNIQUE(admission_id,source_kind);\x0aALTER TABLE conversation_entry ADD COLUMN source_kind BIGINT NULL AFTER source_admission_id;\x0aUPDATE conversation_entry e LEFT JOIN message_admission m ON m.admission_id=e.source_admission_id SET e.source_kind=m.source_kind;\x0aALTER TABLE conversation_entry ADD CHECK((entry_kind=1)=(source_kind IS NOT NULL)), ADD FOREIGN KEY(source_admission_id,source_kind) REFERENCES message_admission(admission_id,source_kind);\x0aCREATE INDEX conversation_entry_activity_user ON conversation_entry(session_ref,entry_kind,source_kind,session_position);\x0aCREATE INDEX conversation_entry_activity_assistant ON conversation_entry(session_ref,entry_kind,session_position);\x0aCREATE INDEX message_admission_activity ON message_admission(session_ref,source_kind,admission_position);\x0aCREATE INDEX session_creator ON session(creator_ref,session_ref);\x0aALTER TABLE session ADD COLUMN archive_seq BIGINT AFTER creator_ref, ADD CHECK(archive_seq IS NULL OR archive_seq>0), ADD FOREIGN KEY(archive_seq) REFERENCES core_command(command_seq);\x0aUPDATE ses