nt_id);\x0aALTER TABLE tool_record ADD CHECK(OCTET_LENGTH(remote_name)<=64 AND (NOT REGEXP_LIKE(remote_name,'[^A-Za-z0-9_-]','c')));\x0aALTER TABLE model_fact ADD COLUMN output_limit BIGINT AFTER generation, ADD CHECK(output_limit IS NULL OR output_limit BETWEEN 0 AND 4294967295);\x0aALTER TABLE model_operation ADD COLUMN output_limit BIGINT NOT NULL DEFAULT 32000 AFTER context_window, ADD CHECK(output_limit BETWEEN 0 AND 4294967295);\x0aSET @rui_owner_ddl=(SELECT CONCAT('ALTER TABLE tool_record DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='tool_record' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='owner = _utf8mb4''rui'' or owner = _utf8mb4''provider'' or owner = _utf8mb4''mcp''';\x0aPREPARE rui_owner_check FROM @rui_owner_ddl;\x0aEXECUTE rui_owner_check;\x0aDEALLOCATE PREPARE rui_owner_check;\x0aALTER TABLE tool_record ADD CHECK((owner='rui' OR owner='provider' OR owner='mcp' OR owner='app'));\x0aALTER TABLE tool_record ADD COLUMN replay VARCHAR(6) NOT NULL DEFAULT '' AFTER server;\x0aALTER TABLE tool_record ALTER COLUMN replay DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN restart_limit BIGINT NOT NULL DEFAULT 0 AFTER replay;\x0aALTER TABLE tool_record ALTER COLUMN restart_limit DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN wait_ms BIGINT NOT NULL DEFAULT 0 AFTER restart_limit;\x0aALTER TABLE tool_record ALTER COLUMN wait_ms DROP DEFAULT;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,remote_name,owner,server,replay,restart_limit,wait_ms,description_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(OCTET_LENGTH(replay)<=6 AND replay IN ('','unsafe','safe') AND (owner='app' AND replay<>'' OR owner<>'app' AND replay=''));\x0aALTER TABLE tool_record ADD CHECK((owner='app' AND restart_limit BETWEEN 0 AND 16 OR owner<>'app' AND restart_limit=0));\x0aALTER TABLE tool_record ADD CHECK((owner='app' AND wait_ms BETWEEN 1000 AND 3600000 OR owner<>'app' AND wait_ms=0));\x0aALTER TABLE tool_record ADD CHECK(replay<>'unsafe' OR restart_limit=0);\x0aUPDATE store_meta SET meta_value='92' WHERE meta_key='format';\x0a", "ALTER TABLE session ADD COLUMN parent_ref VARCHAR(6),ADD FOREIGN KEY(parent_ref) REFERENCES session(session_ref),ADD CHECK(parent_ref IS NULL OR parent_ref<>session_ref);\x0aCREATE TABLE session_stop_owed(\x0a child_ref VARCHAR(6) NOT NULL,\x0a cause_ref VARCHAR(6) NOT NULL,\x0a cause_position BIGINT NOT NULL,\x0a settled BIGINT NOT NULL,\x0a PRIMARY KEY(child_ref,cause_ref,cause_position),\x0a FOREIGN KEY(child_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(cause_ref) REFERENCES session(session_ref),\x0a CHECK(cause_position>0),\x0a CHECK(settled BETWEEN 0 AND 1)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX session_stop_open ON session_stop_owed(settled,child_ref);\x0aCREATE INDEX session_parent ON session(parent_ref);\x0aALTER TABLE session ADD COLUMN loaded_tool_set_id BIGINT AFTER tool_set_id,ADD FOREIGN KEY(loaded_tool_set_id) REFERENCES tool_set(tool_set_id);\x0aALTER TABLE session_revision ADD COLUMN loaded_tool_set_id BIGINT AFTER tool_set_id,ADD FOREIGN KEY(loaded_tool_set_id) REFERENCES tool_set(tool_set_id);\x0aALTER TABLE session_change DROP CHECK session_change_chk_4,ADD CHECK((field='provider' OR field='model' OR field='instructions' OR field='tools' OR field='loaded_tools' OR field='permission_mode' OR field='output_schema' OR field='compaction_trigger' OR field='output_reservation' OR field='reasoning_effort' OR field='label'));\x0aALTER TABLE store_meta DROP CHECK store_meta_chk_1, ADD CHECK((meta_key='wire_version' OR meta_key='store_selector' OR meta_key='format' OR meta_key='store_id'));\x0aCREATE TABLE store_owner(\x0a owner_key BIGINT NOT NULL,\x0a epoch BIGINT NOT NULL,\x0a commit_seq BIGINT NOT NULL,\x0a PRIMARY KEY(owner_key),\x0a CHECK(owner_key=1),\x0a CHECK(epoch>=0),\x0a CHECK(commit_seq>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE content_chunk(\x0a content_id BIGINT NOT NULL,\x0a chunk_index BIGINT NOT NULL,\x0a bytes LONGBLOB NOT NULL,\x0a PRIMARY KEY(content_id,chunk_index),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a CHECK(chunk_index>=0),\x0a CHECK(length(bytes) BETWEEN 1 AND 131072)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO content_chunk(content_id,chunk_index,bytes) WITH digit(d) AS (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9), chunk(i) AS (SELECT a.d+10*b.d+100*c.d+1000*e.d FROM digit a CROSS JOIN digit b CROSS JOIN digit c CROSS JOIN digit e) SELECT content.content_id,chunk.i,SUBSTRING(content.payload,chunk.i*131072+1,131072) FROM content JOIN chunk ON chunk.i*131072<content.byte_length;\x0aALTER TABLE content DROP CHECK content_chk_4, DROP COLUMN payload;\x0aALTER TABLE message_admission ADD COLUMN message_admission_pending_lead BIGINT GENERATED ALWAYS AS (CASE WHEN turn_id IS NULL THEN admission_id END) STORED, ADD COLUMN message_admission_session_pending_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN turn_id IS NULL THEN session_ref END) STORED, ADD COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN sender_session_ref IS NULL THEN session_ref END) STORED, ADD COLUMN message_admission_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN admission_position IS NULL THEN session_ref END) STORED, DROP INDEX message_admission_pending, ADD INDEX message_admission_pending(message_admission_pending_lead,session_ref), DROP INDEX message_admission_session_pending, ADD INDEX message_admission_session_pending(message_admission_session_pending_lead,admission_id), DROP INDEX message_admission_person, ADD INDEX message_admission_person(message_admission_person_lead,admission_position), DROP INDEX message_admission_unpositioned, ADD INDEX message_admission_unpositioned(message_admission_unpositioned_lead);\x0aALTER TABLE turn ADD COLUMN turn_tool_continuation_lead BIGINT GENERATED ALWAYS AS (CASE WHEN outcome_code IS NULL AND continuation_operation_id=operation_id THEN operation_id END) STORED, ADD COLUMN turn_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN (outcome_code IS NULL)!=(outcome_position IS NULL) THEN session_ref END) STORED, DROP INDEX turn_tool_continuation, ADD INDEX turn_tool_continuation(turn_tool_continuation_lead), DROP INDEX turn_unpositioned, ADD INDEX turn_unpositioned(turn_unpositioned_lead);\x0aALTER TABLE session_stop ADD COLUMN session_stop_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN position IS NULL THEN session_ref END) STORED, DROP INDEX session_stop_unpositioned, ADD INDEX session_stop_unpositioned(session_stop_unpositioned_lead);\x0aALTER TABLE model_operation ADD COLUMN model_operation_retry_due_lead BIGINT GENERATED ALWAYS AS (CASE WHEN resolution_code IS NULL AND attempt_ordinal<4 THEN retry_due_at_ms END) STORED, ADD COLUMN model_operation_retry_exhausted_lead BIGINT GENERATED ALWAYS AS (CASE WHEN resolution_code IS NULL AND retry_due_at_ms=0 AND attempt_ordinal=4 THEN operation_id END) STORED, ADD COLUMN model_operation_context_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN (resolution_code='answer' OR resolution_code='compacted' OR resolution_code='tool_proposals') THEN session_ref END) STORED, ADD COLUMN model_operation_compaction_bases_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN purpose=1 AND resolution_code='compacted' THEN session_ref END) STORED, DROP INDEX model_operation_retry_due, ADD INDEX model_operation_retry_due(model_operation_retry_due_lead,operation_id), DROP INDEX model_operation_retry_exhausted, ADD INDEX model_operation_retry_exhausted(model_operation_retry_exhausted_lead), DROP INDEX model_operation_context_history, ADD INDEX model_operation_context_history(model_operation_context_history_lead,admission_position), DROP INDEX model_operation_compaction_bases, ADD INDEX model_operation_compaction_bases(model_operation_compaction_bases_lead,admission_position);\x0aALTER TABLE model_output_item ADD COLUMN model_output_call_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN item_kind=3 THEN session_ref END) STORED, ADD COLUMN model_output_hosted_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN item_kind=5 THEN session_ref END) STORED, ADD COLUMN model_output_compaction_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN item_kind=4 THEN session_ref END) STORED, ADD COLUMN model_output_compaction_anchor_lead BIGINT GENERATED ALWAYS AS (CASE WHEN item_kind=4 THEN operation_id END) STORED, DROP INDEX model_output_call_history, ADD INDEX model_output_call_history(model_output_call_history_lead,session_position), DROP INDEX model_output_hosted_history, ADD INDEX model_output_hosted_history(model_output_hosted_history_lead,session_position), DROP INDEX model_output_compaction_history, ADD INDEX model_output_compaction_history(model_output_compaction_history_lead,session_position), DROP INDEX model_output_compaction_anchor, ADD INDEX model_output_compaction_anchor(model_output_compaction_anchor_lead,item_ordinal);\x0aALTER TABLE model_tool_call ADD COLUMN model_tool_call_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED, ADD COLUMN model_tool_call_acceptance_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED, DROP INDEX model_tool_call_session_results, ADD INDEX model_tool_call_session_results(model_tool_call_session_results_lead,operation_id,acceptance_position), DROP INDEX model_tool_call_acceptance, ADD INDEX model_tool_call_acceptance(model_tool_call_acceptance_lead,acceptance_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED, ADD COLUMN action_operation_approval_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN approval_position IS NOT NULL THEN session_ref END) STORED, ADD COLUMN action_operation_executable_lead BIGINT GENERATED ALWAYS AS (CASE WHEN authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0 THEN action_id END) STORED, ADD COLUMN action_operation_unresolved_attempt_lead BIGINT GENERATED ALWAYS AS (CASE WHEN resolution_code IS NULL AND attempt_ordinal=1 THEN action_id END) STORED, DROP INDEX action_operation_session_results, ADD INDEX action_operation_session_results(action_operation_session_results_lead,parent_operation_id,acceptance_position), DROP INDEX action_operation_approval, ADD INDEX action_operation_approval(action_operation_approval_lead,approval_position), DROP INDEX action_operation_executable, ADD INDEX action_operation_executable(action_operation_executable_lead), DROP INDEX action_operation_unresolved_attempt, ADD INDEX action_operation_unresolved_attempt(action_operation_unresolved_attempt_lead);\x0aALTER TABLE session ADD COLUMN session_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN parent_ref IS NOT NULL THEN parent_ref END) STORED, ADD INDEX parent_ref(parent_ref);\x0aALTER TABLE session DROP INDEX session_parent, ADD INDEX session_parent(session_parent_lead);\x0aCREATE TABLE session_ending_owed(\x0a turn_id BIGINT NOT NULL,\x0a delivered BIGINT NOT NULL,\x0a PRIMARY KEY(turn_id),\x0a FOREIGN KEY(turn_id) REFERENCES turn(turn_id),\x0a CHECK(turn_id>0),\x0a CHECK(delivered BETWEEN 0 AND 1)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX session_ending_open ON session_ending_owed(delivered,turn_id);\x0aCREATE TABLE session_forward(\x0a forward_id BIGINT NOT NULL,\x0a target_ref VARCHAR(6) NOT NULL,\x0a child_ref VARCHAR(6) NOT NULL,\x0a kind BIGINT NOT NULL,\x0a source_id BIGINT NOT NULL,\x0a position BIGINT,\x0a ordinal BIGINT NOT NULL,\x0a delivered_at BIGINT,\x0a session_forward_open_lead BIGINT GENERATED ALWAYS AS (CASE WHEN position IS NULL THEN forward_id END) STORED,\x0a PRIMARY KEY(forward_id),\x0a UNIQUE(target_ref,kind,source_id),\x0a FOREIGN KEY(target_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(child_ref) REFERENCES session(session_ref),\x0a CHECK(forward_id>0),\x0a CHECK(kind BETWEEN 1 AND 2),\x0a CHECK(source_id>0),\x0a CHECK(position IS NULL OR position>0),\x0a CHECK(ordinal=0),\x0a CHECK(delivered_at IS NULL OR delivered_at>0),\x0a CHECK((position IS NULL)=(delivered_at IS NULL)),\x0a CHECK(target_ref<>child_ref)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX session_forward_open ON session_forward(session_forward_open_lead);\x0aCREATE INDEX session_forward_feed ON session_forward(target_ref,position);\x0aCREATE TABLE model_fact(\x0a model_id VARCHAR(256) NOT NULL,\x0a context_window BIGINT,\x0a efforts BIGINT NOT NULL,\x0a openai_listed TINYINT NOT NULL,\x0a generation BIGINT NOT NULL,\x0a PRIMARY KEY(model_id),\x0a CHECK(OCTET_LENGTH(model_id) BETWEEN 1 AND 256),\x0a CHECK(efforts BETWEEN 0 AND 63),\x0a CHECK(openai_listed IN (0,1))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE model_catalog_source(\x0a slot BIGINT NOT NULL,\x0a etag TEXT,\x0a generation BIGINT NOT NULL,\x0a fetched_at BIGINT NOT NULL,\x0a PRIMARY KEY(slot),\x0a CHECK(slot=1),\x0a CHECK(etag IS NULL OR OCTET_LENGTH(etag)<=512)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE action_operation ADD COLUMN action_operation_indeterminate_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN resolution_code='indeterminate' THEN session_ref END) STORED, ADD INDEX action_operation_indeterminate(action_operation_indeterminate_lead,parent_operation_id,call_ordinal);\x0aUPDATE store_meta SET meta_value='9' WHERE meta_key='wire_version' AND meta_value='8';\x0aALTER TABLE core_command DROP CHECK core_command_chk_2, ADD CHECK(kind BETWEEN 1 AND 6);\x0aCREATE TABLE session_archive(\x0a session_ref VARCHAR(6) NOT NULL,\x0a command_key VARCHAR(128),\x0a PRIMARY KEY(session_ref),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(command_key) REFERENCES session_stop(command_key)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session_archive_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a archived TINYINT NOT NULL,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(archived IN (0,1))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE session_stop ADD COLUMN parent_caused TINYINT NOT NULL DEFAULT 0 AFTER stopped_at, ADD CHECK(parent_caused IN (0,1));\x0aUPDATE session_stop SET parent_caused=1 WHERE command_key>='rui.core/stop/' AND command_key<'rui.core/stop0';\x0aALTER TABLE session_ending_owed ADD COLUMN suppress_message TINYINT NOT NULL DEFAULT 0, ADD CHECK(suppress_message IN (0,1));\x0aUPDATE store_meta SET meta_value='10' WHERE meta_key='wire_version' AND meta_value='9';\x0aCREATE TABLE session_skill_catalog(\x0a session_ref VARCHAR(6) NOT NULL,\x0a position BIGINT NOT NULL,\x0a catalog_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(session_ref,position),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(catalog_content_id) REFERENCES content(content_id),\x0a CHECK(position>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE conversation_entry MODIFY turn_id BIGINT NULL, ADD COLUMN source_catalog_position BIGINT AFTER source_revision, ADD UNIQUE(session_ref,source_catalog_position), ADD FOREIGN KEY(session_ref,source_catalog_position) REFERENCES session_skill_catalog(session_ref,position), DROP CHECK conversation_entry_chk_7, ADD CHECK((turn_id IS NULL)=(source_catalog_position IS NOT NULL)), ADD CHECK(source_catalog_position IS NULL OR source_catalog_position=session_position), ADD CHECK((entry_kind=1 AND source_admission_id IS NOT NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL) OR (entry_kind=2 AND source_admission_id IS NULL AND ((source_revision IS NOT NULL AND source_catalog_position IS NULL) OR (source_revision IS NULL AND source_catalog_position IS NOT NULL)) AND source_operation_id IS NULL) OR (entry_kind=3 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NOT NULL));\x0aCREATE TABLE message_skill(\x0a admission_id BIGINT NOT NULL,\x0a position BIGINT NOT NULL,\x0a name TEXT NOT NULL,\x0a content_id BIGINT NOT NULL,\x0a PRIMARY KEY(admission_id,position),\x0a FOREIGN KEY(admission_id) REFERENCES message_admission(admission_id),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a CHECK(position>0),\x0a CHECK(OCTET_LENGTH(name) BETWEEN 1 AND 64 AND (NOT REGEXP_LIKE(name,'[^a-z0-9-]','c')))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE conversation_entry_60(\x0a session_ref VARCHAR(6) NOT NULL,\x0a entry_ordinal BIGINT NOT NULL,\x0a session_position BIGINT NOT NULL,\x0a entry_kind BIGINT NOT NULL,\x0a turn_id BIGINT,\x0a source_admission_id BIGINT,\x0a source_revision BIGINT,\x0a source_catalog_position BIGINT,\x0a source_skill_admission_id BIGINT,\x0a source_skill_position BIGINT,\x0a source_operation_id BIGINT,\x0a source_item_ordinal BIGINT,\x0a content_id BIGINT NOT NULL,\x0a recorded_at BIGINT NOT NULL,\x0a PRIMARY KEY(session_ref,entry_ordinal),\x0a UNIQUE(source_admission_id),\x0a UNIQUE(session_ref,session_position),\x0a UNIQUE(session_ref,source_revision),\x0a UNIQUE(session_ref,source_catalog_position),\x0a UNIQUE(source_skil