tent_id FROM tool_record WHERE description_content_id IS NOT NULL) AND content_id NOT IN (SELECT input_schema_content_id FROM tool_record WHERE input_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT primary_content_id FROM core_command WHERE primary_content_id IS NOT NULL) AND content_id NOT IN (SELECT secondary_content_id FROM core_command WHERE secondary_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session_revision WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session_revision WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_admission WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT outcome_content_id FROM turn WHERE outcome_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM model_operation WHERE resolution_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_skill WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT catalog_content_id FROM session_skill_catalog WHERE catalog_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM conversation_entry WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT message_content_id FROM model_output_item WHERE message_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_item WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT text_content_id FROM model_output_part WHERE text_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_part WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT name_content_id FROM model_tool_call WHERE name_content_id IS NOT NULL) AND con