ED ALWAYS AS (CASE WHEN obligation_since IS NOT NULL THEN parent_ref END) STORED AFTER obligation_since, ADD INDEX session_obligation_parent(session_obligation_parent_lead,obligation_since,session_ref);\x0aCREATE INDEX session_forward_owed_message ON session_forward(target_ref,message_delivered);\x0aWITH RECURSIVE own_owed(session_ref,since) AS (SELECT t.session_ref,m.admitted_at AS since FROM turn t JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE t.outcome_code IS NULL UNION SELECT m.session_ref,m.admitted_at FROM message_admission m WHERE m.turn_id IS NULL AND m.admission_id>coalesce((SELECT admission_cutoff FROM session_stop WHERE session_ref=m.session_ref ORDER BY admission_cutoff DESC LIMIT 1),0) UNION SELECT f.target_ref,m.admitted_at FROM session_forward f LEFT JOIN action_operation a ON f.kind=1 AND a.action_id=f.source_id LEFT JOIN model_operation op ON op.operation_id=a.parent_operation_id JOIN turn t ON t.turn_id=CASE WHEN f.kind=2 THEN f.source_id ELSE op.turn_id END JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE f.position IS NULL OR f.message_delivered=0),owed(session_ref,since) AS (SELECT session_ref,since FROM own_owed UNION SELECT s.parent_ref,o.since FROM owed o JOIN session s ON s.session_ref=o.session_ref WHERE s.parent_ref IS NOT NULL) UPDATE session s JOIN (SELECT session_ref,min(since) AS since FROM owed GROUP BY session_ref) o ON o.session_ref=s.session_ref SET s.obligation_since=o.since;\x0aDELETE FROM store_meta WHERE meta_key='wire_version';\x0aSET @rui_pin_kind_ddl=NULL;\x0aSET @rui_pin_kind_ddl=(SELECT CONCAT('ALTER TABLE core_command DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, ADD CHECK(kind BETWEEN 1 AND 7)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='core_command' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='kind between 1 and 6');\x0aPREPARE rui_pin_kind FROM @rui_pin_kind_ddl;\x0aEXECUTE rui_pin_kind;\x0aDEALLOCATE PREPARE rui_pin_kind;\x0aSET @rui_pin_kind_ddl=NULL;\x0aCREATE TABLE session_pin(\x0a session_ref VARCHAR(6) NOT NULL,\x0a command_key VARCHAR(128),\x0a PRIMARY KEY(session_ref),\x0a UNIQUE(command_key),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session_pin_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a pinned TINYINT NOT NULL,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(pinned IN (0,1))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aSET @rui_background_kind_ddl=NULL;\x0aSET @rui_background_kind_ddl=(SELECT CONCAT('ALTER TABLE core_command DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, ADD CHECK(kind BETWEEN 1 AND 8)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='core_command' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='kind between 1 and 7');\x0aPREPARE rui_background_kind FROM @rui_background_kind_ddl;\x0aEXECUTE rui_background_kind;\x0aDEALLOCATE PREPARE rui_background_kind;\x0aSET @rui_background_kind_ddl=NULL;\x0aALTER TABLE action_operation ADD COLUMN background_content_id BIGINT AFTER approval_position, ADD COLUMN background_position BIGINT AFTER background_content_id, ADD COLUMN background_at BIGINT AFTER background_position, ADD FOREIGN KEY(background_content_id) REFERENCES content(content_id), ADD CHECK((background_content_id IS NULL AND background_position IS NULL) OR (background_content_id IS NOT NULL AND background_position IS NOT NULL AND background_position>0 AND (acceptance_position IS NULL OR background_position<acceptance_position))), ADD CHECK((background_position IS NULL AND background_at IS NULL) OR (background_position IS NOT NULL AND background_at IS NOT NULL AND background_at>0));\x0aALTER TABLE action_operation DROP INDEX action_operation_session_results, MODIFY action_operation_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL AND background_position IS NULL THEN session_ref END) STORED, ADD INDEX action_operation_session_results(action_operation_session_results_lead,parent_operation_id,acceptance_position);\x0aCREATE INDEX action_operation_background ON action_operation(session_ref,background_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_background_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL THEN session_ref END) STORED, ADD INDEX action_operation_background_results(action_operation_background_results_lead,parent_operation_id,background_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_background_ready_lead BIGINT GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL AND authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0 THEN parent_operation_id END) STORED, ADD INDEX action_operation_background_ready(action_operation_background_ready_lead,action_id);\x0aALTER TABLE action_operation ADD COLUMN action_operation_awaiting_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN authorized=0 AND resolution_code IS NULL THEN session_ref END) STORED, ADD INDEX action_operation_awaiting(action_operation_awaiting_lead,action_id);\x0aALTER TABLE session_stop ADD COLUMN action_cutoff BIGINT NOT NULL DEFAULT 0 CHECK(action_cutoff>=0) AFTER parent_caused;\x0aCREATE TABLE action_control_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a action_id TEXT NOT NULL,\x0a selected_action_id BIGINT,\x0a selection VARCHAR(10),\x0a selection_position BIGINT,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(selected_action_id) REFERENCES action_operation(action_id),\x0a CHECK(OCTET_LENGTH(action_id) BETWEEN 1 AND 20 AND (NOT REGEXP_LIKE(action_id,'[^0-9]','c'))),\x0a CHECK(selection IS NULL OR selection IN ('background','final')),\x0a CHECK(selection_position>0),\x0a CHECK((selected_action_id IS NULL AND selection IS NULL AND selection_position IS NULL) OR (selected_action_id IS NOT NULL AND selection IS NOT NULL AND selection_position IS NOT NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD COLUMN source_action_id BIGINT AFTER sender_position, ADD UNIQUE(source_action_id), ADD FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id), ADD CHECK(source_action_id IS NULL OR sender_session_ref IS NULL), MODIFY COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN sender_session_ref IS NULL AND source_action_id IS NULL THEN session_ref END) STORED;\x0aCREATE TABLE action_stop(\x0a source_action_id BIGINT NOT NULL,\x0a target_action_id BIGINT NOT NULL,\x0a PRIMARY KEY(source_action_id),\x0a FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id),\x0a FOREIGN KEY(target_action_id) REFERENCES action_operation(action_id),\x0a CHECK(source_action_id<>target_action_id)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX action_stop_target ON action_stop(target_action_id);\x0aALTER TABLE content ADD COLUMN form BIGINT NOT NULL DEFAULT 0, ADD CHECK(form IN (0,1) AND (form=0 OR private=0));\x0aCREATE TABLE content_part(\x0a content_id BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a part_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(content_id,ordinal),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(part_content_id) REFERENCES content(content_id),\x0a CHECK(ordinal>=0),\x0a CHECK(part_content_id<>content_id)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX content_part_by_part ON content_part(part_content_id);\x0aUPDATE core_command SET secondary_content_id=primary_content_id,primary_content_id=NULL WHERE kind=2 AND accepted=0;\x0aALTER TABLE session ADD COLUMN creator_ref VARCHAR(6) AFTER obligation_since, ADD FOREIGN KEY(creator_ref) REFERENCES session(session_ref), ADD CHECK(creator_ref IS NULL OR creator_ref<>session_ref);\x0aUPDATE session SET creator_ref=parent_ref;\x0aSET @rui_action_stop_kind_ddl=NULL;\x0aSET @rui_action_stop_kind_ddl=(SELECT CONCAT('ALTER TABLE core_command DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, ADD CHECK(kind BETWEEN 1 AND 9)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='core_command' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='kind between 1 and 8');\x0aPREPARE rui_action_stop_kind FROM @rui_action_stop_kind_ddl;\x0aEXECUTE rui_action_stop_kind;\x0aDEALLOCATE PREPARE rui_action_stop_kind;\x0aSET @rui_action_stop_kind_ddl=NULL;\x0aALTER TABLE action_stop RENAME TO action_stop_before_81;\x0aCREATE TABLE action_stop(\x0a stop_key VARCHAR(130) NOT NULL,\x0a source_action_id BIGINT,\x0a source_command_key VARCHAR(128),\x0a target_action_id BIGINT NOT NULL,\x0a PRIMARY KEY(stop_key),\x0a UNIQUE(source_action_id),\x0a UNIQUE(source_command_key),\x0a FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id),\x0a FOREIGN KEY(source_command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(target_action_id) REFERENCES action_operation(action_id),\x0a CHECK(OCTET_LENGTH(stop_key)<=130),\x0a CHECK(source_action_id<>target_action_id),\x0a CHECK((source_action_id IS NULL)<>(source_command_key IS NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO action_stop(stop_key,source_action_id,target_action_id) SELECT CONCAT('a/',source_action_id),source_action_id,target_action_id FROM action_stop_before_81;\x0aDROP TABLE action_stop_before_81;\x0aCREATE INDEX action_stop_target ON action_stop(target_action_id);\x0aCREATE TABLE action_stop_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a action_id TEXT NOT NULL,\x0a resolution_position BIGINT,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(OCTET_LENGTH(action_id) BETWEEN 1 AND 20 AND (NOT REGEXP_LIKE(action_id,'[^0-9]','c'))),\x0a CHECK(resolution_position>0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD COLUMN source_kind BIGINT AFTER source_action_id;\x0aUPDATE message_admission SET source_kind=CASE WHEN sender_session_ref IS NOT NULL THEN 2 WHEN source_action_id IS NOT NULL THEN 3 ELSE 1 END;\x0aALTER TABLE message_admission MODIFY COLUMN source_kind BIGINT NOT NULL, ADD CHECK(source_kind BETWEEN 1 AND 5), ADD CHECK((source_kind=1 AND sender_session_ref IS NULL AND source_action_id IS NULL) OR (source_kind=2 AND sender_session_ref IS NOT NULL) OR (source_kind=3 AND source_action_id IS NOT NULL) OR (source_kind IN (4,5) AND sender_session_ref IS NULL)), MODIFY COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN source_kind=1 THEN session_ref END) STORED;\x0aCREATE TABLE action_value(action_id BIGINT NOT NULL, ordinal BIGINT NOT NULL, handle VARCHAR(32) NOT NULL, publication_key VARCHAR(128) NOT NULL, content_id BIGINT NOT NULL, admission_id BIGINT, published_at BIGINT NOT NULL, PRIMARY KEY(action_id,ordinal), UNIQUE(handle,publication_key), UNIQUE(admission_id), FOREIGN KEY(action_id) REFERENCES action_operation(action_id), FOREIGN KEY(content_id) REFERENCES content(content_id), FOREIGN KEY(admission_id) REFERENCES message_admission(admission_id), CHECK(ordinal>0), CHECK(OCTET_LENGTH(handle)=32 AND NOT REGEXP_LIKE(handle,'[^0-9a-f]','c')), CHECK(OCTET_LENGTH(publication_key) BETWEEN 1 AND 128), CHECK(published_at>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD UNIQUE(admission_id,source_kind);\x0aALTER TABLE conversation_entry ADD COLUMN source_kind BIGINT NULL AFTER source_admission_id;\x0aUPDATE conversation_entry e LEFT JOIN message_admission m ON m.admission_id=e.source_admission_id SET e.source_kind=m.source_kind;\x0aALTER TABLE conversation_entry ADD CHECK((entry_kind=1)=(source_kind IS NOT NULL)), ADD FOREIGN KEY(source_admission_id,source_kind) REFERENCES message_admission(admission_id,source_kind);\x0aCREATE INDEX conversation_entry_activity_user ON conversation_entry(session_ref,entry_kind,source_kind,session_position);\x0aCREATE INDEX conversation_entry_activity_assistant ON conversation_entry(session_ref,entry_kind,session_position);\x0aCREATE INDEX message_admission_activity ON message_admission(session_ref,source_kind,admission_position);\x0aCREATE INDEX session_creator ON session(creator_ref,session_ref);\x0aALTER TABLE session ADD COLUMN archive_seq BIGINT AFTER creator_ref, ADD CHECK(archive_seq IS NULL OR archive_seq>0), ADD FOREIGN KEY(archive_seq) REFERENCES core_command(command_seq);\x0aUPDATE session s JOIN session_archive a ON a.session_ref=s.session_ref JOIN core_command c ON c.command_key=a.command_key SET s.archive_seq=c.command_seq WHERE a.command_key IS NOT NULL;\x0aCREATE INDEX session_tab ON session(archive_seq,created_seq);\x0aDROP TABLE session_archive;\x0aUPDATE tool_set_member member JOIN tool_record cur ON cur.tool_record_id=member.tool_record_id JOIN (SELECT min(tool_record_id) AS keep_id,name,owner,server,description_content_id,input_schema_content_id FROM tool_record GROUP BY name,owner,server,description_content_id,input_schema_content_id) keep ON keep.name=cur.name AND keep.owner=cur.owner AND keep.server=cur.server AND keep.description_content_id=cur.description_content_id AND keep.input_schema_content_id=cur.input_schema_content_id SET member.tool_record_id=keep.keep_id;\x0aDELETE cur FROM tool_record cur JOIN (SELECT min(tool_record_id) AS keep_id,name,owner,server,description_content_id,input_schema_content_id FROM tool_record GROUP BY name,owner,server,description_content_id,input_schema_content_id) keep ON keep.name=cur.name AND keep.owner=cur.owner AND keep.server=cur.server AND keep.description_content_id=cur.description_content_id AND keep.input_schema_content_id=cur.input_schema_content_id WHERE cur.tool_record_id<>keep.keep_id;\x0aSET @rui_read_only_ddl=NULL;\x0aSET @rui_read_only_ddl=IF((SELECT count(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tool_record' AND COLUMN_NAME='read_only')=0,'DO 0',(SELECT CONCAT('ALTER TABLE tool_record DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, DROP INDEX name, DROP COLUMN read_only, ADD UNIQUE(name,owner,server,description_content_id,input_schema_content_id)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='tool_record' AND tc.CONSTRAINT_TYPE='CHECK' AND cc.CHECK_CLAUSE LIKE '%read_only%'));\x0aPREPARE rui_read_only FROM @rui_read_only_ddl;\x0aEXECUTE rui_read_only;\x0aDEALLOCATE PREPARE rui_read_only;\x0aSET @rui_read_only_ddl=NULL;\x0aALTER TABLE action_operation ADD COLUMN action_operation_unaccepted_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NULL THEN session_ref END) STORED AFTER action_operation_approval_lead, ADD INDEX action_operation_unaccepted(action_operation_unaccepted_lead);\x0aALTER TABLE turn ADD COLUMN turn_outcome_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN outcome_position IS NULL THEN session_ref END) STORED AFTER turn_unpositioned_lead, ADD INDEX turn_outcome_unpositioned(turn_outcome_unpositioned_lead);\x0aUPDATE session SET creator_ref=(SELECT opening.sender_session_ref FROM message_admission opening WHERE opening.admission_id=(SELECT MIN(m.admission_id) FROM message_admission m WHERE m.session_ref=session.session_ref)) WHERE creator_ref IS NULL AND EXISTS(SELECT 1 FROM message_admission opening WHERE opening.admission_id=(SELECT MIN(m.admission_id) FROM message_admission m WHERE m.session_ref=session.session_ref) AND opening.sender_session_ref IS NOT NULL AND opening.sender_session_ref<>session.session_ref);\x0aDELETE FROM sent_rejection WHERE command_key IN (SELECT command_key FROM core_command WHERE accepted=0 AND code='incomplete_initial_configuration');\x0aDELETE FROM core_command WHERE accepted=0 AND code='incomplete_initial_configuration';\x0aALTER TABLE core_command ADD COLUMN missing_settings BIGINT AFTER command_seq, ADD CHECK(missing_settings IS NULL AND code<>'missing_settings' OR missing_settings IS NOT NULL AND code='missing_settings' AND missing_settings BETWEEN 1 AND 7);\x0aALTER TABLE tool_record ADD COLUMN remote_name VARCHAR(64) NOT NULL DEFAULT '' AFTER name;\x0aALTER TABLE tool_record ALTER COLUMN remote_name DROP DEFAULT;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,remote_name,owner,server,description_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(OCTET_LENGTH(remote_name)<=64 AND (NOT REGEXP_LIKE(remote_name,'[^A-Za-z0-9_-]','c')));\x0aALTER TABLE model_fact ADD COLUMN output_limit BIGINT AFTER generation, ADD CHECK(output_limit IS NULL OR output_limit BETWEEN 0 AND 4294967295);\x0aALTER TABLE model_operation ADD COLUMN output_limit BIGINT NOT NULL DEFAULT 32000 AFTER context_window, ADD CHECK(output_limit BETWEEN 0 AND 4294967295);\x0aSET @rui_owner_ddl=(SELECT CONCAT('ALTER TABLE tool_record DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='tool_record' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='owner = _utf8mb4''rui'' or owner = _utf8mb4''provider'' or owner = _utf8mb4''mcp''';\x0aPREPARE rui_owner_check FROM @rui_owner_ddl;\x0aEXECUTE rui_owner_check;\x0aDEALLOCATE PREPARE rui_owner_check;\x0aALTER TABLE tool_record ADD CHECK((owner='rui' OR owner='provider' OR owner='mcp' OR owner='app'));\x0aALTER TABLE tool_record ADD COLUMN replay VARCHAR(6) NOT NULL DEFAULT '' AFTER server;\x0aALTER TABLE tool_record ALTER COLUMN replay DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN restart_limit BIGINT NOT NULL DEFAULT 0 AFTER replay;\x0aALTER TABLE tool_record ALTER COLUMN restart_limit DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN wait_ms BIGINT NOT NULL DEFAULT 0 AFTER restart_limit;\x0aALTER TABLE tool_record ALTER COLUMN wait_ms DROP DEFAULT;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,remote_name,owner,server,replay,restart_limit,wait_ms,description_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(OCTET_LENGTH(replay)<=6 AND replay IN ('','unsafe','safe') AND (owner='app' AND replay<>'' OR owner<>'app' AND replay=''));\x0aALTER TABLE tool_record ADD CHECK((owner='app' AND restart_limit BETWEEN 0 AND 16 OR owner<>'app' AND restart_limit=0));\x0aALTER TABLE tool_record ADD CHECK((owner='app' AND wait_ms BETWEEN 1000 AND 3600000 OR owner<>'app' AND wait_ms=0));\x0aALTER TABLE tool_record ADD CHECK(replay<>'unsafe' OR restart_limit=0);\x0aUPDATE store_meta SET meta_value='92' WHERE meta_key='format';\x0a", "CREATE TABLE session_stop_owed(\x0a child_ref VARCHAR(6) NOT NULL,\x0a cause_ref VARCHAR(6) NOT NULL,\x0a cause_position BIGINT NOT NULL,\x0a settled BIGINT NOT NULL,\x0a PRIMARY KEY(child_ref,cause_ref,cause_position),\x0a FOREIGN KEY(child_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(cause_ref) REFERENCES session(session_ref),\x0a CHECK(cause_position>0),\x0a CHECK(settled BETWEEN 0 AND 1)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX session_stop_open ON session_stop_owed(settled,child_ref);\x0aCREATE INDEX session_parent ON session(parent_ref);\x0aALTER TABLE session ADD COLUMN loaded_tool_set_id BIGINT AFTER tool_set_id,ADD FOREIGN KEY(loaded_tool_set_id) REFERENCES tool_set(tool_set_id);\x0aALTER TABLE session_revision ADD COLUMN loaded_tool_set_id BIGINT AFTER tool_set_id,ADD FOREIGN KEY(loaded_tool_set_id) REFERENCES tool_set(tool_set_id);\x0aALTER TABLE session_change DROP CHECK session_change_chk_4,ADD CHECK((field='provider' OR field='model' OR field='instructions' OR field='tools' OR field='loaded_tools' OR field='permission_mode' OR field='output_schema' OR field='compaction_trigger' OR field='output_reservation' OR field='reasoning_effort' OR field='label'));\x0aALTER TABLE store_meta DROP CHECK store_meta_chk_1, ADD CHECK((meta_key='wire_version' OR meta_key='store_selector' OR meta_key='format' OR meta_key='store_id'));\x0aCREATE TABLE store_owner(\x0a owner_key BIGINT NOT NULL,\x0a epoch BIGINT NOT NULL,\x0a commit_seq BIGINT NOT NULL,\x0a PRIMARY KEY(owner_key),\x0a CHECK(owner_key=1),\x0a CHECK(epoch>=0),\x0a CHECK(commit_seq>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE content_chunk(\x0a content_id BIGINT NOT NULL,\x0a chunk_index BIGINT NOT NULL,\x0a bytes LONGBLOB NOT NULL,\x0a PRIMARY KEY(content_id,chunk_index),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a CHECK(chunk_index>=0),\x0a CHECK(length(bytes) BETWEEN 1 AND 131072)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO content_chunk(content_id,chunk_index,bytes) WITH digit(d) AS (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9), chunk(i) AS (SELECT a.d+10*b.d+100*c.d+1000*e.d FROM digit a CROSS JOIN digit b CROSS JOIN digit c CROSS JOIN digit e) SELECT content.content_id,chunk.i,SUBSTRING(content.payload,chunk.i*131072+1,131072) FROM content JOIN chunk ON chunk.i*131072<content.byte_length;\x0aALTER TABLE content DROP CHECK content_chk_4, DROP COLUMN payload;\x0aALTER TABLE message_admission ADD COLUMN message_admission_pending_lead BIGINT GENERATED ALWAYS AS (CASE WHEN turn_id IS NULL THEN admission_id END) STORED, ADD COLUMN message_admission_session_pending_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN turn_id IS NULL THEN session_ref END) STORED, ADD COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN sender_session_ref IS NULL THEN session_ref END) STORED, ADD COLUMN message_admission_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN admission_position IS NULL THEN session_ref END) STORED, DROP INDEX message_admission_pending, ADD INDEX message_admission_pending(message_admission_pending_lead,session_ref), DROP INDEX message_admission_session_pending, ADD INDEX message_admission_session_pending(message_admission_session_pending_lead,admission_id), DROP INDEX message_admission_person, ADD INDEX message_admission_person(message_admission_person_lead,admission_position), DROP INDEX message_admission_unpositioned, ADD INDEX message_admission_unpositioned(message_admission_unpositioned_lead);\x0aALTER TABLE turn ADD COLUMN turn_tool_continuation_lead BIGINT GENERATED ALWAYS AS (CASE WHEN outcome_code IS NULL AND continuation_operation_id=operation_id THEN operation_id END) STORED, ADD COLUMN turn_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN (outcome_code IS NULL)!=(outcome_position IS NULL) THEN session_ref END) STORED, DROP INDEX turn_tool_continuation, ADD INDEX turn_tool_continuation(turn_tool_continuation_lead), DROP INDEX turn_unpositioned, ADD INDEX turn_unpositioned(turn_unpositioned_lead);\x0aALTER TABLE session_stop ADD COLUMN session_stop_unpositioned_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN position IS NULL THEN session_ref END) STORED, DROP INDEX session_stop_unpositioned, ADD INDEX session_stop_unpositioned(session_stop_unpositioned_lead);\x0aALTER TABLE model_operation ADD COLUMN model_operation_retry_due_lead BIGINT GENERATED ALWAYS AS (CASE WHEN resolution_code IS NULL AND attempt_ordinal<4 THEN retry_due_at_ms END) STORED, ADD COLUMN model_operation_retry_exhausted_lead BIGINT GENERATED ALWAYS AS (CASE WHEN resolution_code IS NULL AND retry_due_at_ms=0 AND attempt_ordinal=4 THEN operation_id END) STORED, ADD COLUMN model_operation_context_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN (resolution_code='answer' OR resolution_code='compacted' OR resolution_code='tool_proposals') THEN session_ref END) STORED, ADD COLUMN model_operation_compaction_bases_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN purpose=1 AND resolution_code='compacted' THEN session_ref END) STORED, DROP INDEX model_operation_retry_due, ADD INDEX model_operation_retry_due(model_operation_retry_due_lead,operation_id), DROP INDEX model_operation_retry_exhausted, ADD INDEX model_operation_retry_exhausted(model_operation_retry_exhausted_lead), DROP INDEX model_operation_context_history, ADD INDEX model_operation_context_history(model_operation_context_history_lead,admission_position), DROP INDEX model_operation_compaction_bases, ADD INDEX model_operation_compaction_bases(model_operation_compaction_bases_lead,admission_position);\x0aALTER TABLE model_output_item ADD COLUMN model_output_call_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN item_kind=3 THEN session_ref END) STORED, ADD COLUMN model_output_hosted_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN item_kind=5 THEN session_ref END) STORED, ADD COLUMN model_output_compaction_history_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN item_kind=4 THEN session_ref END) STORED, ADD COLUMN model_output_compaction_anchor_lead BIGINT GENERATED ALWAYS AS (CASE WHEN item_kind=4 THEN operation_id END) STORED, DROP INDEX model_output_call_history, ADD INDEX model_output_call_history(model_output_call_history_lead,session_position), DROP INDEX model_output_hosted_history, ADD INDEX model_output_hosted_history(model_output_hosted_history_lead,session_position), DROP INDEX model_output_compaction_history, ADD INDEX model_output_compaction_history(model_output_compaction_history_lead,session_position), DROP INDEX model_output_compaction_anchor, ADD INDEX model_output_compaction_anchor(model_output_compaction_anchor_lead,item_ordinal);\x0aALTER TABLE model_tool_call ADD COLUMN model_tool_call_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED, ADD COLUMN model_tool_call_acceptance_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED, DROP INDEX model_tool_call_session_results, ADD INDEX model_tool_call_session_results(model_tool_call_session_results_lead,operation_id,acceptance_position), DROP INDEX model_tool_call_acceptance, ADD INDEX model_tool_call_acceptance(model_tool_call_acceptance_lead,acceptance_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL THEN session_ref END) STORED, ADD COLUMN action_operation_approval_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN approval_position IS NOT NULL THEN session_ref END) STORED, ADD COLUMN action_operation_executable_lead BIGINT GENERATED ALWAYS AS (CASE WHEN authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0 THEN action_id END) STORED, ADD COLUMN action_operation_unresolved_attempt_lead BIGINT GENERATED ALWAYS AS (CASE WHEN resolution_code IS NULL AND attempt_ordinal=1 THEN action_id END) STORED, DROP INDEX action_operation_session_results, ADD INDEX action_operation_session_results(action_operation_session_results_lead,parent_operation_id,acceptance_position), DROP INDEX action_operation_approval, ADD INDEX action_operation_approval(action_operation_approval_lead,approval_position), DROP INDEX action_operation_executable, ADD INDEX action_operation_executable(action_operation_executable_lead), DROP INDEX action_operation_unresolved_attempt, ADD INDEX action_operation_unresolved_attempt(action_operation_unresolved_attempt_lead);\x0aALTER TABLE session ADD COLUMN session_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN parent_ref IS NOT NULL THEN parent_ref END) STORED, ADD INDEX parent_ref(parent_ref);\x0aALTER TABLE session DROP INDEX session_parent, ADD INDEX session_parent(session_parent_lead);\x0aCREATE TABLE session_ending_owed(\x0a turn_id BIGINT NOT NULL,\x0a delivered BIGINT NOT NULL,\x0a PRIMARY KEY(turn_id),\x0a FOREIGN KEY(turn_id) REFERENCES turn(turn_id),\x0a CHECK(turn_id>0),\x0a CHECK(delivered BETWEEN 0 AND 1)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX session_ending_open ON session_ending_owed(delivered,turn_id);\x0aCREATE TABLE session_forward(\x0a forward_id BIGINT NOT NULL,\x0a target_ref VARCHAR(6) NOT NULL,\x0a child_ref VARCHAR(6) NOT NULL,\x0a kind BIGINT NOT NULL,\x0a source_id BIGINT NOT NULL,\x0a position BIGINT,\x0a ordinal BIGINT NOT NULL,\x0a delivered_at BIGINT,\x0a session_forward_open_lead BIGINT GENERATED ALWAYS AS (CASE WHEN position IS NULL THEN forward_id END) STORED,\x0a PRIMARY KEY(forward_id),\x0a UNIQUE(target_ref,kind,source_id),\x0a FOREIGN KEY(target_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(child_ref) REFERENCES session(session_ref),\x0a CHECK(forward_id>0),\x0a CHECK(kind BETWEEN 1 AND 2),\x0a CHECK(source_id>0),\x0a CHECK(position IS NULL OR position>0),\x0a CHECK(ordinal=0),\x0a CHECK(delivered_at IS NULL OR delivered_at>0),\x0a CHECK((position IS NULL)=(delivered_at IS NULL)),\x0a CHECK(target_ref<>child_ref)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX session_forward_open ON session_forward(session_forward_open_lead);\x0aCREATE INDEX session_forward_feed ON session_forward(target_ref,position);\x0aCREATE TABLE model_fact(\x0a model_id VARCHAR(256) NOT NULL,\x0a context_window BIGINT,\x0a efforts BIGINT NOT NULL,\x0a openai_listed TINYINT NOT NULL,\x0a generation BIGINT NOT NULL,\x0a PRIMARY KEY(model_id),\x0a CHECK(OCTET_LENGTH(model_id) BETWEEN 1 AND 256),\x0a CHECK(efforts BETWEEN 0 AND 63),\x0a CHECK(openai_listed IN (0,1))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE model_catalog_source(\x0a slot BIGINT NOT NULL,\x0a etag TEXT,\x0a generation BIGINT NOT NULL,\x0a fetched_at BIGINT NOT NULL,\x0a PRIMARY KEY(slot),\x0a CHECK(slot=1),\x0a CHECK(etag IS NULL OR OCTET_LENGTH(etag)<=512)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE action_operation ADD COLUMN action_operation_indeterminate_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN resolution_code='indeterminate' THEN session_ref END) STORED, ADD INDEX action_operation_indeterminate(action_operation_indeterminate_lead,parent_operation_id,call_ordinal);\x0aUPDATE store_meta SET meta_value='9' WHERE meta_key='wire_version' AND meta_value='8';\x0aALTER TABLE core_command DROP CHECK core_command_chk_2, ADD CHECK(kind BETWEEN 1 AND 6);\x0aCREATE TABLE session_archive(\x0a session_ref VARCHAR(6) NOT NULL,\x0a command_key VARCHAR(128),\x0a PRIMARY KEY(session_ref),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(command_key) REFERENCES session_stop(command_key)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session_archive_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a archived TINYINT NOT NULL,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(archived IN (0,1))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE session_stop ADD COLUMN parent_caused TINYINT NOT NULL DEFAULT 0 AFTER stopped_at, ADD CHECK(parent_caused IN (0,1));\x0aUPDATE session_stop SET parent_caused=1 WHERE command_key>='rui.core/stop/' AND command_key<'rui.core/stop0';\x0aALTER TABLE session_ending_owed ADD COLUMN suppress_message TINYINT NOT NULL DEFAULT 0, ADD CHECK(suppress_message IN (0,1));\x0aUPDATE store_meta SET meta_value='10' WHERE meta_key='wire_version' AND meta_value='9';\x0aCREATE TABLE session_skill_catalog(\x0a session_ref VARCHAR(6) NOT NULL,\x0a position BIGINT NOT NULL,\x0a catalog_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(session_ref,position),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(catalog_content_id) REFERENCES content(content_id),\x0a CHECK(position>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE conversation_entry MODIFY turn_id BIGINT NULL, ADD COLUMN source_catalog_position BIGINT AFTER source_revision, ADD UNIQUE(session_ref,source_catalog_position), ADD FOREIGN KEY(session_ref,source_catalog_position) REFERENCES session_skill_catalog(session_ref,position), DROP CHECK conversation_entry_chk_7, ADD CHECK((turn_id IS NULL)=(source_catalog_position IS NOT NULL)), ADD CHECK(source_catalog_position IS NULL OR source_catalog_position=session_position), ADD CHECK((entry_kind=1 AND source_admission_id IS NOT NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL) OR (entry_kind=2 AND source_admission_id IS NULL AND ((source_revision IS NOT NULL AND source_catalog_position IS NULL) OR (source_revision IS NULL AND source_catalog_position IS NOT NULL)) AND source_operation_id IS NULL) OR (entry_kind=3 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NOT NULL));\x0aCREATE TABLE message_skill(\x0a admission_id BIGINT NOT NULL,\x0a position BIGINT NOT NULL,\x0a name TEXT NOT NULL,\x0a content_id BIGINT NOT NULL,\x0a PRIMARY KEY(admission_id,position),\x0a FOREIGN KEY(admission_id) REFERENCES message_admission(admission_id),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a CHECK(position>0),\x0a CHECK(OCTET_LENGTH(name) BETWEEN 1 AND 64 AND (NOT REGEXP_LIKE(name,'[^a-z0-9-]','c')))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE conversation_entry_60(\x0a session_ref VARCHAR(6) NOT NULL,\x0a entry_ordinal BIGINT NOT NULL,\x0a session_position BIGINT NOT NULL,\x0a entry_kind BIGINT NOT NULL,\x0a turn_id BIGINT,\x0a source_admission_id BIGINT,\x0a source_revision BIGINT,\x0a source_catalog_position BIGINT,\x0a source_skill_admission_id BIGINT,\x0a source_skill_position BIGINT,\x0a source_operation_id BIGINT,\x0a source_item_ordinal BIGINT,\x0a content_id BIGINT NOT NULL,\x0a recorded_at BIGINT NOT NULL,\x0a PRIMARY KEY(session_ref,entry_ordinal),\x0a UNIQUE(source_admission_id),\x0a UNIQUE(session_ref,session_position),\x0a UNIQUE(session_ref,source_revision),\x0a UNIQUE(session_ref,source_catalog_position),\x0a UNIQUE(source_skill_admission_id,source_skill_position),\x0a FOREIGN KEY(turn_id) REFERENCES turn(turn_id),\x0a FOREIGN KEY(source_admission_id) REFERENCES message_admission(admission_id),\x0a FOREIGN KEY(source_operation_id) REFERENCES model_operation(operation_id),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(session_ref,source_revision) REFERENCES session_revision(session_ref,revision),\x0a FOREIGN KEY(session_ref,source_catalog_position) REFERENCES session_skill_catalog(session_ref,position),\x0a FOREIGN KEY(source_skill_admission_id,source_skill_position) REFERENCES message_skill(admission_id,position),\x0a CHECK(entry_ordinal>0),\x0a CHECK(session_position>0),\x0a CHECK(entry_kind BETWEEN 1 AND 4),\x0a CHECK(source_item_ordinal IS NULL OR source_item_ordinal>=0),\x0a CHECK(recorded_at>0),\x0a CHECK((entry_kind=3)=(source_item_ordinal IS NOT NULL)),\x0a CHECK((turn_id IS NULL)=(source_catalog_position IS NOT NULL)),\x0a CHECK(source_catalog_position IS NULL OR source_catalog_position=session_position),\x0a CHECK((source_skill_admission_id IS NULL)=(source_skill_position IS NULL)),\x0a CHECK((entry_kind=4)=(source_skill_position IS NOT NULL)),\x0a CHECK((entry_kind=1 AND source_admission_id IS NOT NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL) OR (entry_kind=2 AND source_admission_id IS NULL AND ((source_revision IS NOT NULL AND source_catalog_position IS NULL) OR (source_revision IS NULL AND source_catalog_position IS NOT NULL)) AND source_operation_id IS NULL) OR (entry_kind=3 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NOT NULL) OR (entry_kind=4 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO conversation_entry_60(session_ref,entry_ordinal,session_position,entry_kind,turn_id,source_admission_id,source_revision,source_catalog_position,source_operation_id,source_item_ordinal,content_id,recorded_at) SELECT session_ref,entry_ordinal,session_position,entry_kind,turn_id,source_admission_id,source_revision,source_catalog_position,source_operation_id,source_item_ordinal,content_id,recorded_at FROM conversation_entry;\x0aDROP TABLE conversation_entry;\x0aRENAME TABLE conversation_entry_60 TO conversation_entry;\x0aCREATE INDEX conversation_entry_history ON conversation_entry(session_ref,session_position);\x0aALTER TABLE conversation_entry ADD FOREIGN KEY(source_operation_id,source_item_ordinal) REFERENCES model_output_item(operation_id,item_ordinal);\x0aUPDATE store_meta SET meta_value='11' WHERE meta_key='wire_version' AND meta_value='10';\x0aALTER TABLE model_output_item DROP CHECK model_output_item_chk_10, ADD CHECK(description IS NULL OR (OCTET_LENGTH(description) BETWEEN 1 AND 200 AND (description IS NOT NULL)=(item_kind=5)));\x0aALTER TABLE model_tool_call DROP CHECK model_tool_call_chk_3, ADD CHECK(description IS NULL OR OCTET_LENGTH(description) BETWEEN 1 AND 200);\x0aALTER TABLE tool_record ADD COLUMN read_only TINYINT NOT NULL DEFAULT 0 AFTER server;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,owner,server,read_only,description_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(read_only IN (0,1) AND (read_only=0 OR owner='mcp'));\x0aALTER TABLE model_operation DROP FOREIGN KEY model_operation_ibfk_3, DROP CHECK model_operation_chk_28, ADD CHECK((usage_uncached_tokens IS NULL AND usage_cache_read_tokens IS NULL AND usage_cache_write_tokens IS NULL AND usage_output_tokens IS NULL) OR (usage_uncached_tokens IS NOT NULL AND usage_cache_read_tokens IS NOT NULL AND usage_cache_write_tokens IS NOT NULL AND usage_output_tokens IS NOT NULL));\x0aDELETE FROM content_chunk WHERE content_id IN (SELECT usage_content_id FROM model_operation) AND content_id NOT IN (SELECT description_content_id FROM tool_record WHERE description_content_id IS NOT NULL) AND content_id NOT IN (SELECT input_schema_content_id FROM tool_record WHERE input_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT primary_content_id FROM core_command WHERE primary_content_id IS NOT NULL) AND content_id NOT IN (SELECT secondary_content_id FROM core_command WHERE secondary_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session_revision WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session_revision WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_admission WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT outcome_content_id FROM turn WHERE outcome_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM model_operation WHERE resolution_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_skill WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT catalog_content_id FROM session_skill_catalog WHERE catalog_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM conversation_entry WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT message_content_id FROM model_output_item WHERE message_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_item WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT text_content_id FROM model_output_part WHERE text_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_part WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT name_content_id FROM model_tool_call WHERE name_content_id IS NOT NULL) AND content_id NOT IN (SELECT call_id_content_id FROM model_tool_call WHERE call_id_content_id IS NOT NULL) AND content_id NOT IN (SELECT arguments_content_id FROM model_tool_call WHERE arguments_content_id IS NOT NULL) AND content_id NOT IN (SELECT rejection_content_id FROM model_tool_call WHERE rejection_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM action_operation WHERE resolution_content_id IS NOT NULL);\x0aDELETE FROM content WHERE content_id IN (SELECT usage_content_id FROM model_operation) AND content_id NOT IN (SELECT description_content_id FROM tool_record WHERE description_content_id IS NOT NULL) AND content_id NOT IN (SELECT input_schema_content_id FROM tool_record WHERE input_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT primary_content_id FROM core_command WHERE primary_content_id IS NOT NULL) AND content_id NOT IN (SELECT secondary_content_id FROM core_command WHERE secondary_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session_revision WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session_revision WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_admission WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT outcome_content_id FROM turn WHERE outcome_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM model_operation WHERE resolution_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_skill WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT catalog_content_id FROM session_skill_catalog WHERE catalog_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM conversation_entry WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT message_content_id FROM model_output_item WHERE message_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_item WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT text_content_id FROM model_output_part WHERE text_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_part WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT name_content_id FROM model_tool_call WHERE name_content_id IS NOT NULL) AND content_id NOT IN (SELECT call_id_content_id FROM model_tool_call WHERE call_id_content_id IS NOT NULL) AND content_id NOT IN (SELECT arguments_content_id FROM model_tool_call WHERE arguments_content_id IS NOT NULL) AND content_id NOT IN (SELECT rejection_content_id FROM model_tool_call WHERE rejection_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM action_operation WHERE resolution_content_id IS NOT NULL);\x0aALTER TABLE model_operation DROP COLUMN usage_content_id;\x0aRENAME TABLE host_catalog TO host_tool_set;\x0aALTER TABLE action_operation DROP CHECK action_operation_chk_8, DROP CHECK action_operation_chk_17;\x0aALTER TABLE action_operation RENAME COLUMN bash_timeout_ms TO attempt_timeout_ms;\x0aALTER TABLE action_operation ADD CHECK(attempt_timeout_ms IS NULL OR attempt_timeout_ms>0), ADD CHECK((attempt_ordinal=0 AND attempt_timeout_ms IS NULL) OR (attempt_ordinal=1 AND attempt_timeout_ms IS NOT NULL));\x0aALTER TABLE model_operation ADD COLUMN tool_set_id BIGINT AFTER history_dropped;\x0aUPDATE model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision SET o.tool_set_id=coalesce(r.loaded_tool_set_id,r.tool_set_id);\x0aALTER TABLE model_operation MODIFY tool_set_id BIGINT NOT NULL,ADD CHECK(tool_set_id>0),ADD FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id);\x0aCREATE TABLE revision_effort_before_66 AS SELECT r.session_ref,r.revision,(SELECT choice.revision FROM session_revision choice LEFT JOIN session_revision before_choice ON before_choice.session_ref=choice.session_ref AND before_choice.revision=choice.revision-1 WHERE choice.session_ref=r.session_ref AND choice.revision<=r.revision AND (choice.revision=1 OR choice.model<>before_choice.model OR NOT (choice.reasoning_effort<=>before_choice.reasoning_effort) OR EXISTS(SELECT 1 FROM session_change changed WHERE changed.session_ref=choice.session_ref AND changed.revision=choice.revision AND changed.field IN ('reasoning_effort','model'))) ORDER BY choice.revision DESC LIMIT 1) AS effort_source_revision FROM session_revision r;\x0aALTER TABLE session_revision ADD COLUMN effort_source_revision BIGINT NOT NULL DEFAULT 1,ADD CHECK(effort_source_revision>0 AND effort_source_revision<=revision),ADD FOREIGN KEY(session_ref,effort_source_revision) REFERENCES session_revision(session_ref,revision);\x0aUPDATE session_revision r JOIN revision_effort_before_66 frozen ON frozen.session_ref=r.session_ref AND frozen.revision=r.revision SET r.effort_source_revision=frozen.effort_source_revision;\x0aDROP TABLE revision_effort_before_66;\x0aCREATE TABLE model_effort_before_66 AS SELECT o.operation_id,r.effort_source_revision AS effort_source_revision,(SELECT prior_effort.reasoning_effort FROM model_operation prior_effort JOIN session_revision prior_model ON prior_model.session_ref=prior_effort.session_ref AND prior_model.revision=prior_effort.settings_revision WHERE prior_effort.session_ref=o.session_ref AND prior_effort.admission_position<o.admission_position AND prior_model.model=r.model ORDER BY prior_effort.admission_position DESC LIMIT 1) AS previous_reasoning_effort,(SELECT earlier_model.reasoning_effort FROM model_operation earlier JOIN session_revision earlier_model ON earlier_model.session_ref=earlier.session_ref AND earlier_model.revision=earlier.settings_revision WHERE earlier.session_ref=o.session_ref AND earlier.admission_position<o.admission_position AND earlier_model.model=r.model ORDER BY earlier.admission_position DESC LIMIT 1) AS previous_effort_override,(s.codec='openai-responses/2' AND o.reasoning_effort IS NOT NULL AND NOT (o.reasoning_effort<=>(SELECT CASE WHEN retained.operation_id IS NOT NULL THEN retained.reasoning_effort WHEN first_effort.operation_id IS NOT NULL THEN first_effort.reasoning_effort ELSE o.reasoning_effort END FROM session effort_seed LEFT JOIN model_operation effort_base ON effort_base.operation_id=(SELECT selected.operation_id FROM model_operation selected WHERE selected.session_ref=o.session_ref AND selected.purpose=1 AND selected.resolution_code='compacted' AND selected.admission_position<o.admission_position ORDER BY selected.admission_position DESC LIMIT 1) LEFT JOIN session_revision effort_base_model ON effort_base_model.session_ref=effort_base.session_ref AND effort_base_model.revision=effort_base.settings_revision LEFT JOIN model_operation retained ON retained.operation_id=(SELECT earlier.operation_id FROM model_operation earlier JOIN session_revision earlier_model ON earlier_model.session_ref=earlier.session_ref AND earlier_model.revision=earlier.settings_revision WHERE earlier.session_ref=o.session_ref AND earlier.admission_position<o.admission_position AND earlier_model.model=r.model AND earlier.admission_position>greatest(coalesce(o.history_floor,0),CASE WHEN effort_base_model.model=r.model THEN coalesce(effort_base.history_floor,0) ELSE 0 END) AND earlier.admission_position>=CASE WHEN effort_base_model.model=r.model THEN coalesce((SELECT min(anchor.session_position) FROM model_output_item anchor WHERE anchor.operation_id=effort_base.operation_id AND anchor.item_kind=4),0) ELSE 0 END ORDER BY earlier.admission_position DESC LIMIT 1) LEFT JOIN model_operation first_effort ON first_effort.operation_id=(SELECT first.operation_id FROM model_operation first JOIN session_revision first_model ON first_model.session_ref=first.session_ref AND first_model.revision=first.settings_revision WHERE first.session_ref=o.session_ref AND first_model.model=r.model AND first.admission_position<o.admission_position ORDER BY first.admission_position LIMIT 1) WHERE effort_seed.session_ref=o.session_ref))) AS effort_update FROM model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision JOIN session s ON s.session_ref=o.session_ref;\x0aCREATE UNIQUE INDEX model_effort_before_66_key ON model_effort_before_66(operation_id);\x0aALTER TABLE model_operation ADD COLUMN effort_source_revision BIGINT NOT NULL DEFAULT 1 AFTER tool_set_id,ADD CHECK(effort_source_revision>0 AND effort_source_revision<=settings_revision),ADD COLUMN previous_reasoning_effort VARCHAR(6) AFTER effort_source_revision,ADD CHECK(previous_reasoning_effort IS NULL OR (previous_reasoning_effort='none' OR previous_reasoning_effort='low' OR previous_reasoning_effort='medium' OR previous_reasoning_effort='high' OR previous_reasoning_effort='xhigh' OR previous_reasoning_effort='max')),ADD COLUMN effort_update TINYINT NOT NULL DEFAULT 0 AFTER previous_reasoning_effort,ADD CHECK(effort_update IN (0,1) AND (effort_update=0 OR reasoning_effort IS NOT NULL)),ADD COLUMN previous_effort_override VARCHAR(6) AFTER effort_update,ADD CHECK(previous_effort_override IS NULL OR (previous_effort_override='none' OR previous_effort_override='low' OR previous_effort_override='medium' OR previous_effort_override='high' OR previous_effort_override='xhigh' OR previous_effort_override='max'));\x0aUPDATE model_operation o JOIN model_effort_before_66 frozen ON frozen.operation_id=o.operation_id SET o.effort_source_revision=frozen.effort_source_revision,o.previous_reasoning_effort=frozen.previous_reasoning_effort,o.effort_update=frozen.effort_update,o.previous_effort_override=frozen.previous_effort_override;\x0aDROP TABLE model_effort_before_66;\x0aCREATE UNIQUE INDEX model_operation_effort_source ON model_operation(operation_id,session_ref,effort_source_revision);\x0aCREATE TABLE session_change_66(\x0a session_ref VARCHAR(6) NOT NULL,\x0a position BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a revision BIGINT NOT NULL,\x0a field VARCHAR(24) NOT NULL,\x0a changed_at BIGINT NOT NULL,\x0a provider_text TEXT,\x0a refused_operation_id BIGINT,\x0a PRIMARY KEY(session_ref,position,ordinal),\x0a UNIQUE(session_ref,revision,field),\x0a INDEX session_change_refused_operation(refused_operation_id,session_ref,revision),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(session_ref,revision) REFERENCES session_revision(session_ref,revision),\x0a CHECK(position>0),\x0a CHECK(ordinal>=0),\x0a CHECK(revision>1),\x0a CHECK((field='provider' OR field='model' OR field='instructions' OR field='tools' OR field='loaded_tools' OR field='permission_mode' OR field='output_schema' OR field='compaction_trigger' OR field='output_reservation' OR field='reasoning_effort' OR field='label' OR field='reasoning_effort_refused')),\x0a CHECK(changed_at>0),\x0a CHECK(provider_text IS NULL OR OCTET_LENGTH(provider_text)<=520),\x0a FOREIGN KEY(refused_operation_id,session_ref,revision) REFERENCES model_operation(operation_id,session_ref,effort_source_revision),\x0a CHECK((field='reasoning_effort_refused')=(provider_text IS NOT NULL)),\x0a CHECK((field='reasoning_effort_refused')=(refused_operation_id IS NOT NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO session_change_66(session_ref,position,ordinal,revision,field,changed_at) SELECT session_ref,position,ordinal,revision,field,changed_at FROM session_change;\x0aDROP TABLE session_change;\x0aRENAME TABLE session_change_66 TO session_change;\x0aUPDATE store_meta SET meta_value='13' WHERE meta_key='wire_version' AND meta_value='12';\x0aALTER TABLE session_forward ADD COLUMN message_delivered TINYINT AFTER delivered_at, ADD COLUMN suppress_message TINYINT NOT NULL DEFAULT 0 AFTER message_delivered;\x0aALTER TABLE session_forward ADD CHECK(message_delivered IS NULL OR message_delivered IN (0,1)), ADD CHECK(suppress_message IN (0,1));\x0aUPDATE session_forward f JOIN session child ON child.session_ref=f.child_ref JOIN session_ending_owed e ON f.kind=2 AND e.turn_id=f.source_id AND f.target_ref=child.parent_ref SET f.message_delivered=e.delivered,f.suppress_message=e.suppress_message;\x0aINSERT INTO session_forward(forward_id,target_ref,child_ref,kind,source_id,position,ordinal,delivered_at,message_delivered,suppress_message) SELECT COALESCE((SELECT max(forward_id) FROM session_forward),0)+ROW_NUMBER() OVER(ORDER BY e.turn_id),child.parent_ref,t.session_ref,2,e.turn_id,NULL,0,NULL,e.delivered,e.suppress_message FROM session_ending_owed e JOIN turn t ON t.turn_id=e.turn_