(action_operation_indeterminate_lead,parent_operation_id,call_ordinal);\x0aUPDATE store_meta SET meta_value='9' WHERE meta_key='wire_version' AND meta_value='8';\x0aALTER TABLE core_command DROP CHECK core_command_chk_2, ADD CHECK(kind BETWEEN 1 AND 6);\x0aCREATE TABLE session_archive(\x0a session_ref VARCHAR(6) NOT NULL,\x0a command_key VARCHAR(128),\x0a PRIMARY KEY(session_ref),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(command_key) REFERENCES session_stop(command_key)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session_archive_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a archived TINYINT NOT NULL,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(archived IN (0,1))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE session_stop ADD COLUMN parent_caused TINYINT NOT NULL DEFAULT 0 AFTER stopped_at, ADD CHECK(parent_caused IN (0,1));\x0aUPDATE session_stop SET parent_caused=1 WHERE command_key>='rui.core/stop/' AND command_key<'rui.core/stop0';\x0aALTER TABLE session_ending_owed ADD COLUMN suppress_message TINYINT NOT NULL DEFAULT 0, ADD CHECK(suppress_message IN (0,1));\x0aUPDATE store_meta SET meta_value='10' WHERE meta_key='wire_version' AND meta_value='9';\x0aCREATE TABLE session_skill_catalog(\x0a session_ref VARCHAR(6) NOT NULL,\x0a position BIGINT NOT NULL,\x0a catalog_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(session_ref,position),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(catalog_content_id) REFERENCES content(content_id),\x0a CHECK(position>=0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE conversation_entry MODIFY turn_id BIGINT NULL, ADD COLUMN source_catalog_position BIGINT AFTER source_revision, ADD UNIQUE(session_ref,source_catalog_position), ADD FOREIGN KEY(session_ref,source_catalog_position) REFERENCES session_skill_catalog(session_ref,position), DROP CHECK conversation_entry_chk_7, ADD CHECK((turn_id IS NULL)=(source_catalog_position IS NOT NULL)), ADD CHECK(source_catalog_position IS NULL OR source_catalog_position=session_position), ADD CHECK((entry_kind=1 AND source_admission_id IS NOT NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL) OR (entry_kind=2 AND source_admission_id IS NULL AND ((source_revision IS NOT NULL AND source_catalog_position IS NULL) OR (source_revision IS NULL AND source_catalog_position IS NOT NULL)) AND source_operation_id IS NULL) OR (entry_kind=3 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NOT NULL));\x0aCREATE TABLE message_skill(\x0a admission_id BIGINT NOT NULL,\x0a position BIGINT NOT NULL,\x0a name TEXT NOT NULL,\x0a content_id BIGINT NOT NULL,\x0a PRIMARY KEY(admission_id,position),\x0a FOREIGN KEY(admission_id) REFERENCES message_admission(admission_id),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a CHECK(position>0),\x0a CHECK(OCTET_LENGTH(name) BETWEEN 1 AND 64 AND (NOT REGEXP_LIKE(name,'[^a-z0-9-]','c')))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE conversation_entry_60(\x0a session_ref VARCHAR(6) NOT NULL,\x0a entry_ordinal BIGINT NOT NULL,\x0a session_position BIGINT NOT NULL,\x0a entry_kind BIGINT NOT NULL,\x0a turn_id BIGINT,\x0a source_admission_id BIGINT,\x0a source_revision BIGINT,\x0a source_catalog_position BIGINT,\x0a source_skill_admission_id BIGINT,\x0a source_skill_position BIGINT,\x0a source_operation_id BIGINT,\x0a source_item_ordinal BIGINT,\x0a content_id BIGINT NOT NULL,\x0a recorded_at BIGINT NOT NULL,\x0a PRIMARY KEY(session_ref,entry_ordinal),\x0a UNIQUE(source_admission_id),\x0a UNIQUE(session_ref,session_position),\x0a UNIQUE(session_ref,source_revision),\x0a UNIQUE(session_ref,source_catalog_position),\x0a UNIQUE(source_skill_admission_id,source_skill_position),\x0a FOREIGN KEY(turn_id) REFERENCES turn(turn_id),\x0a FOREIGN KEY(source_admission_id) REFERENCES message_admission(admission_id),\x0a FOREIGN KEY(source_operation_id) REFERENCES model_operation(operation_id),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(session_ref,source_revision) REFERENCES session_revision(session_ref,revision),\x0a FOREIGN KEY(session_ref,source_catalog_position) REFERENCES session_skill_catalog(session_ref,position),\x0a FOREIGN KEY(source_skill_admission_id,source_skill_position) REFERENCES message_skill(admission_id,position),\x0a CHECK(entry_ordinal>0),\x0a CHECK(session_position>0),\x0a CHECK(entry_kind BETWEEN 1 AND 4),\x0a CHECK(source_item_ordinal IS NULL OR source_item_ordinal>=0),\x0a CHECK(recorded_at>0),\x0a CHECK((entry_kind=3)=(source_item_ordinal IS NOT NULL)),\x0a CHECK((turn_id IS NULL)=(source_catalog_position IS NOT NULL)),\x0a CHECK(source_catalog_position IS NULL OR source_catalog_position=session_position),\x0a CHECK((source_skill_admission_id IS NULL)=(source_skill_position IS NULL)),\x0a CHECK((entry_kind=4)=(source_skill_position IS NOT NULL)),\x0a CHECK((entry_kind=1 AND source_admission_id IS NOT NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL) OR (entry_kind=2 AND source_admission_id IS NULL AND ((source_revision IS NOT NULL AND source_catalog_position IS NULL) OR (source_revision IS NULL AND source_catalog_position IS NOT NULL)) AND source_operation_id IS NULL) OR (entry_kind=3 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NOT NULL) OR (entry_kind=4 AND source_admission_id IS NULL AND source_revision IS NULL AND source_catalog_position IS NULL AND source_operation_id IS NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO conversation_entry_60(session_ref,entry_ordinal,session_position,entry_kind,turn_id,source_admission_id,source_revision,source_catalog_position,source_operation_id,source_item_ordinal,content_id,recorded_at) SELECT session_ref,entry_ordinal,session_position,entry_kind,turn_id,source_admission_id,source_revision,source_catalog_position,source_operation_id,source_item_ordinal,content_id,recorded_at FROM conversation_entry;\x0aDROP TABLE conversation_entry;\x0aRENAME TABLE conversation_entry_60 TO conversation_entry;\x0aCREATE INDEX conversation_entry_history ON conversation_entry(session_ref,session_position);\x0aALTER TABLE conversation_entry ADD FOREIGN KEY(source_operation_id,source_item_ordinal) REFERENCES model_output_item(operation_id,item_ordinal);\x0aUPDATE store_meta SET meta_value='11' WHERE meta_key='wire_version' AND meta_value='10';\x0aALTER TABLE model_output_item DROP CHECK model_output_item_chk_10, ADD CHECK(description IS NULL OR (OCTET_LENGTH(description) BETWEEN 1 AND 200 AND (description IS NOT NULL)=(item_kind=5)));\x0aALTER TABLE model_tool_call DROP CHECK model_tool_call_chk_3, ADD CHECK(description IS NULL OR OCTET_LENGTH(description) BETWEEN 1 AND 200);\x0aALTER TABLE tool_record ADD COLUMN read_only TINYINT NOT NULL DEFAULT 0 AFTER server;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,owner,server,read_only,description_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(read_only IN (0,1) AND (read_only=0 OR owner='mcp'));\x0aALTER TABLE model_operation DROP FOREIGN KEY model_operation_ibfk_3, DROP CHECK model_operation_chk_28, ADD CHECK((usage_uncached_tokens IS NULL AND usage_cache_read_tokens IS NULL AND usage_cache_write_tokens IS NULL AND usage_output_tokens IS NULL) OR (usage_uncached_tokens IS NOT NULL AND usage_cache_read_tokens IS NOT NULL AND usage_cache_write_tokens IS NOT NULL AND usage_output_tokens IS NOT NULL));\x0aDELETE FROM content_chunk WHERE content_id IN (SELECT usage_content_id FROM model_operation) AND content_id NOT IN (SELECT description_content_id FROM tool_record WHERE description_content_id IS NOT NULL) AND content_id NOT IN (SELECT input_schema_content_id FROM tool_record WHERE input_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT primary_content_id FROM core_command WHERE primary_content_id IS NOT NULL) AND content_id NOT IN (SELECT secondary_content_id FROM core_command WHERE secondary_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session_revision WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session_revision WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_admission WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT outcome_content_id FROM turn WHERE outcome_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM model_operation WHERE resolution_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_skill WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT catalog_content_id FROM session_skill_catalog WHERE catalog_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM conversation_entry WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT message_content_id FROM model_output_item WHERE message_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_item WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT text_content_id FROM model_output_part WHERE text_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_part WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT name_content_id FROM model_tool_call WHERE name_content_id IS NOT NULL) AND content_id NOT IN (SELECT call_id_content_id FROM model_tool_call WHERE call_id_content_id IS NOT NULL) AND content_id NOT IN (SELECT arguments_content_id FROM model_tool_call WHERE arguments_content_id IS NOT NULL) AND content_id NOT IN (SELECT rejection_content_id FROM model_tool_call WHERE rejection_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM action_operation WHERE resolution_content_id IS NOT NULL);\x0aDELETE FROM content WHERE content_id IN (SELECT usage_content_id FROM model_operation) AND content_id NOT IN (SELECT description_content_id FROM tool_record WHERE description_content_id IS NOT NULL) AND content_id NOT IN (SELECT input_schema_content_id FROM tool_record WHERE input_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT primary_content_id FROM core_command WHERE primary_content_id IS NOT NULL) AND content_id NOT IN (SELECT secondary_content_id FROM core_command WHERE secondary_content_id IS NOT NULL) AND content_id NOT IN (SELECT instructions_content_id FROM session_revision WHERE instructions_content_id IS NOT NULL) AND content_id NOT IN (SELECT output_schema_content_id FROM session_revision WHERE output_schema_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_admission WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT outcome_content_id FROM turn WHERE outcome_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM model_operation WHERE resolution_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM message_skill WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT catalog_content_id FROM session_skill_catalog WHERE catalog_content_id IS NOT NULL) AND content_id NOT IN (SELECT content_id FROM conversation_entry WHERE content_id IS NOT NULL) AND content_id NOT IN (SELECT message_content_id FROM model_output_item WHERE message_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_item WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT text_content_id FROM model_output_part WHERE text_content_id IS NOT NULL) AND content_id NOT IN (SELECT extras_content_id FROM model_output_part WHERE extras_content_id IS NOT NULL) AND content_id NOT IN (SELECT name_content_id FROM model_tool_call WHERE name_content_id IS NOT NULL) AND content_id NOT IN (SELECT call_id_content_id FROM model_tool_call WHERE call_id_content_id IS NOT NULL) AND content_id NOT IN (SELECT arguments_content_id FROM model_tool_call WHERE arguments_content_id IS NOT NULL) AND content_id NOT IN (SELECT rejection_content_id FROM model_tool_call WHERE rejection_content_id IS NOT NULL) AND content_id NOT IN (SELECT resolution_content_id FROM action_operation WHERE resolution_content_id IS NOT NULL);\x0aALTER TABLE model_operation DROP COLUMN usage_content_id;\x0aRENAME TABLE host_catalog TO host_tool_set;\x0aALTER TABLE action_operation DROP CHECK action_operation_chk_8, DROP CHECK action_operation_chk_17;\x0aALTER TABLE action_operation RENAME COLUMN bash_timeout_ms TO attempt_timeout_ms;\x0aALTER TABLE action_operation ADD CHECK(attempt_timeout_ms IS NULL OR attempt_timeout_ms>0), ADD CHECK((attempt_ordinal=0 AND attempt_timeout_ms IS NULL) OR (attempt_ordinal=1 AND attempt_timeout_ms IS NOT NULL));\x0aALTER TABLE model_operation ADD COLUMN tool_set_id BIGINT AFTER history_dropped;\x0aUPDATE model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision SET o.tool_set_id=coalesce(r.loaded_tool_set_id,r.tool_set_id);\x0aALTER TABLE model_operation MODIFY tool_set_id BIGINT NOT NULL,ADD CHECK(tool_set_id>0),ADD FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id);\x0aCREATE TABLE revision_effort_before_66 AS SELECT r.session_ref,r.revision,(SELECT choice.revision FROM session_revision choice LEFT JOIN session_revision before_choice ON before_choice.session_ref=choice.session_ref AND before_choice.revision=choice.revision-1 WHERE choice.session_ref=r.session_ref AND choice.revision<=r.revision AND (choice.revision=1 OR choice.model<>before_choice.model OR NOT (choice.reasoning_effort<=>before_choice.reasoning_effort) OR EXISTS(SELECT 1 FROM session_change changed WHERE changed.session_ref=choice.session_ref AND changed.revision=choice.revision AND changed.field IN ('reasoning_effort','model'))) ORDER BY choice.revision DESC LIMIT 1) AS effort_source_revision FROM session_revision r;\x0aALTER TABLE session_revision ADD COLUMN effort_source_revision BIGINT NOT NULL DEFAULT 1,ADD CHECK(effort_source_revision>0 AND effort_source_revision<=revision),ADD FOREIGN KEY(session_ref,effort_source_revision) REFERENCES session_revision(session_ref,revision);\x0aUPDATE session_revision r JOIN revision_effort_before_66 frozen ON frozen.session_ref=r.session_ref AND frozen.revision=r.revision SET r.effort_source_revision=frozen.effort_source_revision;\x0aDROP TABLE revision_effort_before_66;\x0aCREATE TABLE model_effort_before_66 AS SELECT o.operation_id,r.effort_source_revision AS effort_source_revision,(SELECT prior_effort.reasoning_effort FROM model_operation prior_effort JOIN session_revision prior_model ON prior_model.session_ref=prior_effort.session_ref AND prior_model.revision=prior_effort.settings_revision WHERE prior_effort.session_ref=o.session_ref AND prior_effort.admission_position<o.admission_position AND prior_model.model=r.model ORDER BY prior_effort.admission_position DESC LIMIT 1) AS previous_reasoning_effort,(SELECT earlier_model.reasoning_effort FROM model_operation earlier JOIN session_revision earlier_model ON earlier_model.session_ref=earlier.session_ref AND earlier_model.revision=earlier.settings_revision WHERE earlier.session_ref=o.session_ref AND earlier.admission_position<o.admission_position AND earlier_model.model=r.model ORDER BY earlier.admission_position DESC LIMIT 1) AS previous_effort_override,(s.codec='openai-responses/2' AND o.reasoning_effort IS NOT NULL AND NOT (o.reasoning_effort<=>(SELECT CASE WHEN retained.operation_id IS NOT NULL THEN retained.reasoning_effort WHEN first_effort.operation_id IS NOT NULL THEN first_effort.reasoning_effort ELSE o.reasoning_effort END FROM session effort_seed LEFT JOIN model_operation effort_base ON effort_base.operation_id=(SELECT selected.operation_id FROM model_operation selected WHERE selected.session_ref=o.session_ref AND selected.purpose=1 AND selected.resolution_code='compacted' AND selected.admission_position<o.admission_position ORDER BY selected.admission_position DESC LIMIT 1) LEFT JOIN session_revision effort_base_model ON effort_base_model.session_ref=effort_base.session_ref AND effort_base_model.revision=effort_base.settings_revision LEFT JOIN model_operation retained ON retained.operation_id=(SELECT earlier.operation_id FROM model_operation earlier JOIN session_revision earlier_model ON earlier_model.session_ref=earlier.session_ref AND earlier_model.revision=earlier.settings_revision WHERE earlier.session_ref=o.session_ref AND earlier.admission_position<o.admission_position AND earlier_model.model=r.model AND earlier.admission_position>greatest(coalesce(o.history_floor,0),CASE WHEN effort_base_model.model=r.model THEN coalesce(effort_base.history_floor,0) ELSE 0 END) AND earlier.admission_position>=CASE WHEN effort_base_model.model=r.model THEN coalesce((SELECT min(anchor.session_position) FROM model_output_item anchor WHERE anchor.operation_id=effort_base.operation_id AND anchor.item_kind=4),0) ELSE 0 END ORDER BY earlier.admission_position DESC LIMIT 1) LEFT JOIN model_operation first_effort ON first_effort.operation_id=(SELECT first.operation_id FROM model_operation first JOIN session_revision first_model ON first_model.session_ref=first.session_ref AND first_model.revision=first.settings_revision WHERE first.session_ref=o.session_ref AND first_model.model=r.model AND first.admission_position<o.admission_position ORDER BY first.admission_position LIMIT 1) WHERE effort_seed.session_ref=o.session_ref))) AS effort_update FROM model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision JOIN session s ON s.session_ref=o.session_ref;\x0aCREATE UNIQUE INDEX model_effort_before_66_key ON model_effort_before_66(operation_id);\x0aALTER TABLE model_operation ADD COLUMN effort_source_revision BIGINT NOT NULL DEFAULT 1 AFTER tool_set_id,ADD CHECK(effort_source_revision>0 AND effort_source_revision<=settings_revision),ADD COLUMN previous_reasoning_effort VARCHAR(6) AFTER effort_source_revision,ADD CHECK(previous_reasoning_effort IS NULL OR (previous_reasoning_effort='none' OR previous_reasoning_effort='low' OR previous_reasoning_effort='medium' OR previous_reasoning_effort='high' OR previous_reasoning_effort='xhigh' OR previous_reasoning_effort='max')),ADD COLUMN effort_update TINYINT NOT NULL DEFAULT 0 AFTER previous_reasoning_effort,ADD CHECK(effort_update IN (0,1) AND (effort_update=0 OR reasoning_effort IS NOT NULL)),ADD COLUMN previous_effort_override VARCHAR(6) AFTER effort_update,ADD CHECK(previous_effort_override IS NULL OR (previous_effort_override='none' OR previous_effort_override='low' OR previous_effort_override='medium' OR previous_effort_override='high' OR previous_effort_override='xhigh' OR previous_effort_override='max'));\x0aUPDATE model_operation o JOIN model_effort_before_66 frozen ON frozen.operation_id=o.operation_id SET o.effort_source_revision=frozen.effort_source_revision,o.previous_reasoning_effort=frozen.previous_reasoning_effort,o.effort_update=frozen.effort_update,o.previous_effort_override=frozen.previous_effort_override;\x0aDROP TABLE model_effort_before_66;\x0aCREATE UNIQUE INDEX model_operation_effort_source ON model_operation(operation_id,session_ref,effort_source_revision);\x0aCREATE TABLE session_change_66(\x0a session_ref VARCHAR(6) NOT NULL,\x0a position BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a revision BIGINT NOT NULL,\x0a field VARCHAR(24) NOT NULL,\x0a changed_at BIGINT NOT NULL,\x0a provider_text TEXT,\x0a refused_operation_id BIGINT,\x0a PRIMARY KEY(session_ref,position,ordinal),\x0a UNIQUE(session_ref,revision,field),\x0a INDEX session_change_refused_operation(refused_operation_id,session_ref,revision),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(session_ref,revision) REFERENCES session_revision(session_ref,revision),\x0a CHECK(position>0),\x0a CHECK(ordinal>=0),\x0a CHECK(revision>1),\x0a CHECK((field='provider' OR field='model' OR field='instructions' OR field='tools' OR field='loaded_tools' OR field='permission_mode' OR field='output_schema' OR field='compaction_trigger' OR field='output_reservation' OR field='reasoning_effort' OR field='label' OR field='reasoning_effort_refused')),\x0a CHECK(changed_at>0),\x0a CHECK(provider_text IS NULL OR OCTET_LENGTH(provider_text)<=520),\x0a FOREIGN KEY(refused_operation_id,session_ref,revision) REFERENCES model_operation(operation_id,session_ref,effort_source_revision),\x0a CHECK((field='reasoning_effort_refused')=(provider_text IS NOT NULL)),\x0a CHECK((field='reasoning_effort_refused')=(refused_operation_id IS NOT NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO session_change_66(session_ref,position,ordinal,revision,field,changed_at) SELECT session_ref,position,ordinal,revision,field,changed_at FROM session_change;\x0aDROP TABLE session_change;\x0aRENAME TABLE session_change_66 TO session_change;\x0aUPDATE store_meta SET meta_value='13' WHERE meta_key='wire_version' AND meta_value='12';\x0aALTER TABLE session_forward ADD COLUMN message_delivered TINYINT AFTER delivered_at, ADD COLUMN suppress_message TINYINT NOT NULL DEFAULT 0 AFTER message_delivered;\x0aALTER TABLE session_forward ADD CHECK(message_delivered IS NULL OR message_delivered IN (0,1)), ADD CHECK(suppress_message IN (0,1));\x0aUPDATE session_forward f JOIN session child ON child.session_ref=f.child_ref JOIN session_ending_owed e ON f.kind=2 AND e.turn_id=f.source_id AND f.target_ref=child.parent_ref SET f.message_delivered=e.delivered,f.suppress_message=e.suppress_message;\x0aINSERT INTO session_forward(forward_id,target_ref,child_ref,kind,source_id,position,ordinal,delivered_at,message_delivered,suppress_message) SELECT COALESCE((SELECT max(forward_id) FROM session_forward),0)+ROW_NUMBER() OVER(ORDER BY e.turn_id),child.parent_ref,t.session_ref,2,e.turn_id,NULL,0,NULL,e.delivered,e.suppress_message FROM session_ending_owed e JOIN turn t ON t.turn_id=e.turn_id JOIN session child ON child.session_ref=t.session_ref WHERE child.parent_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM session_forward f WHERE f.target_ref=child.parent_ref AND f.kind=2 AND f.source_id=e.turn_id);\x0aDROP TABLE session_ending_owed;\x0aCREATE INDEX session_forward_message ON session_forward(message_delivered,source_id);\x0aALTER TABLE model_operation ADD COLUMN latency_ms BIGINT CHECK(latency_ms IS NULL OR latency_ms>=0) AFTER previous_effort_override, ADD COLUMN first_event_ms BIGINT CHECK(first_event_ms IS NULL OR first_event_ms>=0) AFTER latency_ms;\x0aCREATE TEMPORARY TABLE operation_window_backfill(model_id VARCHAR(256) NOT NULL PRIMARY KEY,context_window BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO operation_window_backfill(model_id,context_window) VALUES('@cf/deepseek-ai/deepseek-r1-distill-qwen-32b',80000),('@cf/deepseek-ai/deepseek-v4-flash-0731',1048576),('@cf/deepseek-ai/deepseek-v4-pro-0813',1048576),('@cf/deepseek-ai/deepseek-v4.1-flash-1017',1048576),('@cf/google/gemma-4-26b-a4b-it',256000),('@cf/ibm-granite/granite-4.0-h-micro',131000),('@cf/meta/llama-3.1-8b-instruct-fp8',32000),('@cf/meta/llama-3.2-1b-instruct',60000),('@cf/meta/llama-3