ed.model_id=r.model SET o.context_window=coalesce(pinned.context_window,128000);\x0aALTER TABLE model_operation MODIFY COLUMN context_window BIGINT NOT NULL, ADD CHECK(context_window BETWEEN 0 AND 4294967295);\x0aDROP TEMPORARY TABLE operation_window_backfill;\x0aUPDATE store_meta SET meta_value='14' WHERE meta_key='wire_version' AND meta_value='13';\x0aUPDATE store_meta SET meta_value='15' WHERE meta_key='wire_version' AND meta_value='14';\x0aUPDATE store_meta SET meta_value='16' WHERE meta_key='wire_version' AND meta_value='15';\x0aALTER TABLE session ADD COLUMN obligation_since BIGINT CHECK(obligation_since IS NULL OR obligation_since>0) AFTER parent_ref;\x0aALTER TABLE session ADD COLUMN session_obligation_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN obligation_since IS NOT NULL THEN parent_ref END) STORED AFTER obligation_since, ADD INDEX session_obligation_parent(session_obligation_parent_lead,obligation_since,session_ref);\x0aCREATE INDEX session_forward_owed_message ON session_forward(target_ref,message_delivered);\x0aWITH RECURSIVE own_owed(session_ref,since) AS (SELECT t.session_ref,m.admitted_at AS since FROM turn t JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE t.outcome_code IS NULL UNION SELECT m.session_ref,m.admitted_at FROM message_admission m WHERE m.turn_id IS NULL AND m.admission_id>coalesce((SELECT admission_cutoff FROM session_stop WHERE session_ref=m.session_ref ORDER BY admission_cutoff DESC LIMIT 1),0) UNION SELECT f.target_ref,m.admitted_at FROM session_forward f LEFT JOIN action_operation a ON f.kind=1 AND a.action_id=f.source_id LEFT JOIN model_operation op ON op.operation_id=a.parent_operation_id JOIN turn t ON t.turn_id=CASE WHEN f.kind=2 THEN f.source_id ELSE op.turn_id END JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE f.position IS NULL OR f.message_delivered=0),owed(session_ref,since) AS (SELECT session_ref,since FROM own_owed UNION SELECT s.parent_ref,o.since FROM owed o JOIN session s ON s.session_ref=o.session_ref WHERE s.parent_ref IS NOT NULL) UPDATE session s JOIN (SELECT session_ref,min(since) AS since FROM owed GROUP BY session_ref) o ON o.session_ref=s.session_ref SET s.obligation_since=o.since;\x0aDELETE FROM store_meta WHERE meta_key='wire_version';\x0aSET @rui_pin_kind_ddl=NULL;\x0aSET @rui_pin_kind_ddl=(SELECT CONCAT('ALTER TABLE core_command DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, ADD CHECK(kind BETWEEN 1 AND 7)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='core_command' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='kind between 1 and 6');\x0aPREPARE rui_pin_kind FROM @rui_pin_kind_ddl;\x0aEXECUTE rui_pin_kind;\x0aDEALLOCATE PREPARE rui_pin_kind;\x0aSET @rui_pin_kind_ddl=NULL;\x0aCREATE TABLE session_pin(\x0a session_ref VARCHAR(6) NOT NULL,\x0a command_key VARCHAR(128),\x0a PRIMARY KEY(session_ref),\x0a UNIQUE(command_key),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE TABLE session_pin_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a pinned TINYINT NOT NULL,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(pinned IN (0,1))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aSET @rui_background_kind_ddl=NULL;\x0aSET @rui_background_kind_ddl=(SELECT CONCAT('ALTER TABLE core_command DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, ADD CHECK(kind BETWEEN 1 AND 8)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='core_command' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='kind between 1 and 7');\x0aPREPARE rui_background_kind FROM @rui_background_kind_ddl;\x0aEXECUTE rui_background_kind;\x0aDEALLOCATE PREPARE rui_background_kind;\x0aSET @rui_background_kind_ddl=NULL;\x0aALTER TABLE action_operation ADD COLUMN background_content_id BIGINT AFTER approval_position, ADD COLUMN background_position BIGINT AFTER background_content_id, ADD COLUMN background_at BIGINT AFTER background_position, ADD FOREIGN KEY(background_content_id) REFERENCES content(content_id), ADD CHECK((background_content_id IS NULL AND background_position IS NULL) OR (background_content_id IS NOT NULL AND background_position IS NOT NULL AND background_position>0 AND (acceptance_position IS NULL OR background_position<acceptance_position))), ADD CHECK((background_position IS NULL AND background_at IS NULL) OR (background_position IS NOT NULL AND background_at IS NOT NULL AND background_at>0));\x0aALTER TABLE action_operation DROP INDEX action_operation_session_results, MODIFY action_operation_session_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN acceptance_position IS NOT NULL AND background_position IS NULL THEN session_ref END) STORED, ADD INDEX action_operation_session_results(action_operation_session_results_lead,parent_operation_id,acceptance_position);\x0aCREATE INDEX action_operation_background ON action_operation(session_ref,background_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_background_results_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL THEN session_ref END) STORED, ADD INDEX action_operation_background_results(action_operation_background_results_lead,parent_operation_id,background_position);\x0aALTER TABLE action_operation ADD COLUMN action_operation_background_ready_lead BIGINT GENERATED ALWAYS AS (CASE WHEN background_position IS NOT NULL AND authorized=1 AND resolution_code IS NULL AND attempt_ordinal=0 THEN parent_operation_id END) STORED, ADD INDEX action_operation_background_ready(action_operation_background_ready_lead,action_id);\x0aALTER TABLE action_operation ADD COLUMN action_operation_awaiting_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN authorized=0 AND resolution_code IS NULL THEN session_ref END) STORED, ADD INDEX action_operation_awaiting(action_operation_awaiting_lead,action_id);\x0aALTER TABLE session_stop ADD COLUMN action_cutoff BIGINT NOT NULL DEFAULT 0 CHECK(action_cutoff>=0) AFTER parent_caused;\x0aCREATE TABLE action_control_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a action_id TEXT NOT NULL,\x0a selected_action_id BIGINT,\x0a selection VARCHAR(10),\x0a selection_position BIGINT,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(selected_action_id) REFERENCES action_operation(action_id),\x0a CHECK(OCTET_LENGTH(action_id) BETWEEN 1 AND 20 AND (NOT REGEXP_LIKE(action_id,'[^0-9]','c'))),\x0a CHECK(selection IS NULL OR selection IN ('background','final')),\x0a CHECK(selection_position>0),\x0a CHECK((selected_action_id IS NULL AND selection IS NULL AND selection_position IS NULL) OR (selected_action_id IS NOT NULL AND selection IS NOT NULL AND selection_position IS NOT NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD COLUMN source_action_id BIGINT AFTER sender_position, ADD UNIQUE(source_action_id), ADD FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id), ADD CHECK(source_action_id IS NULL OR sender_session_ref IS NULL), MODIFY COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN sender_session_ref IS NULL AND source_action_id IS NULL THEN session_ref END) STORED;\x0aCREATE TABLE action_stop(\x0a source_action_id BIGINT NOT NULL,\x0a target_action_id BIGINT NOT NULL,\x0a PRIMARY KEY(source_action_id),\x0a FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id),\x0a FOREIGN KEY(target_action_id) REFERENCES action_operation(action_id),\x0a CHECK(source_action_id<>target_action_id)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX action_stop_target ON action_stop(target_action_id);\x0aALTER TABLE content ADD COLUMN form BIGINT NOT NULL DEFAULT 0, ADD CHECK(form IN (0,1) AND (form=0 OR private=0));\x0aCREATE TABLE content_part(\x0a content_id BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a part_content_id BIGINT NOT NULL,\x0a PRIMARY KEY(content_id,ordinal),\x0a FOREIGN KEY(content_id) REFERENCES content(content_id),\x0a FOREIGN KEY(part_content_id) REFERENCES content(content_id),\x0a CHECK(ordinal>=0),\x0a CHECK(part_content_id<>content_id)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aCREATE INDEX content_part_by_part ON content_part(part_content_id);\x0aUPDATE core_command SET secondary_content_id=primary_content_id,primary_content_id=NULL WHERE kind=2 AND accepted=0;\x0aALTER TABLE session ADD COLUMN creator_ref VARCHAR(6) AFTER obligation_since, ADD FOREIGN KEY(creator_ref) REFERENCES session(session_ref), ADD CHECK(creator_ref IS NULL OR creator_ref<>session_ref);\x0aUPDATE session SET creator_ref=parent_ref;\x0aSET @rui_action_stop_kind_ddl=NULL;\x0aSET @rui_action_stop_kind_ddl=(SELECT CONCAT('ALTER TABLE core_command DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, ADD CHECK(kind BETWEEN 1 AND 9)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='core_command' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='kind between 1 and 8');\x0aPREPARE rui_action_stop_kind FROM @rui_action_stop_kind_ddl;\x0aEXECUTE rui_action_stop_kind;\x0aDEALLOCATE PREPARE rui_action_stop_kind;\x0aSET @rui_action_stop_kind_ddl=NULL;\x0aALTER TABLE action_stop RENAME TO action_stop_before_81;\x0aCREATE TABLE action_stop(\x0a stop_key VARCHAR(130) NOT NULL,\x0a source_action_id BIGINT,\x0a source_command_key VARCHAR(128),\x0a target_action_id BIGINT NOT NULL,\x0a PRIMARY KEY(stop_key),\x0a UNIQUE(source_action_id),\x0a UNIQUE(source_command_key),\x0a FOREIGN KEY(source_action_id) REFERENCES action_operation(action_id),\x0a FOREIGN KEY(source_command_key) REFERENCES core_command(command_key),\x0a FOREIGN KEY(target_action_id) REFERENCES action_operation(action_id),\x0a CHECK(OCTET_LENGTH(stop_key)<=130),\x0a CHECK(source_action_id<>target_action_id),\x0a CHECK((source_action_id IS NULL)<>(source_command_key IS NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO action_stop(stop_key,source_action_id,target_action_id) SELECT CONCAT('a/',source_action_id),source_action_id,target_action_id FROM action_stop_before_81;\x0aDROP TABLE action_stop_before_81;\x0aCREATE INDEX action_stop_target ON action_stop(target_action_id);\x0aCREATE TABLE action_stop_command(\x0a command_key VARCHAR(128) NOT NULL,\x0a action_id TEXT NOT NULL,\x0a resolution_position BIGINT,\x0a PRIMARY KEY(command_key),\x0a FOREIGN KEY(command_key) REFERENCES core_command(command_key),\x0a CHECK(OCTET_LENGTH(action_id) BETWEEN 1 AND 20 AND (NOT REGEXP_LIKE(action_id,'[^0-9]','c'))),\x0a CHECK(resolution_position>0)\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD COLUMN source_kind BIGINT AFTER source_action_id;\x0aUPDATE message_admission SET source_kind=CASE WHEN sender_session_ref IS NOT NULL THEN 2 WHEN source_action_id IS NOT NULL THEN 3 ELSE 1 END;\x0aALTER TABLE message_admission MODIFY COLUMN source_kind BIGINT NOT NULL, ADD CHECK(source_kind BETWEEN 1 AND 5), ADD CHECK((source_kind=1 AND sender_session_ref IS NULL AND source_action_id IS NULL) OR (source_kind=2 AND sender_session_ref IS NOT NULL) OR (source_kind=3 AND source_action_id IS NOT NULL) OR (source_kind IN (4,5) AND sender_session_ref IS NULL)), MODIFY COLUMN message_admission_person_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN source_kind=1 THEN session_ref END) STORED;\x0aCREATE TABLE action_value(action_id BIGINT NOT NULL, ordinal BIGINT NOT NULL, handle VARCHAR(32) NOT NULL, publication_key VARCHAR(128) NOT NULL, content_id BIGINT NOT NULL, admission_id BIGINT, published_at BIGINT NOT NULL, PRIMARY KEY(action_id,ordinal), UNIQUE(handle,publication_key), UNIQUE(admission_id), FOREIGN KEY(action_id) REFERENCES action_operation(action_id), FOREIGN KEY(content_id) REFERENCES content(content_id), FOREIGN KEY(admission_id) REFERENCES message_admission(admission_id), CHECK(ordinal>0), CHECK(OCTET_LENGTH(handle)=32 AND NOT REGEXP_LIKE(handle,'[^0-9a-f]','c')), CHECK(OCTET_LENGTH(publication_key) BETWEEN 1 AND 128), CHECK(published_at>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aALTER TABLE message_admission ADD UNIQUE(admission_id,source_kind);\x0aALTER TABLE conversation_entry ADD COLUMN source_kind BIGINT NULL AFTER source_admission_id;\x0aUPDATE conversation_entry e LEFT JOIN message_admission m ON m.admission_id=e.source_admission_id SET e.source_kind=m.source_kind;\x0aALTER TABLE conversation_entry ADD CHECK((entry_kind=1)=(source_kind IS NOT NULL)), ADD FOREIGN KEY(source_admission_id,source_kind) REFERENCES message_admission(admission_id,source_kind);\x0aCREATE INDEX conversation_entry_activity_user ON conversation_entry(session_ref,entry_kind,source_kind,session_position);\x0aCREATE INDEX conversation_entry_activity_assistant ON conversation_entry(session_ref,entry_kind,session_position);\x0aCREATE INDEX message_admission_activity ON message_admission(session_ref,source_kind,admission_position);\x0aCREATE INDEX session_creator ON session(creator_ref,session_ref);\x0aALTER TABLE session ADD CO