record ALTER COLUMN remote_name DROP DEFAULT;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,remote_name,owner,server,description_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(OCTET_LENGTH(remote_name)<=64 AND (NOT REGEXP_LIKE(remote_name,'[^A-Za-z0-9_-]','c')));\x0aALTER TABLE model_fact ADD COLUMN output_limit BIGINT AFTER generation, ADD CHECK(output_limit IS NULL OR output_limit BETWEEN 0 AND 4294967295);\x0aALTER TABLE model_operation ADD COLUMN output_limit BIGINT NOT NULL DEFAULT 32000 AFTER context_window, ADD CHECK(output_limit BETWEEN 0 AND 4294967295);\x0aSET @rui_owner_ddl=(SELECT CONCAT('ALTER TABLE tool_record DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='tool_record' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='owner = _utf8mb4''rui'' or owner = _utf8mb4''provider'' or owner = _utf8mb4''mcp''';\x0aPREPARE rui_owner_check FROM @rui_owner_ddl;\x0aEXECUTE rui_owner_check;\x0aDEALLOCATE PREPARE rui_owner_check;\x0aALTER TABLE tool_record ADD CHECK((owner='rui' OR owner='provider' OR owner='mcp' OR owner='app'));\x0aALTER TABLE tool_record ADD COLUMN replay VARCHAR(6) NOT NULL DEFAULT '' AFTER server;\x0aALTER TABLE tool_record ALTER COLUMN replay DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN restart_limit BIGINT NOT NULL DEFAULT 0 AFTER replay;\x0aALTER TABLE tool_record ALTER COLUMN restart_limit DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN wait_ms BIGINT NOT NULL DEFAULT 0 AFTER restart_limit;\x0aALTER TABLE tool_record ALTER COLUMN wait_ms DROP DEFAULT;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,remote_name,owner,server,replay,restart_limit,wait_ms,description_content_id,input_sche