),('zai/glm-5.3-flashx-legal',1000000),('zai/glm-5v-turbo',200000),('zdev',1000000),('zhipu/glm-5.2',1000000),('zhipu/glm-5.3',1024000),('~anthropic/claude-fable-latest',1000000),('~anthropic/claude-haiku-latest',1000000),('~anthropic/claude-opus-latest',1000000),('~anthropic/claude-sonnet-latest',1000000),('~deepseek/deepseek-flash-latest',1048576),('~deepseek/deepseek-pro-latest',1048576),('~deepseek/deepseek-v4-flash-latest',1048576),('~google/gemini-flash-latest',1048576),('~google/gemini-pro-latest',1048576),('~moonshotai/kimi-latest',1048576),('~openai/gpt-astra-latest',1050000),('~openai/gpt-luna-latest',1050000),('~openai/gpt-mini-latest',400000),('~openai/gpt-sol-latest',1050000),('~openai/gpt-terra-latest',1050000),('~unbiased/pareto-latest',1048576),('~x-ai/grok-latest',500000),('~z-ai/glm-flash-latest',1048576),('~z-ai/glm-latest',1048576);\x0aALTER TABLE model_operation ADD COLUMN context_window BIGINT NULL AFTER first_event_ms;\x0aUPDATE model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision LEFT JOIN operation_window_backfill pinned ON pinned.model_id=r.model SET o.context_window=coalesce(pinned.context_window,128000);\x0aALTER TABLE model_operation MODIFY COLUMN context_window BIGINT NOT NULL, ADD CHECK(context_window BETWEEN 0 AND 4294967295);\x0aDROP TEMPORARY TABLE operation_window_backfill;\x0aUPDATE store_meta SET meta_value='14' WHERE meta_key='wire_version' AND meta_value='13';\x0aUPDATE store_meta SET meta_value='15' WHERE meta_key='wire_version' AND meta_value='14';\x0aUPDATE store_meta SET meta_value='16' WHERE meta_key='wire_version' AND meta_value='15';\x0aALTER TABLE session ADD COLUMN obligation_since BIGINT CHECK(obligation_since IS NULL OR obligation_since>0) AFTER parent_ref;\x0aALTER TABLE session ADD COLUMN session_obligation_parent_lead VARCHAR(6) GENERATED ALWAYS AS (CASE WHEN obligation_since IS NOT NULL THEN parent_ref END) STORED AFTER obligation_since, ADD INDEX session_obligation_parent(session_obligation_parent_lead,obligation_since,session_ref);\x0aCREATE INDEX session_forward_owed_message ON session_forward(target_ref,message_delivered);\x0aWITH RECURSIVE own_owed(session_ref,since) AS (SELECT t.session_ref,m.admitted_at AS since FROM turn t JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE t.outcome_code IS NULL UNION SELECT m.session_ref,m.admitted_at FROM message_admission m WHERE m.turn_id IS NULL AND m.admission_id>coalesce((SELECT admission_cutoff FROM session_stop WHERE session_ref=m.session_ref ORDER BY admission_cutoff DESC LIMIT 1),0) UNION SELECT f.target_ref,m.admitted_at FROM session_forward f LEFT JOIN action_operation a ON f.kind=1 AND a.action_id=f.source_id LEFT JOIN model_operation op ON op.operation_id=a.parent_operation_id JOIN turn t ON t.turn_id=CASE WHEN f.kind=2 THEN f.source_id ELSE op.turn_id END JOIN message_admission m ON m.admission_id=t.first_admission_id WHERE f.position IS NULL OR f.message_delivered=0),owed(session_ref,since) AS (SELECT session_ref,since FROM own_owed UNION SELECT s.parent_ref,o.since FROM owed o JOIN session s ON s.session_ref=o.session_ref WHERE s.parent_ref IS NOT NULL) UPDATE session s JOIN (SELECT session_ref,min(since) AS since FROM owed GROUP BY session_ref) o ON o.session_ref=s.session_ref SET s.obligation_since=o.since;\x0aDELETE FROM store_meta WHERE meta_key='wire_version';\x0aSET @rui_pin_kind_ddl=NULL;\x0aSET @rui_pin_kind_ddl=(SELECT CONCAT('ALTER TABLE core_command DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`, ADD CHECK(kind BETWEEN 1 AND 7)') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='core_command' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='kind between 1 and 6');\x0aPREPARE rui_pin_kin