tion_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(OCTET_LENGTH(remote_name)<=64 AND (NOT REGEXP_LIKE(remote_name,'[^A-Za-z0-9_-]','c')));\x0aALTER TABLE model_fact ADD COLUMN output_limit BIGINT AFTER generation, ADD CHECK(output_limit IS NULL OR output_limit BETWEEN 0 AND 4294967295);\x0aALTER TABLE model_operation ADD COLUMN output_limit BIGINT NOT NULL DEFAULT 32000 AFTER context_window, ADD CHECK(output_limit BETWEEN 0 AND 4294967295);\x0aSET @rui_owner_ddl=(SELECT CONCAT('ALTER TABLE tool_record DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`') FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.TABLE_SCHEMA=DATABASE() AND tc.TABLE_NAME='tool_record' AND tc.CONSTRAINT_TYPE='CHECK' AND LOWER(TRIM(REPLACE(REPLACE(REPLACE(cc.CHECK_CLAUSE,'`',''),'(',''),')','')))='owner = _utf8mb4''rui'' or owner = _utf8mb4''provider'' or owner = _utf8mb4''mcp''';\x0aPREPARE rui_owner_check FROM @rui_owner_ddl;\x0aEXECUTE rui_owner_check;\x0aDEALLOCATE PREPARE rui_owner_check;\x0aALTER TABLE tool_record ADD CHECK((owner='rui' OR owner='provider' OR owner='mcp' OR owner='app'));\x0aALTER TABLE tool_record ADD COLUMN replay VARCHAR(6) NOT NULL DEFAULT '' AFTER server;\x0aALTER TABLE tool_record ALTER COLUMN replay DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN restart_limit BIGINT NOT NULL DEFAULT 0 AFTER replay;\x0aALTER TABLE tool_record ALTER COLUMN restart_limit DROP DEFAULT;\x0aALTER TABLE tool_record ADD COLUMN wait_ms BIGINT NOT NULL DEFAULT 0 AFTER restart_limit;\x0aALTER TABLE tool_record ALTER COLUMN wait_ms DROP DEFAULT;\x0aALTER TABLE tool_record DROP INDEX name, ADD UNIQUE(name,remote_name,owner,server,replay,restart_limit,wait_ms,description_content_id,input_schema_content_id);\x0aALTER TABLE tool_record ADD CHECK(OCTET_LENGTH(replay)<=6 AND replay IN ('','unsafe','safe') AND (owner='app' AND replay<>'' OR owner<>'app' AND replay=''));\x0aALTER TABLE tool_record ADD CHECK((owner='app' AND restart_limit BETWEEN 0 AND 16 OR owner<>'app' AND restart_limit=0));\x0aALTER TABLE tool_record ADD CHECK((owner='app' AND wait_ms BETWEEN 1000 AND 3600000 OR owner<>'app' AND wait_ms=0));\x0aALTER TABLE tool_record ADD CHECK(replay<>'unsafe' OR restart_limit=0);\x0aUPDATE store_meta SET meta_value='92' WHERE meta_key='format';\x0a", "ALTER TABLE model_operation ADD COLUMN tool_set_id BIGINT AFTER history_dropped;\x0aUPDATE model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision SET o.tool_set_id=coalesce(r.loaded_tool_set_id,r.tool_set_id);\x0aALTER TABLE model_operation MODIFY tool_set_id BIGINT NOT NULL,ADD CHECK(tool_set_id>0),ADD FOREIGN KEY(tool_set_id) REFERENCES tool_set(tool_set_id);\x0aCREATE TABLE revision_effort_before_66 AS SELECT r.session_ref,r.revision,(SELECT choice.revision FROM session_revision choice LEFT JOIN session_revision before_choice ON before_choice.session_ref=choice.session_ref AND before_choice.revision=choice.revision-1 WHERE choice.session_ref=r.session_ref AND choice.revision<=r.revision AND (choice.revision=1 OR choice.model<>before_choice.model OR NOT (choice.reasoning_effort<=>before_choice.reasoning_effort) OR EXISTS(SELECT 1 FROM session_change changed WHERE changed.session_ref=choice.session_ref AND changed.revision=choice.revision AND changed.field IN ('reasoning_effort','model'))) ORDER BY choice.revision DESC LIMIT 1) AS effort_source_revision FROM session_revision r;\x0aALTER TABLE session_revision ADD COLUMN effort_source_revision BIGINT NOT NULL DEFAULT 1,ADD CHECK(effort_source_revision>0 AND effort_source_revision<=revision),ADD FOREIGN KEY(session_ref,effort_source_revision) REFERENCES session_revision(session_ref,revision);\x0aUPDATE session_revision r JOIN revision_effort_before_66 frozen ON frozen.session_ref=r.session_ref AND frozen.revision=r.revision SET r.effort_source_revision=frozen.effort_source_revision;\x0aDROP TABLE revision_effort_before_66;\x0aCREATE TABLE model_effort_before_66 AS SELECT o.operation_id,r.effort_source_revision AS effort_source_revision,(SELECT prior_effort.reasoning_effort FROM model_operation prior_effort JOIN session_revision prior_model ON prior_model.session_ref=prior_effort.session_ref AND prior_model.revision=prior_effort.settings_revision WHERE prior_effort.session_ref=o.session_ref AND prior_effort.admission_position<o.admission_position AND prior_model.model=r.model ORDER BY prior_effort.admission_position DESC LIMIT 1) AS previous_reasoning_effort,(SELECT earlier_model.reasoning_effort FROM model_operation earlier JOIN session_revision earlier_model ON earlier_model.session_ref=earlier.session_ref AND earlier_model.revision=earlier.settings_revision WHERE earlier.session_ref=o.session_ref AND earlier.admission_position<o.admission_position AND earlier_model.model=r.model ORDER BY earlier.admission_position DESC LIMIT 1) AS previous_effort_override,(s.codec='openai-responses/2' AND o.reasoning_effort IS NOT NULL AND NOT (o.reasoning_effort<=>(SELECT CASE WHEN retained.operation_id IS NOT NULL THEN retained.reasoning_effort WHEN first_effort.operation_id IS NOT NULL THEN first_effort.reasoning_effort ELSE o.reasoning_effort END FROM session effort_seed LEFT JOIN model_operation effort_base ON effort_base.operation_id=(SELECT selected.operation_id FROM model_operation selected WHERE selected.session_ref=o.session_ref AND selected.purpose=1 AND selected.resolution_code='compacted' AND selected.admission_position<o.admission_position ORDER BY selected.admission_position DESC LIMIT 1) LEFT JOIN session_revision effort_base_model ON effort_base_model.session_ref=effort_base.session_ref AND effort_base_model.revision=effort_base.settings_revision LEFT JOIN model_operation retained ON retained.operation_id=(SELECT earlier.operation_id FROM model_operation earlier JOIN session_revision earlier_model ON earlier_model.session_ref=earlier.session_ref AND earlier_model.revision=earlier.settings_revision WHERE earlier.session_ref=o.session_ref AND earlier.admission_position<o.admission_position AND earlier_model.model=r.model AND earlier.admission_position>greatest(coalesce(o.history_floor,0),CASE WHEN effort_base_model.model=r.model THEN coalesce(effort_base.history_floor,0) ELSE 0 END) AND earlier.admission_position>=CASE WHEN effort_base_model.model=r.model THEN coalesce((SELECT min(anchor.session_position) FROM model_output_item anchor WHERE anchor.operation_id=effort_base.operation_id AND anchor.item_kind=4),0) ELSE 0 END ORDER BY earlier.admission_position DESC LIMIT 1) LEFT JOIN model_operation first_effort ON first_effort.operation_id=(SELECT first.operation_id FROM model_operation first JOIN session_revision first_model ON first_model.session_ref=first.session_ref AND first_model.revision=first.settings_revision WHERE first.session_ref=o.session_ref AND first_model.model=r.model AND first.admission_position<o.admission_position ORDER BY first.admission_position LIMIT 1) WHERE effort_seed.session_ref=o.session_ref))) AS effort_update FROM model_operation o JOIN session_revision r ON r.session_ref=o.session_ref AND r.revision=o.settings_revision JOIN session s ON s.session_ref=o.session_ref;\x0aCREATE UNIQUE INDEX model_effort_before_66_key ON model_effort_before_66(operation_id);\x0aALTER TABLE model_operation ADD COLUMN effort_source_revision BIGINT NOT NULL DEFAULT 1 AFTER tool_set_id,ADD CHECK(effort_source_revision>0 AND effort_source_revision<=settings_revision),ADD COLUMN previous_reasoning_effort VARCHAR(6) AFTER effort_source_revision,ADD CHECK(previous_reasoning_effort IS NULL OR (previous_reasoning_effort='none' OR previous_reasoning_effort='low' OR previous_reasoning_effort='medium' OR previous_reasoning_effort='high' OR previous_reasoning_effort='xhigh' OR previous_reasoning_effort='max')),ADD COLUMN effort_update TINYINT NOT NULL DEFAULT 0 AFTER previous_reasoning_effort,ADD CHECK(effort_update IN (0,1) AND (effort_update=0 OR reasoning_effort IS NOT NULL)),ADD COLUMN previous_effort_override VARCHAR(6) AFTER effort_update,ADD CHECK(previous_effort_override IS NULL OR (previous_effort_override='none' OR previous_effort_override='low' OR previous_effort_override='medium' OR previous_effort_override='high' OR previous_effort_override='xhigh' OR previous_effort_override='max'));\x0aUPDATE model_operation o JOIN model_effort_before_66 frozen ON frozen.operation_id=o.operation_id SET o.effort_source_revision=frozen.effort_source_revision,o.previous_reasoning_effort=frozen.previous_reasoning_effort,o.effort_update=frozen.effort_update,o.previous_effort_override=frozen.previous_effort_override;\x0aDROP TABLE model_effort_before_66;\x0aCREATE UNIQUE INDEX model_operation_effort_source ON model_operation(operation_id,session_ref,effort_source_revision);\x0aCREATE TABLE session_change_66(\x0a session_ref VARCHAR(6) NOT NULL,\x0a position BIGINT NOT NULL,\x0a ordinal BIGINT NOT NULL,\x0a revision BIGINT NOT NULL,\x0a field VARCHAR(24) NOT NULL,\x0a changed_at BIGINT NOT NULL,\x0a provider_text TEXT,\x0a refused_operation_id BIGINT,\x0a PRIMARY KEY(session_ref,position,ordinal),\x0a UNIQUE(session_ref,revision,field),\x0a INDEX session_change_refused_operation(refused_operation_id,session_ref,revision),\x0a FOREIGN KEY(session_ref) REFERENCES session(session_ref),\x0a FOREIGN KEY(session_ref,revision) REFERENCES session_revision(session_ref,revision),\x0a CHECK(position>0),\x0a CHECK(ordinal>=0),\x0a CHECK(revision>1),\x0a CHECK((field='provider' OR field='model' OR field='instructions' OR field='tools' OR field='loaded_tools' OR field='permission_mode' OR field='output_schema' OR field='compaction_trigger' OR field='output_reservation' OR field='reasoning_effort' OR field='label' OR field='reasoning_effort_refused')),\x0a CHECK(changed_at>0),\x0a CHECK(provider_text IS NULL OR OCTET_LENGTH(provider_text)<=520),\x0a FOREIGN KEY(refused_operation_id,session_ref,revision) REFERENCES model_operation(operation_id,session_ref,effort_source_revision),\x0a CHECK((field='reasoning_effort_refused')=(provider_text IS NOT NULL)),\x0a CHECK((field='reasoning_effort_refused')=(refused_operation_id IS NOT NULL))\x0a) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;\x0aINSERT INTO session_change_66(session_ref,position,ordinal,revision,field,changed_at) SELECT session_ref,position,ordinal,revision,field,changed_at FROM session_change;\x0aDROP TABLE session_change;\x0aRENAME TABLE session_change_66 TO session_change;\x0aUPDATE store_meta SET meta_value='13' WHERE meta_key='wire_version' AND meta_value='12';\x0aALTER TABLE session_forward ADD COLUMN message_delivered TINYINT AFTER delivered_at, ADD COLUMN suppress_message TINYINT NOT NULL DEFAULT 0 AFTER message_delivered;\x0aALTER TABLE session_forward ADD CHECK(message_delivered IS NULL OR message_delivered IN (0,1)), ADD CHECK(suppress_message IN (0,1));\x0aUPDATE session_forward f JOIN session child ON child.session_ref=f.child_ref JOIN session_ending_owed e ON f.kind=2 AND e.turn_id=f.source_id AND f.target_ref=child.parent_ref SET f.message_delivered=e.delivered,f.suppress_message=e.suppress_message;\x0aINSERT INTO session_forward(forward_id,target_ref,child_ref,kind,source_id,position,ordinal,delivered_at,message_delivered,suppress_message) SELECT COALESCE((SELECT max(forward_id) FROM session_forward),0)+ROW_NUMBER() OVER(ORDER BY e.turn_id),child.parent_ref,t.session_ref,2,e.turn_id,NULL,0,NULL,e.delivered,e.suppress_message FROM session_ending_owed e JOIN turn t ON t.turn_id=e.turn_id JOIN session child ON child.session_ref=t.session_ref WHERE child.parent_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM session_forward f WHERE f.target_ref=child.parent_ref AND f.kind=2 AND f.source_id=e.turn_id);\x0aDROP TABLE session_ending_owed;\x0aCREATE INDEX session_forward_message ON session_forward(message_delivered,source_id);\x0aALTER 